INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-gokuu-den---totsugeki-hen-japan-en-by-kakkoii-v0313-~dragon-ball-z---the-legend-of-goku-1-incomplete', 'SNES', 'Dragon Ball Z - Super Gokuu Den - Totsugeki Hen (Japan) [En by Kakkoii v0.313] (~Dragon Ball Z - The Legend of Goku 1) (Incomplete)', '1994', 'RPG', 'Bandai', '1', 'Incomplete fan-translated RPG', 'Cinematic adventure/fighting hybrid covering the early Dragon Ball story.', 'Follow young Goku''s adventures with translated English text.', 'Play the DBZ: The Legend of Goku 1 English mod on SNES.', 'An early translation of Totsugeki Hen. Follow the classic story from the beginning with 16-bit sprites and tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-saiya-densetsu-japan', 'SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan)', '1992', 'RPG', 'Bandai', '1', 'Turn-based Dragon Ball RPG', 'Strategic turn-based RPG using a card-based battle system.', 'Lead the Z-fighters from the Raditz saga to the final fight with Frieza.', 'Master the cards in DBZ: Super Saiya Densetsu (Japan).', 'A deep JRPG where cards determine your speed, power, and defense. Manage your party''s Ki and explore the 16-bit Dragon Ball world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-saiya-densetsu-japan-rev-1-en-by-klepto-v096-~dragon-ball-z---legend-of-the-saiyans-incomplete', 'SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan) (Rev 1) [En by Klepto v0.96] (~Dragon Ball Z - Legend of the Saiyans) (Incomplete)', '1992', 'RPG', 'Bandai', '1', 'Incomplete fan translation', 'Strategic turn-based RPG using a card-based battle system.', 'Experience the Saiyan legend with an early English translation.', 'Play DBZ: Legend of the Saiyans in English on the SNES.', 'An early translation effort by Klepto. While not perfect, it allows fans to navigate the complex 16-bit card-based battle system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-saiya-densetsu-japan-rev-1-en-by-saiya-v099final-~dragon-ball-z---legend-of-the-saiyans', 'SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan) (Rev 1) [En by Saiya v0.99Final] (~Dragon Ball Z - Legend of the Saiyans)', '1992', 'RPG', 'Bandai', '1', 'Fan-translated RPG', 'Strategic turn-based RPG using a card-based battle system.', 'Experience the Saiyan legend with the definitive English translation.', 'The complete DBZ: Legend of the Saiyans translation on SNES.', 'The best way to play this 16-bit RPG. Follow the story of Goku and Vegeta with fully translated dialogue and a perfectly explained card system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---super-saiya-densetsu-japan-rev-a', 'SNES', 'Dragon Ball Z - Super Saiya Densetsu (Japan) (Rev A)', '1992', 'RPG', 'Bandai', '1', 'Revised original version', 'Strategic turn-based RPG using a card-based battle system.', 'Lead the Z-fighters to victory in the refined Rev A version.', 'Play the polished DBZ: Super Saiya Densetsu (Rev A) on SNES.', 'An official revision that fixed game-breaking bugs and balanced the encounter rates for a better 16-bit RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---ultime-menace-france', 'SNES', 'Dragon Ball Z - Ultime Menace (France)', '1994', 'Fighting', 'Bandai', '2', 'European version of anime fighter', 'The French release of Super Butouden 3, covering the Majin Buu era.', 'Defeat the ultimate menace in this 16-bit fighting classic.', 'Experience DBZ: Ultime Menace on the Super Nintendo.', 'The official European (French) version. Features the same high-speed combat and iconic DBZ characters in a polished 16-bit format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---ultime-menace-france-en-by-aeon-genesis-v10-~dragon-ball-z---super-butouden-3-incomplete', 'SNES', 'Dragon Ball Z - Ultime Menace (France) [En by Aeon Genesis v1.0] (~Dragon Ball Z - Super Butouden 3) (Incomplete)', '1994', 'Fighting', 'Bandai', '2', 'Incomplete fan translation', 'The French release of Super Butouden 3, covering the Majin Buu era.', 'Experience the final Butouden battle with English text.', 'Play the DBZ: Ultime Menace English translation on SNES.', 'An Aeon Genesis project that translates the menus and victory quotes, making this 16-bit brawler fully accessible to Western fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-ball-z---ultime-menace-france-en-by-saiya+vice-v11-~dragon-ball-z---super-butouden-3-incomplete', 'SNES', 'Dragon Ball Z - Ultime Menace (France) [En by Saiya+Vice v1.1] (~Dragon Ball Z - Super Butouden 3) (Incomplete)', '1994', 'Fighting', 'Bandai', '2', 'Incomplete fan translation', 'The French release of Super Butouden 3, covering the Majin Buu era.', 'Experience the final Butouden battle with English text.', 'Play the DBZ: Ultime Menace English translation (Saiya+Vice).', 'Another high-quality translation effort for the third Butouden game, ensuring fans can enjoy the 16-bit tournament action in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-knight-4-japan', 'SNES', 'Dragon Knight 4 (Japan)', '1994', 'Adventure', 'Elf', '1', 'Story-driven visual novel RPG', 'Tactical turn-based RPG with a focus on adult-oriented storytelling.', 'Lead your army to victory and uncover the secrets of the Dragon Knight.', 'Experience the epic Dragon Knight 4 on the Super Famicom.', 'A deep tactical RPG featuring large-scale battles and a multi-generational story. Manage your units across a grid-based battlefield in this visually detailed 16-bit Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-i-&-ii-japan', 'SNES', 'Dragon Quest I & II (Japan)', '1993', 'RPG', 'Chunsoft', '1', 'Turn-based fantasy RPG compilation', 'Remake of the first two legendary JRPGs with updated 16-bit graphics.', 'Defeat the Dragonlord and Hargon to restore peace to Alefgard.', 'Play the Dragon Quest I & II collection on the SNES.', 'A beautiful 16-bit overhaul of the NES originals. Experience the foundations of the JRPG genre with improved music, smoother gameplay, and refined inventory systems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-i-&-ii-japan-en-by-rpgone-v20-dragon-quest-version', 'SNES', 'Dragon Quest I & II (Japan) [En by RPGOne v2.0] (Dragon Quest Version)', '1993', 'RPG', 'Chunsoft', '1', 'Fan-translated classic RPG compilation', 'Remake of the first two legendary JRPGs with a faithful fan translation.', 'Experience the origins of the series with the "Quest" terminology.', 'Play Dragon Quest I & II in English on the Super Nintendo.', 'The RPGOne translation provides a modern, faithful script. Relive the epic journey of the descendants of Erdrick with beautiful 16-bit sprites and fully translated menus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-i-&-ii-japan-en-by-rpgone-v20-dragon-warrior-version', 'SNES', 'Dragon Quest I & II (Japan) [En by RPGOne v2.0] (Dragon Warrior Version)', '1993', 'RPG', 'Chunsoft', '1', 'Fan-translated classic RPG compilation', 'Remake of the first two legendary JRPGs with "Dragon Warrior" terminology.', 'Defeat the Dragonlord in this nostalgic NES-style translation.', 'Play Dragon Warrior I & II in English on the SNES.', 'A special version of the RPGOne translation that uses the classic 8-bit Western names and terms, bringing 16-bit polish to your childhood memories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-iii---soshite-densetsu-e-japan-en-by-damarsman-v10-~dragon-quest-iii---into-the-legend', 'SNES', 'Dragon Quest III - Soshite Densetsu e... (Japan) [En by DaMarsMan v1.0] (~Dragon Quest III - Into the Legend)', '1996', 'RPG', 'Chunsoft', '1', 'Fan-translated epic turn-based RPG', 'One of the most ambitious JRPGs ever made, featuring a deep class system.', 'Assemble a party of heroes to defeat the archfiend Baramos.', 'Play the legendary Dragon Quest III remake in English on SNES.', 'The definitive version of a masterpiece. Features a personality system, beautiful 16-bit animations, and a massive world that sets the standard for the entire genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-iii---soshite-densetsu-he-japan', 'SNES', 'Dragon Quest III - Soshite Densetsu he... (Japan)', '1996', 'RPG', 'Chunsoft', '1', 'Epic turn-based fantasy RPG', 'One of the most ambitious JRPGs ever made, featuring a deep class system.', 'Assemble a party of heroes to defeat the archfiend Baramos.', 'Experience the original Dragon Quest III on Super Famicom.', 'A technical marvel for the system. Build your own party from scratch and explore a world filled with secrets, day/night cycles, and the iconic 16-bit "Pachisi" board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-v---tenkuu-no-hanayome-japan', 'SNES', 'Dragon Quest V - Tenkuu no Hanayome (Japan)', '1992', 'RPG', 'Chunsoft', '1', 'Story-driven turn-based RPG', 'The first Dragon Quest on SNES, featuring a story that spans generations.', 'Choose a bride and raise a family of heroes to defeat Nimzo.', 'Experience the emotional Dragon Quest V on the SNES.', 'A groundbreaking JRPG where you follow the protagonist from childhood to parenthood. Master the monster-recruitment system in this beautifully written 16-bit epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-v---tenkuu-no-hanayome-japan-en-by-byuu+spspiff-v091-~dragon-quest-v---bride-of-heaven', 'SNES', 'Dragon Quest V - Tenkuu no Hanayome (Japan) [En by Byuu+spSpiff v0.91] (~Dragon Quest V - Bride of Heaven)', '1992', 'RPG', 'Chunsoft', '1', 'Fan-translated narrative RPG', 'The first Dragon Quest on SNES, featuring a story that spans generations.', 'Experience the "Bride of Heaven" story with an English translation.', 'Play Dragon Quest V in English on the Super Nintendo.', 'A dedicated fan translation by Byuu and Spiff. Follow the hero''s life-long journey with fully translated dialogue and a refined 16-bit interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-v---tenkuu-no-hanayome-japan-en-by-dejap+partial-v201final-~dragon-quest-v---bride-of-heaven', 'SNES', 'Dragon Quest V - Tenkuu no Hanayome (Japan) [En by DeJap+Partial v2.01Final] (~Dragon Quest V - Bride of Heaven)', '1992', 'RPG', 'Chunsoft', '1', 'Fan-translated definitive edition', 'The first Dragon Quest on SNES, featuring a story that spans generations.', 'Experience the "Bride of Heaven" story with an English translation.', 'Enjoy the DeJap translation of Dragon Quest V on SNES.', 'One of the most famous fan translations in the scene. Experience the complete narrative and monster-taming mechanics of this 16-bit masterpiece in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-vi---maboroshi-no-daichi-japan', 'SNES', 'Dragon Quest VI - Maboroshi no Daichi (Japan)', '1995', 'RPG', 'Chunsoft', '1', 'Classic turn-based RPG', 'The final 16-bit Dragon Quest, featuring a massive dual-world system.', 'Travel between the Dream World and Reality to stop Deathtamoor.', 'Explore two worlds in Dragon Quest VI for the SNES.', 'A visual and technical peak for the series. Features a complex job system and an epic story that weaves through two massive 16-bit world maps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-quest-vi---maboroshi-no-daichi-japan-en-by-noprgress-v090beta2-~dragon-quest-vi---land-of-illusion', 'SNES', 'Dragon Quest VI - Maboroshi no Daichi (Japan) [En by NoPrgress v0.90Beta2] (~Dragon Quest VI - Land of Illusion)', '1995', 'RPG', 'Chunsoft', '1', 'Fan-translated RPG', 'The final 16-bit Dragon Quest, featuring a massive dual-world system.', 'Uncover the truth of the "Land of Illusion" with English text.', 'Play the Dragon Quest VI English fan translation on SNES.', 'A monumental translation effort that allows Western players to experience the deep class system and reality-bending story of the final 16-bit DQ title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-slayer---eiyuu-densetsu-japan', 'SNES', 'Dragon Slayer - Eiyuu Densetsu (Japan)', '1992', 'RPG', 'Nihon Falcom', '1', 'Story-focused fantasy RPG', 'Traditional turn-based RPG and the origin of the "Legend of Heroes" series.', 'Lead Prince Selios on a quest to reclaim his kingdom.', 'Discover the classic Dragon Slayer: Eiyuu Densetsu on SNES.', 'A foundational JRPG with a focus on party management and exploration. Experience the roots of Falcom’s legendary series with polished 16-bit visuals and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-slayer---eiyuu-densetsu-japan-rev-a-np', 'SNES', 'Dragon Slayer - Eiyuu Densetsu (Japan) (Rev A) (NP)', '1992', 'RPG', 'Nihon Falcom', '1', 'Revised fantasy RPG release', 'Traditional turn-based RPG and the origin of the "Legend of Heroes" series.', 'Lead Prince Selios on a quest to reclaim his kingdom.', 'Play the refined Dragon Slayer (Rev A) on the SNES.', 'The Nintendo Power revision of the classic Falcom RPG. Features minor bug fixes and balanced encounter rates for a more consistent 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-slayer---eiyuu-densetsu-ii-japan', 'SNES', 'Dragon Slayer - Eiyuu Densetsu II (Japan)', '1994', 'RPG', 'Nihon Falcom', '1', 'Sequel story-driven RPG', 'The epic sequel featuring a new generation of heroes and a vast world.', 'Defeat the mysterious "Emperor" and restore the light to the world.', 'Experience the sequel Dragon Slayer II on the Super Famicom.', 'Improves upon the original with more complex tactical battles and a deeper narrative. A must-play for fans of classic 16-bit JRPG progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragon-view-usa', 'SNES', 'Dragon View (USA)', '1995', 'Action RPG', 'Kemco', '1', 'Isometric action RPG', 'Action-RPG with a unique hybrid perspective of side-scrolling and 3D.', 'Stop the resurrection of a dark god in the world of Keire.', 'Embark on a quest in Dragon View for the Super Nintendo.', 'A spiritual successor to Drakkhen. Features a 3D overworld and fluid side-scrolling combat, offering a unique and atmospheric 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-earth-japan', 'SNES', 'Dragon''s Earth (Japan)', '1993', 'Action', 'Technosoft', '1', 'Dark fantasy action adventure', 'Real-time strategy game with a focus on resource and unit management.', 'Conquer the dragon-infested lands by building a powerful army.', 'Master the strategy of Dragon''s Earth on the SNES.', 'A rare 16-bit RTS where you manage troops and combat mythical creatures. Features a clean interface and challenging AI for fans of tactical gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-lair-europe-beta', 'SNES', 'Dragon''s Lair (Europe) (Beta)', '1993', 'Action', 'Crawfish Interactive', '1', 'Animated arcade-style action', 'Side-scrolling action platformer based on the famous laserdisc game.', 'Rescue Princess Daphne from the dragon Singe in the wizard''s castle.', 'Test your reflexes in the Dragon''s Lair Beta on SNES.', 'A pre-release version of the challenging platformer. Discover early level designs and timing windows used during the development of this 16-bit cinematic adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-lair-europe-enfrdeesitnlsv', 'SNES', 'Dragon''s Lair (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1993', 'Action', 'Crawfish Interactive', '1', 'Laserdisc-style animated adventure', 'Side-scrolling action platformer based on the famous laserdisc game.', 'Rescue Princess Daphne from the dragon Singe in the wizard''s castle.', 'Face the danger of Dragon''s Lair for the Super Nintendo.', 'A reimagining of the arcade classic as a traditional platformer. Navigate a castle full of traps and monsters with high-quality 16-bit animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-lair-usa', 'SNES', 'Dragon''s Lair (USA)', '1993', 'Action', 'Crawfish Interactive', '1', 'Laserdisc-style animated adventure', 'Side-scrolling action platformer based on the famous laserdisc game.', 'Rescue Princess Daphne from the dragon Singe in the wizard''s castle.', 'Face the danger of Dragon''s Lair for the Super Nintendo.', 'Known for its high difficulty and detailed character sprites. Master the precision jumps and weapon usage to survive the 16-bit dragon''s lair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dragons-magic-japan', 'SNES', 'Dragon''s Magic (Japan)', '1991', 'Action', 'Ray Force', '1', 'Fantasy action platformer', 'Falling-block puzzle game with a magical theme.', 'Clear the screen by matching mystical orbs and gems.', 'Solve the puzzles of Dragon''s Magic on the Super Famicom.', 'A colorful and fast-paced 16-bit puzzler. Use special magical abilities to clear the board and compete against challenging AI or a second player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drakkhen-europe', 'SNES', 'Drakkhen (Europe)', '1989', 'RPG', 'Infogrames', '1', 'Early 3D-style RPG', 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Experience the surreal world of Drakkhen on the SNES.', 'A cult classic known for its eerie atmosphere and open-world exploration. Manage a party of four through a 3D-rendered landscape in this unique 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drakkhen-germany', 'SNES', 'Drakkhen (Germany)', '1989', 'RPG', 'Infogrames', '1', 'Early 3D-style RPG', 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Experience the surreal world of Drakkhen on the SNES.', 'The German localization of the innovative RPG. Experience the mysterious lore and challenging 3D navigation with fully translated text for the 16-bit console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drakkhen-japan', 'SNES', 'Drakkhen (Japan)', '1990', 'RPG', 'Infogrames', '1', 'Early polygonal RPG', 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Explore the Japanese version of Drakkhen on the SNES.', 'The original Japanese release, featuring the same haunting soundtrack and groundbreaking 3D-style overworld that defined this experimental 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drakkhen-usa', 'SNES', 'Drakkhen (USA)', '1989', 'RPG', 'Infogrames', '1', 'Early 3D dungeon RPG', 'Innovative 3D exploration RPG with a unique hybrid perspective.', 'Retrieve the eight dragon tears to save the world of Drakkhen.', 'Explore the mysterious world of Drakkhen on the SNES.', 'One of the earliest examples of a 3D world on home consoles. Master the complex UI and survive the strange creatures of the 16-bit night.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-basketball---dunk-&-hoop-japan', 'SNES', 'Dream Basketball - Dunk & Hoop (Japan)', '1994', 'Sports', 'Human Entertainment', '2', 'Arcade-style basketball', 'Arcade-style basketball game featuring high-energy dunks.', 'Win the tournament by outscoring rival teams with flashy plays.', 'Hit the court in Dream Basketball: Dunk & Hoop for SNES.', 'A fast-paced 16-bit sports game with a focus on arcade fun. Execute spectacular dunks and master the timing-based shooting system to become the champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-maze---kigurumi-daibouken-japan-en-by-kingmike-v10b-~dream-maze---the-kigurumi-adventure', 'SNES', 'Dream Maze - Kigurumi Daibouken (Japan) [En by KingMike v1.0b] (~Dream Maze - The Kigurumi Adventure)', '1994', 'Platformer', 'Naxat Soft', '1', 'Fan-translated fantasy platformer', 'First-person dungeon crawler where characters wear animal costumes.', 'Navigate the "Dream Maze" to save the world of fantasy.', 'Explore the Dream Maze in English on the Super Nintendo.', 'A quirky 16-bit dungeon crawler translated by KingMike. Use different "Kigurumi" (animal suits) to gain powers and explore colorful first-person labyrinths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-tv-usa', 'SNES', 'Dream TV (USA)', '1992', 'Edutainment', 'Loriciel', '4', 'TV game show mini-games', 'Action-puzzle game set inside a surreal television world.', 'Navigate through various "channels" to find the exit and escape the TV.', 'Escape the nightmare in Dream TV for the Super Nintendo.', 'A unique 16-bit title where you switch between two characters to solve puzzles. Explore diverse stages based on TV genres while avoiding traps and enemies in this surreal adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-tv-usa-beta1', 'SNES', 'Dream TV (USA) (Beta1)', '1992', 'Edutainment', 'Loriciel', '4', 'Beta TV game show mini-games', 'Action-puzzle game set inside a surreal television world.', 'Explore the early channel designs and experimental mechanics.', 'Check out the Dream TV Beta 1 version on the SNES.', 'An early development build of the TV-themed puzzle-platformer. Discover initial level layouts and mechanical concepts that were being tested for the 16-bit retail release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dream-tv-usa-beta2', 'SNES', 'Dream TV (USA) (Beta2)', '1992', 'Edutainment', 'Loriciel', '4', 'Beta TV game show mini-games', 'Action-puzzle game set inside a surreal television world.', 'Explore the early channel designs and experimental mechanics.', 'Check out the Dream TV Beta 2 version on the SNES.', 'A later development build featuring refined character controls and more complete stage designs compared to the first beta of this 16-bit puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drift-king-shutokou-battle-94---tsuchiya-keiichi-&-bandou-masaaki-japan', 'SNES', 'Drift King Shutokou Battle ''94 - Tsuchiya Keiichi & Bandou Masaaki (Japan)', '1994', 'Racing', 'Genki', '1', 'Street drifting racing simulation', 'Street racing simulation featuring the legendary "Drift King" Keiichi Tsuchiya.', 'Win the Shutokou highway races and become the king of drifting.', 'Experience the drift culture in Drift King Shutokou Battle ''94.', 'A foundational title for fans of Japanese car culture. Master the art of drifting on the Tokyo expressway using Mode 7 16-bit graphics and realistic car physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('drift-king-shutokou-battle-2---tsuchiya-keiichi-&-bandou-masaaki-japan', 'SNES', 'Drift King Shutokou Battle 2 - Tsuchiya Keiichi & Bandou Masaaki (Japan)', '1995', 'Racing', 'Genki', '1', 'Street drifting racing sequel', 'Street racing simulation with enhanced tuning and more car models.', 'Defeat the highway racing gangs and maintain your title as Drift King.', 'Master the drift in Drift King Shutokou Battle 2 on SNES.', 'Includes more customization and a deeper career mode. Fine-tune your machine to handle the tightest corners of the 16-bit Japanese highways.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-orb---seirei-tama-densetsu-japan', 'SNES', 'Dual Orb - Seirei Tama Densetsu (Japan)', '1992', 'RPG', 'I''MAX', '1', 'Totsa-inspired turn-based RPG', 'Traditional turn-based JRPG with a focus on elemental spirits.', 'Journey across the land to collect the powerful Spirit Orbs.', 'Discover the classic RPG Dual Orb on the Super Famicom.', 'A polished 16-bit Japanese exclusive featuring beautiful character portraits and a classic world-saving narrative for fans of the golden age of JRPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-orb-ii-japan', 'SNES', 'Dual Orb II (Japan)', '1994', 'RPG', 'I''MAX', '1', 'Turn-based fantasy RPG sequel', 'Visually stunning turn-based JRPG with cinematic battle animations.', 'Protect the world from an ancient evil alongside a cast of unique heroes.', 'Experience the epic Dual Orb II on the Super Famicom.', 'Known for its incredible 16-bit graphics and dynamic camera angles during combat. A hidden gem with an emotional story and a deep magic system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dual-orb-ii-japan-en-by-transcorp-v15', 'SNES', 'Dual Orb II (Japan) [En by TransCorp v1.5]', '1994', 'RPG', 'I''MAX', '1', 'Fan-translated fantasy RPG', 'Visually stunning turn-based JRPG with cinematic battle animations.', 'Experience the epic Dual Orb II story with a full English translation.', 'Play Dual Orb II in English on the Super Nintendo.', 'The definitive fan translation by TransCorp. Now Western players can enjoy the cinematic 16-bit combat and deep lore of this Japanese RPG masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-the---test-drive-ii-europe', 'SNES', 'Duel, The - Test Drive II (Europe)', '1990', 'Racing', 'Accolade', '1', 'Open-world driving simulation', 'First-person driving simulation featuring high-performance sports cars.', 'Outrun the police and your opponent in a high-speed cross-country race.', 'Test your driving skills in The Duel: Test Drive II for SNES.', 'Choose between legendary cars like the Porsche 959 and Ferrari F40. Features realistic cockpit views and challenging 16-bit mountain road navigation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duel-the---test-drive-ii-usa', 'SNES', 'Duel, The - Test Drive II (USA)', '1990', 'Racing', 'Accolade', '1', 'Open-world driving simulation', 'First-person driving simulation featuring high-performance sports cars.', 'Outrun the police and your opponent in a high-speed cross-country race.', 'Test your driving skills in The Duel: Test Drive II for SNES.', 'A classic simulation focusing on speed and avoidance. Watch your tachometer and avoid road hazards in this pioneering 16-bit racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dun-quest---majin-fuuin-no-densetsu-japan', 'SNES', 'Dun Quest - Majin Fuuin no Densetsu (Japan)', '1995', 'RPG', 'Pandora Box', '1', 'Classic turn-based dungeon RPG', 'First-person dungeon crawler with turn-based combat and riddles.', 'Seal the ancient demon by navigating a perilous labyrinth.', 'Conquer the maze in Dun Quest for the Super Famicom.', 'A traditional "blobber" style RPG. Manage your party''s resources and map out complex 16-bit floors while battling mythological monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-master-europe', 'SNES', 'Dungeon Master (Europe)', '1992', 'RPG', 'FTL Games', '1', 'Real-time dungeon crawler', 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Experience the classic Dungeon Master on the Super Nintendo.', 'A revolutionary RPG that introduced real-time interaction. Manage hunger, thirst, and light while casting spells in a claustrophobic 16-bit environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-master-japan', 'SNES', 'Dungeon Master (Japan)', '1992', 'RPG', 'FTL Games', '1', 'Real-time dungeon crawler', 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Explore the Japanese version of Dungeon Master on SNES.', 'The localized release of the Western RPG hit. Features the same deep mechanics and atmospheric 16-bit dungeon crawling that defined the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-master-japan-rev-a', 'SNES', 'Dungeon Master (Japan) (Rev A)', '1992', 'RPG', 'FTL Games', '1', 'Revised dungeon crawler', 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Play the refined Dungeon Master (Rev A) on the SNES.', 'The updated Japanese revision featuring minor bug fixes and UI improvements for a more stable 16-bit dungeoneering experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dungeon-master-usa', 'SNES', 'Dungeon Master (USA)', '1992', 'RPG', 'FTL Games', '1', 'Real-time dungeon crawler', 'Pioneering first-person dungeon crawler with real-time combat.', 'Navigate the deep dungeon to defeat the evil wizard Lord Chaos.', 'Master the spells in Dungeon Master for the Super Nintendo.', 'One of the most immersive RPGs of its time. Master the rune-based magic system and solve environmental puzzles to survive the 16-bit darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamaite-the-las-vegas-japan', 'SNES', 'Dynamaite the Las Vegas (Japan)', '1995', 'Action', 'Naxat Soft', '1', 'Top-down action shooter', 'Casino simulation featuring various gambling games in Las Vegas.', 'Win big at the tables and become a high-roller in Vegas.', 'High stakes fun in Dynamaite the Las Vegas for SNES.', 'Includes poker, blackjack, and slot machines. Features a vibrant 16-bit casino atmosphere with unique character interactions and gambling challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynamic-stadium-japan', 'SNES', 'Dynamic Stadium (Japan)', '1993', 'Sports', 'Electronic Arts', '2', 'Baseball stadium simulation', 'Arcade-style baseball simulation with a focus on dynamic action.', 'Lead your team to victory in a high-energy baseball tournament.', 'Step up to the plate in Dynamic Stadium for the Super Famicom.', 'A fast-paced 16-bit baseball game. Features smooth animations and intuitive controls, making it accessible for both casual and hardcore sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evo---search-for-eden-usa', 'SNES', 'E.V.O. - Search for Eden (USA)', '1995', 'Action RPG', 'Almanic', '1', 'Evolution-themed action RPG', 'Side-scrolling action-RPG where you guide a creature through evolution.', 'Evolve from a simple fish to a complex mammal to reach Eden.', 'Experience the unique E.V.O. Search for Eden on the SNES.', 'A cult classic by Enix. Earn evolution points to customize your creature’s body parts, adapting to survive different 16-bit prehistoric eras.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earth-light---luna-strike-japan', 'SNES', 'Earth Light - Luna Strike (Japan)', '1994', 'Strategy RPG', 'Hudson Soft', '1', 'Sci-fi tactical RPG', 'Turn-based tactical mecha strategy game set in a futuristic lunar war.', 'Command your unit of mechs to defeat the invading lunar forces.', 'Master the tactics of Earth Light: Luna Strike on SNES.', 'The sequel to Earth Light, featuring refined hex-based combat, improved 16-bit visuals, and a more complex branching mission structure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earth-light-japan', 'SNES', 'Earth Light (Japan)', '1994', 'Strategy RPG', 'Hudson Soft', '1', 'Sci-fi tactical RPG', 'Turn-based tactical mecha strategy game featuring hex-based combat.', 'Defeat enemy forces using a variety of specialized mechs and units.', 'Experience the strategic Earth Light on the Super Famicom.', 'A hidden gem of the strategy genre. Utilize terrain and unit positioning to win intense 16-bit battles in this beautifully animated sci-fi title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-mar-27-1995-prototype', 'SNES', 'EarthBound (Mar 27, 1995 prototype)', '1995', 'RPG', 'Ape Inc.', '1', 'Prototype narrative RPG', 'Legendary modern-day JRPG featuring a boy with psychic powers.', 'Discover a pre-release version of the game with subtle differences.', 'Check out the rare EarthBound Prototype for the SNES.', 'A fascinating look at the localization process. Features minor text variations and early translations of the 16-bit masterpiece known as Mother 2.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa', 'SNES', 'EarthBound (USA)', '1995', 'RPG', 'Ape Inc.', '1', 'Modern surreal turn-based RPG', 'Legendary modern-day JRPG known for its quirky humor and charm.', 'Travel the world with your friends to stop the cosmic destroyer Giygas.', 'Experience the cult classic EarthBound on the Super Nintendo.', 'A unique RPG set in a modern world. Fight hippies and street signs, use psychic powers, and enjoy a brilliant 16-bit story about friendship and courage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa-hack-by-blue-antoid-v20-~jonbound---dark-future', 'SNES', 'EarthBound (USA) [Hack by Blue Antoid v2.0] (~JonBound - Dark Future)', '1995', 'RPG', 'Ape Inc.', '1', 'Dark future story hack', 'Dark and gritty fan-made reimagining of the EarthBound universe.', 'Navigate a post-apocalyptic future to change the fate of the world.', 'Explore the dark EarthBound: JonBound - Dark Future mod.', 'A total conversion hack featuring new graphics, a darker narrative tone, and a revamped 16-bit difficulty for veterans of the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa-hack-by-ebgirl-v25-~mother-25---the-giftman-chronicles', 'SNES', 'EarthBound (USA) [Hack by EBGirl v2.5] (~Mother 2.5 - The Giftman Chronicles)', '1995', 'RPG', 'Ape Inc.', '1', 'Fan-made sequel-style hack', 'Holiday-themed fan expansion featuring new characters and story.', 'Help Giftman save the holiday season in the world of Mother.', 'Play EarthBound: The Giftman Chronicles on the Super Nintendo.', 'A charming hack that replaces the main cast and adds a festive story, new items, and 16-bit winter-themed environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa-hack-by-michael-cayer+tomato-v20-new-game-plus-plus', 'SNES', 'EarthBound (USA) [Hack by Michael Cayer+Tomato v2.0] (New Game Plus Plus)', '1995', 'RPG', 'Ape Inc.', '1', 'New Game Plus hack', 'Enhanced version of the original game with a "New Game Plus" feature.', 'Relive the journey with your endgame stats and new challenges.', 'Experience EarthBound New Game Plus Plus on the SNES.', 'Allows players to restart the story with their previous levels and equipment. Features rebalanced 16-bit enemies to keep the challenge fresh.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa-hack-by-mr-accident-v11-~earthbound---10th-anniversary-celebration', 'SNES', 'EarthBound (USA) [Hack by Mr. Accident v1.1] (~EarthBound - 10th Anniversary Celebration)', '1995', 'RPG', 'Ape Inc.', '1', 'Anniversary content hack', 'Comprehensive mod celebrating the legacy of the series.', 'Experience a refined version of the classic game with new secrets.', 'Celebrate EarthBound with the 10th Anniversary hack.', 'Features numerous quality-of-life improvements, restored Japanese content, and subtle 16-bit graphical touch-ups for the ultimate fan experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa-hack-by-mr-tenda-v0908-~mr-saturn-in-hat-quest', 'SNES', 'EarthBound (USA) [Hack by Mr. Tenda v0.908] (~Mr. Saturn in Hat Quest)', '1995', 'RPG', 'Ape Inc.', '1', 'Character-focused story hack', 'Quirky fan-adventure starring the iconic Mr. Saturn.', 'Embark on a small but strange quest as a resident of Saturn Valley.', 'Play as a Mr. Saturn in Hat Quest on the Super Nintendo.', 'A humorous and creative hack that focuses on the weirdest characters in the series. Navigate 16-bit puzzles with the unique perspective of a Mr. Saturn.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa-hack-by-radiation-v102-~arns-winter-quest---gway-edition', 'SNES', 'EarthBound (USA) [Hack by Radiation v1.02] (~Arn''s Winter Quest - Gway Edition)', '1995', 'RPG', 'Ape Inc.', '1', 'Winter-themed quest hack', 'Atmospheric fan-sequel following Arn on a cold and mysterious journey.', 'Survive the winter and uncover the secrets of a new 16-bit world.', 'Play Arn''s Winter Quest - Gway Edition on the SNES.', 'Created by "Radiation" (Toby Fox). A legendary hack known for its unique music, somber atmosphere, and innovative use of the 16-bit EarthBound engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-usa-hack-by-rofish-v050-~earthbound-battler-battle-mode', 'SNES', 'EarthBound (USA) [Hack by Rofish v0.50] (~EarthBound Battler) (Battle Mode)', '1995', 'RPG', 'Ape Inc.', '1', 'Battle-focused mode hack', 'Combat-only mod that focuses entirely on the battle system.', 'Defeat waves of enemies in a specialized battle arena.', 'Test your combat skills in EarthBound Battler on the SNES.', 'Skip the exploration and dive straight into the 16-bit turn-based combat. Features a gauntlet of bosses and enemies to challenge your tactical mastery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthbound-randomizer', 'SNES', 'EarthBound Randomizer', '1995', 'RPG', 'Ape Inc.', '1', 'Procedurally randomized RPG', 'A procedural generation mod that reshuffles the entire game.', 'Complete the game with randomized items, enemies, and stats.', 'Experience the chaos of the EarthBound Randomizer on SNES.', 'Every playthrough is unique! Items, gift boxes, and enemy encounters are shuffled, forcing players to adapt their 16-bit strategy on the fly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-europe', 'SNES', 'Earthworm Jim (Europe)', '1994', 'Platformer', 'Shiny Entertainment', '1', 'Physics-based cartoon platformer', 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name from the evil Psy-Crow.', 'Experience the wacky world of Earthworm Jim on SNES.', 'A masterpiece of 16-bit animation. Control Jim, a worm in a super-suit, through bizarre levels like "New Junk City." Use your head as a whip and blast enemies with high-tech blasters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-japan', 'SNES', 'Earthworm Jim (Japan)', '1994', 'Platformer', 'Shiny Entertainment', '1', 'Physics-based cartoon platformer', 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name from the evil Psy-Crow.', 'Play the Japanese version of Earthworm Jim on the SNES.', 'The Super Famicom release of the cult classic. Features the same fluid 16-bit animations and eccentric humor that made Jim a global gaming icon in the 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-usa', 'SNES', 'Earthworm Jim (USA)', '1994', 'Platformer', 'Shiny Entertainment', '1', 'Physics-based cartoon platformer', 'Surreal side-scrolling platformer with run-and-gun elements.', 'Rescue Princess What''s-Her-Name from the evil Psy-Crow.', 'Play the definitive Earthworm Jim on the Super Nintendo.', 'Battle through surreal environments with a groovy soundtrack. Master the helicopter-head spin and the "Andy Asteroids" racing levels in this peak 16-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-usa-gamesmaster-special-edition', 'SNES', 'Earthworm Jim (USA) (GamesMaster Special Edition)', '1994', 'Platformer', 'Shiny Entertainment', '1', 'Special edition platformer', 'Timed score-attack version of the classic platformer.', 'Achieve the highest score in specific levels within a time limit.', 'Play the Earthworm Jim GamesMaster Special Edition.', 'A rare promotional version used for the UK TV show GamesMaster. It features a timer and scoring system, challenging players to speedrun through 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2-europe', 'SNES', 'Earthworm Jim 2 (Europe)', '1995', 'Platformer', 'Shiny Entertainment', '2', 'Fast-paced cartoon platformer', 'Absurdist side-scrolling platformer with diverse gameplay styles.', 'Rescue the Princess again and defeat the evil Psy-Crow.', 'Groovy! Play Earthworm Jim 2 on the Super Nintendo.', 'More creative and weirder than the first. Features levels ranging from digging through dirt to flying a giant balloon. A visual and musical 16-bit tour de force.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2-usa', 'SNES', 'Earthworm Jim 2 (USA)', '1995', 'Platformer', 'Shiny Entertainment', '2', 'Fast-paced cartoon platformer', 'Absurdist side-scrolling platformer with diverse gameplay styles.', 'Rescue the Princess again and defeat the evil Psy-Crow.', 'Groovy! Play Earthworm Jim 2 on the Super Nintendo.', 'Utilize new weapons and "Snott" the backpack parasite. This sequel pushes the SNES to its limits with incredible 16-bit sprite work and hilarious scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2-usa-beta', 'SNES', 'Earthworm Jim 2 (USA) (Beta)', '1995', 'Platformer', 'Shiny Entertainment', '2', 'Beta sequel platformer', 'Absurdist side-scrolling platformer with diverse gameplay styles.', 'Rescue the Princess again and defeat the evil Psy-Crow.', 'Explore the Earthworm Jim 2 Beta on the Super Nintendo.', 'A pre-release build featuring early level concepts and music tracks. See how the 16-bit madness was refined before the final release of this iconic sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('edono-kiba-japan', 'SNES', 'Edono Kiba (Japan)', '1995', 'Action RPG', 'Studio Pierrot', '1', 'Japanese folklore action RPG', 'Cyberpunk side-scrolling beat ''em up and action game.', 'Defeat the rogue machines and clean up the futuristic streets.', 'Battle in the cyberpunk world of Edono Kiba for SNES.', 'Set in a futuristic Tokyo (Edo). Features large character sprites and fast-paced 16-bit combat. Use your sword to slice through cybernetic enemies in this atmospheric Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eek!-the-cat-europe', 'SNES', 'Eek! The Cat (Europe)', '1994', 'Platformer', 'Radium', '1', 'Slapstick cartoon platformer', 'Puzzle-platformer based on the animated series about a clumsy cat.', 'Protect the clumsy family members from hazards as they walk.', 'Join the misadventures in Eek! The Cat for the SNES.', 'Help Eek clear the path for the Sleepy family. Use Eek''s resilience to take hits and move objects in this colorful and humorous 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eek!-the-cat-usa', 'SNES', 'Eek! The Cat (USA)', '1994', 'Platformer', 'Radium', '1', 'Slapstick cartoon platformer', 'Puzzle-platformer based on the animated series about a clumsy cat.', 'Protect the clumsy family members from hazards as they walk.', 'Join the misadventures in Eek! The Cat for the SNES.', 'Navigate through levels inspired by the cartoon. A unique 16-bit escort-puzzle game where your patience and timing are tested to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eien-no-filerna-japan', 'SNES', 'Eien no Filerna (Japan)', '1995', 'RPG', 'Taito', '1', 'Dark fantasy turn-based RPG', 'Traditional turn-based JRPG set in an underwater world.', 'Help Filena reclaim her kingdom and uncover her true identity.', 'Discover the underwater RPG Eien no Filerna on SNES.', 'Based on a novel series. Features a unique world where humans live under the sea. Manage your party and enjoy the classic 16-bit JRPG storytelling and combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eien-no-filerna-japan-en-by-satsu-v098-~eternal-filena', 'SNES', 'Eien no Filerna (Japan) [En by Satsu v0.98] (~Eternal Filena)', '1995', 'RPG', 'Taito', '1', 'Fan-translated dark fantasy RPG', 'Traditional turn-based JRPG set in an underwater world.', 'Experience the story of Eternal Filena with an English translation.', 'Play Eternal Filena in English on the Super Nintendo.', 'The fan translation by Satsu brings this hidden gem to the West. Follow Filena''s journey through a 16-bit world filled with political intrigue and ancient magic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elfaria---the-isle-of-the-blest-japan', 'SNES', 'Elfaria - The Isle of the Blest (Japan)', '1993', 'RPG', 'Hudson Soft', '1', 'Traditional fantasy turn-based RPG', 'Turn-based JRPG with a unique item-based progression system.', 'Stop the world from being drained of its life force.', 'Explore the Isle of the Blest in Elfaria for the SNES.', 'A unique JRPG that replaces traditional leveling with equipment-based growth. Features a beautiful 16-bit world map and strategic turn-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elfaria-ii---the-quest-of-the-meld-japan', 'SNES', 'Elfaria II - The Quest of the Meld (Japan)', '1994', 'RPG', 'Hudson Soft', '1', 'Story-driven fantasy RPG sequel', 'Turn-based JRPG featuring party-based combat and exploration.', 'Solve the mystery of the Meld and save the continent of Elfaria.', 'Experience the sequel Elfaria II on the Super Famicom.', 'Improves upon the original with more refined combat and a deeper narrative. A classic 16-bit JRPG experience for fans of the genre''s golden age.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elite-soccer-usa', 'SNES', 'Elite Soccer (USA)', '1993', 'Sports', 'Rage Software', '2', 'Arcade-style soccer game', 'Deep soccer simulation with a tactical overhead perspective.', 'Win the world cup by mastering team strategy and precise passing.', 'Experience the pitch in Elite Soccer for the Super Nintendo.', 'Known as "World Cup Striker" in Europe. Offers a more realistic take on the sport with detailed 16-bit tactics, formation management, and smooth ball physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elnard-japan', 'SNES', 'Elnard (Japan)', '1990', 'RPG', 'NCS', '1', 'Classic Japanese turn-based RPG', 'Traditional turn-based JRPG with a focus on exploration.', 'Discover the secret of the Seven Stones and save the world.', 'Master the cards and combat in Elnard for the SNES.', 'Known as "The 7th Saga" in the West. This original Japanese version is famous for being more balanced than its punishingly difficult Western counterpart in 16-bit glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-dragon-japan', 'SNES', 'Emerald Dragon (Japan)', '1995', 'RPG', 'Glodia', '1', 'High-fantasy narrative RPG', 'Turn-based JRPG with a focus on dragon lore and cinematic story.', 'Lead a hero and a dragon-girl to prevent a global catastrophe.', 'Experience the epic Emerald Dragon on the Super Famicom.', 'Originally a PC hit, this 16-bit port features a unique tactical combat system where character positioning is key. A beautiful and emotional Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emerald-dragon-japan-en-by-transcorp-v11', 'SNES', 'Emerald Dragon (Japan) [En by TransCorp v1.1]', '1995', 'RPG', 'Glodia', '1', 'Fan-translated narrative RPG', 'Turn-based JRPG with a focus on dragon lore and cinematic story.', 'Experience the epic Emerald Dragon story with English text.', 'Play Emerald Dragon in English on the Super Nintendo.', 'The TransCorp translation allows Western fans to enjoy this high-quality JRPG. Experience the deep character development and innovative 16-bit tactical battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emit-vol-1---toki-no-maigo-japan', 'SNES', 'Emit Vol. 1 - Toki no Maigo (Japan)', '1994', 'Adventure', 'Koei', '1', 'Visual novel time-travel drama', 'Interactive visual novel and language-learning adventure.', 'Solve the mystery of the "Lost in Time" girl through dialogue.', 'Experience the unique Emit Vol. 1 on the Super Famicom.', 'Part of a series designed to help Japanese players learn English. Features high-quality voice acting (via CD or cart) and a charming 16-bit anime art style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emit-vol-2---inochigake-no-tabi-japan', 'SNES', 'Emit Vol. 2 - Inochigake no Tabi (Japan)', '1994', 'Adventure', 'Koei', '1', 'Visual novel suspense adventure', 'Interactive visual novel and language-learning adventure.', 'Navigate the "Life-Threatening Journey" to uncover the truth.', 'Explore the story in Emit Vol. 2 for the Super Famicom.', 'The second chapter of the adventure. It continues the educational and narrative focus, using 16-bit visuals to tell a compelling sci-fi mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emit-vol-3---watashi-ni-sayonara-o-japan', 'SNES', 'Emit Vol. 3 - Watashi ni Sayonara o (Japan)', '1995', 'Adventure', 'Koei', '1', 'Emotional story-driven visual novel', 'Interactive visual novel and language-learning adventure.', 'Reach the emotional conclusion of the Emit trilogy.', 'Experience the finale in Emit Vol. 3 for the SNES.', 'The final installment of the series. Players must use their deduction skills and linguistic knowledge to solve the final 16-bit temporal puzzle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('emmitt-smith-football-usa', 'SNES', 'Emmitt Smith Football (USA)', '1995', 'Sports', 'Imagineering', '2', 'NFL arcade football game', 'American football simulation featuring the legendary Emmitt Smith.', 'Lead your team to the championship using pro playbooks.', 'Hit the gridiron in Emmitt Smith Football for the SNES.', 'Features a "Play Editor" that allows for deep tactical customization. A solid 16-bit football sim with the endorsement of the Dallas Cowboys star.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('energy-breaker-japan', 'SNES', 'Energy Breaker (Japan)', '1994', 'RPG', 'Taito', '1', 'Tactical story-heavy RPG', 'Tactical turn-based RPG with isometric perspective and deep story.', 'Solve the mystery of the "Energy" and stop a looming war.', 'Master the tactical Energy Breaker on the Super Famicom.', 'A late-gen masterpiece. Features beautiful character designs and a grid-based combat system that requires careful planning. One of the most polished 16-bit JRPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('epic-tio-kart', 'SNES', 'Epic Tio Kart', '1995', 'Racing', 'Nakajima Satoru', '4', 'Colorful arcade kart racing', 'Mascot-style kart racer featuring the "Tio" character.', 'Win the tournament by using power-ups and mastering the tracks.', 'Race with friends in the fan-made Epic Tio Kart on SNES.', 'A creative fan-made racing mod using the Super Mario Kart engine. Features new tracks, items, and 16-bit sprites for a fresh racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('equinox-europe', 'SNES', 'Equinox (Europe)', '1993', 'Action-Adventure', 'Sony Imagesoft', '1', 'Isometric puzzle adventure', 'Isometric action-puzzle game with a dark fantasy setting.', 'Navigate through four elemental castles to rescue the princess.', 'Enter the challenging world of Equinox on the Super Nintendo.', 'The sequel to "Solstice." Explore complex 3D-style rooms, solve environmental puzzles, and defeat massive 16-bit bosses in this atmospheric adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('equinox-usa', 'SNES', 'Equinox (USA)', '1993', 'Action-Adventure', 'Sony Imagesoft', '1', 'Isometric puzzle adventure', 'Isometric action-puzzle game with a dark fantasy setting.', 'Navigate through four elemental castles to rescue the princess.', 'Enter the challenging world of Equinox on the Super Nintendo.', 'The sequel to "Solstice." Explore complex 3D-style rooms, solve environmental puzzles, and defeat massive 16-bit bosses in this atmospheric and difficult adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('equinox-usa-beta', 'SNES', 'Equinox (USA) (Beta)', '1993', 'Action-Adventure', 'Sony Imagesoft', '1', 'Beta isometric puzzle adventure', 'Isometric action-puzzle game with a dark fantasy setting.', 'Navigate through four elemental castles to rescue the princess.', 'Explore the Equinox Beta version on the Super Nintendo.', 'A pre-release build of the isometric classic. Discover early room layouts and subtle changes in the physics engine of this challenging 16-bit puzzle-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eric-cantona-football-challenge-europe-enfrdeesitnlsv', 'SNES', 'Eric Cantona Football Challenge (Europe) (En,Fr,De,Es,It,Nl,Sv)', '1994', 'Sports', 'Gremlin Interactive', '2', 'European arcade soccer', 'Arcade-style soccer simulation endorsed by the legendary Eric Cantona.', 'Win the international cup through aggressive and tactical football.', 'Hit the pitch in Eric Cantona Football Challenge on SNES.', 'Known as "World Cup Striker" in other regions. Features fast-paced 16-bit action, multiple weather conditions, and the ability to execute spectacular special shots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('esparks---ijikuu-kara-no-raihousha-japan', 'SNES', 'Esparks - Ijikuu Kara no Raihousha (Japan)', '1994', 'Action', 'NCS', '1', 'Sci-fi action adventure', 'Action-RPG with a unique sci-fi and fantasy crossover theme.', 'Travel through time and space to defeat an interdimensional threat.', 'Experience the epic Esparks on the Super Famicom.', 'A Japanese exclusive featuring vibrant 16-bit graphics and a real-time combat system. Manage your party''s abilities to solve puzzles and defeat massive celestial bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-baseball-tonight-europe', 'SNES', 'ESPN Baseball Tonight (Europe)', '1994', 'Sports', 'Sculptured Software', '2', 'MLB broadcast-style baseball', 'Realistic baseball simulation with full ESPN branding and presentation.', 'Win the World Series by mastering pitching and batting timing.', 'Step up to the plate in ESPN Baseball Tonight on the SNES.', 'Features digitized video sequences and commentary-style presentation. Manage your roster and play through a full 16-bit season with authentic stadium layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-baseball-tonight-usa', 'SNES', 'ESPN Baseball Tonight (USA)', '1994', 'Sports', 'Sculptured Software', '2', 'MLB broadcast-style baseball', 'Realistic baseball simulation with full ESPN branding and presentation.', 'Win the World Series by mastering pitching and batting timing.', 'Step up to the plate in ESPN Baseball Tonight on the SNES.', 'Utilizes the ESPN license to provide a TV-broadcast feel. Master the 16-bit mechanics of the diamond in this detailed and licensed sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-baseball-tonight-usa-beta', 'SNES', 'ESPN Baseball Tonight (USA) (Beta)', '1994', 'Sports', 'Sculptured Software', '2', 'Beta MLB baseball simulation', 'Realistic baseball simulation with full ESPN branding and presentation.', 'Win the World Series by mastering pitching and batting timing.', 'Check out the ESPN Baseball Tonight Beta on SNES.', 'An early development build featuring unfinished assets and testing mechanics for the 16-bit baseball simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-national-hockey-night-usa', 'SNES', 'ESPN National Hockey Night (USA)', '1994', 'Sports', 'Sculptured Software', '2', 'NHL broadcast-style hockey', 'High-energy ice hockey simulation with ESPN-style broadcast.', 'Win the Stanley Cup by outplaying rival NHL teams.', 'Hit the ice in ESPN National Hockey Night for the SNES.', 'Features multiple camera angles and smooth 16-bit skating physics. Use the "playmaker" system to execute advanced strategies and score the winning goal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-speedworld-usa', 'SNES', 'ESPN Speedworld (USA)', '1994', 'Racing', 'Sculptured Software', '2', 'Arcade off-road racing', 'Stock car racing simulation featuring official ESPN licensing.', 'Win the championship by mastering high-speed oval tracks.', 'Experience the speed of ESPN Speedworld on the Super Nintendo.', 'Manage your fuel, tire wear, and pit stops. A detailed 16-bit racing sim that focuses on the strategy and endurance of professional stock car racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-speedworld-usa-beta', 'SNES', 'ESPN Speedworld (USA) (Beta)', '1994', 'Racing', 'Sculptured Software', '2', 'Beta off-road racing', 'Stock car racing simulation featuring official ESPN licensing.', 'Win the championship by mastering high-speed oval tracks.', 'Explore the ESPN Speedworld Beta version for the SNES.', 'A pre-release version of the racing sim, showing early car physics and track designs for the 16-bit ESPN-licensed experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-sunday-night-nfl-usa', 'SNES', 'ESPN Sunday Night NFL (USA)', '1994', 'Sports', 'Sculptured Software', '2', 'NFL broadcast-style football', 'American football simulation focusing on the Sunday night broadcast experience.', 'Lead your team to the Super Bowl through tactical play-calling.', 'Play the gridiron classic ESPN Sunday Night NFL on SNES.', 'Features Bill Berman''s commentary style and detailed playbooks. A solid 16-bit football experience with a focus on realism and authentic ESPN branding.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('estpolis-denki-japan', 'SNES', 'Estpolis Denki (Japan)', '1993', 'RPG', 'Neverland', '1', 'Turn-based fantasy RPG', 'Traditional turn-based JRPG with a focus on cinematic storytelling.', 'Stop the Four Sinistrals from destroying the world.', 'Experience the legendary Estpolis Denki (Lufia) on SNES.', 'The original Japanese release of "Lufia & The Fortress of Doom." Features a classic 16-bit quest with an emotional narrative and a strategic turn-based combat system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('estpolis-denki-ii-japan', 'SNES', 'Estpolis Denki II (Japan)', '1995', 'RPG', 'Neverland', '1', 'Expanded story-driven turn-based RPG', 'Epic turn-based JRPG featuring the legendary "Ancient Cave" roguelike mode.', 'Uncover the origin of the Sinistrals in this prequel.', 'Play the masterpiece Estpolis Denki II (Lufia II) on SNES.', 'Widely regarded as one of the best 16-bit RPGs. Features complex puzzles, monster taming, and one of the most emotional stories on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eurit-usa-proto', 'SNES', 'Eurit (USA) (Proto)', '1992', 'Action', 'Psygnosis', '1', 'Experimental action prototype', 'Abstract action-puzzle game (Unreleased Prototype).', 'Navigate through surreal environments to find the exit.', 'Discover the unreleased prototype Eurit on the SNES.', 'A rare look at a cancelled project. Features experimental 16-bit graphics and unique gameplay mechanics that focused on environmental interaction and logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('euro-football-champ-europe', 'SNES', 'Euro Football Champ (Europe)', '1992', 'Sports', 'Dinamic Software', '2', 'European arcade soccer', 'Arcade-style soccer simulation with a humorous and fast-paced tone.', 'Win the world championship by outscoring every rival nation.', 'Kick off the fun in Euro Football Champ for the SNES.', 'Features large, expressive sprites and exaggerated special moves. A fast and accessible 16-bit football game that focuses on pure arcade excitement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('europe-sensen-japan', 'SNES', 'Europe Sensen (Japan)', '1994', 'Strategy', 'Kemco', '1', 'World War II strategy simulation', 'Grand-scale WWII tactical strategy simulation set in Europe.', 'Lead the Axis or Allied forces to victory in the European theater.', 'Master the battlefield in Europe Sensen for the Super Famicom.', 'Known as "Operation Europe" in the West. A deep Koei strategy game focusing on troop management, logistics, and 16-bit tactical planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exertainment-life-fitness-mega-cart-europe-proto', 'SNES', 'Exertainment Life Fitness Mega Cart (Europe) (Proto)', '1994', 'Fitness', 'LG / Nintendo', '1', 'Fitness-focused exertainment cartridge', 'Specialized software designed for use with Life Fitness exercise equipment.', 'Engage in virtual workouts while using a compatible exercise bike.', 'Discover the rare Exertainment Mega Cart prototype on SNES.', 'A unique piece of 16-bit history. It allowed users to track their fitness progress and participate in mini-games while exercising on physical gym equipment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exhaust-heat-europe', 'SNES', 'Exhaust Heat (Europe)', '1992', 'Racing', 'Seta', '2', 'Arcade-style Formula One racing', 'Realistic Formula 1 racing simulation using Mode 7 for 3D effects.', 'Win the F1 world championship by mastering every international circuit.', 'Race at high speeds in Exhaust Heat for the Super Nintendo.', 'Known as "F1 ROC: Race of Champions." Features car tuning and realistic handling. Experience the intensity of 16-bit open-wheel racing on global tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exhaust-heat-japan', 'SNES', 'Exhaust Heat (Japan)', '1992', 'Racing', 'Seta', '2', 'Arcade-style Formula One racing', 'Realistic Formula 1 racing simulation using Mode 7 for 3D effects.', 'Win the F1 world championship by mastering every international circuit.', 'Race at high speeds in Exhaust Heat for the Super Nintendo.', 'The Japanese original. Buy parts and upgrade your car as you progress through the season. A technical 16-bit racer that prioritizes simulation over arcade action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exhaust-heat-ii---f1-driver-e-no-kiseki-japan', 'SNES', 'Exhaust Heat II - F1 Driver e no Kiseki (Japan)', '1993', 'Racing', 'Seta', '1', 'Story-driven Formula One career racing', 'Enhanced F1 simulation featuring improved graphics and career mode.', 'Build a legendary career and become the world''s best F1 driver.', 'Experience the evolution in Exhaust Heat II for the SNES.', 'Known as "F1 ROC II." Adds a more detailed career path and refined car physics, offering the ultimate 16-bit Formula 1 experience for hardcore fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extra-innings-usa', 'SNES', 'Extra Innings (USA)', '1991', 'Sports', 'Sony Imagesoft', '2', 'Arcade baseball game', 'Lighthearted baseball simulation with an emphasis on arcade fun.', 'Win the baseball league by mastering unique character stats.', 'Play the charming Extra Innings for the Super Nintendo.', 'Features a "chibi" art style and fast-paced gameplay. A fun and accessible 16-bit take on baseball that doesn''t sacrifice depth for its cute visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eye-of-the-beholder-japan', 'SNES', 'Eye of the Beholder (Japan)', '1992', 'RPG', 'Strategic Simulations Inc.', '1', 'Dungeon crawler RPG', 'First-person dungeon crawler based on the Dungeons & Dragons rules.', 'Explore the sewers of Waterdeep to defeat the beholder Xanathar.', 'Enter the dungeon in Eye of the Beholder for the SNES.', 'A classic "blobber" RPG. Navigate tile-based labyrinths, manage your 16-bit party''s inventory, and cast spells in real-time to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eye-of-the-beholder-usa', 'SNES', 'Eye of the Beholder (USA)', '1992', 'RPG', 'Strategic Simulations Inc.', '1', 'Dungeon crawler RPG', 'First-person dungeon crawler based on the Dungeons & Dragons rules.', 'Explore the sewers of Waterdeep to defeat the beholder Xanathar.', 'Enter the dungeon in Eye of the Beholder for the SNES.', 'A faithful port of the PC legend. Experience the atmosphere and challenge of the Forgotten Realms in this deep 16-bit dungeon-crawling experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-grand-prix---part-ii-japan', 'SNES', 'F-1 Grand Prix - Part II (Japan)', '1993', 'Racing', 'Video System', '1', 'Formula One simulation racing', 'Formula 1 racing simulation with an overhead perspective.', 'Win the F1 championship through precise driving and pit strategy.', 'Master the circuit in F-1 Grand Prix - Part II on SNES.', 'A Japanese exclusive sequel featuring updated rosters and tracks. Focuses on the technical aspects of F1 with a unique 16-bit top-down view.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-grand-prix---part-iii-japan', 'SNES', 'F-1 Grand Prix - Part III (Japan)', '1994', 'Racing', 'Video System', '1', 'Formula One simulation racing', 'Formula 1 racing simulation with an overhead perspective.', 'Win the F1 championship through precise driving and pit strategy.', 'Master the circuit in F-1 Grand Prix - Part III on SNES.', 'The third entry in the series, offering the most refined controls and the largest selection of 16-bit tracks and teams for the Japanese market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-1-grand-prix-japan', 'SNES', 'F-1 Grand Prix (Japan)', '1991', 'Racing', 'Video System', '1', 'Classic Formula One racing', 'Formula 1 racing simulation with an overhead perspective.', 'Win the F1 championship through precise driving and pit strategy.', 'Experience the original F-1 Grand Prix on the SNES.', 'The foundational entry of the series. Features a blend of arcade action and simulation management, all presented in a clean 16-bit top-down style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-15-super-strike-eagle-japan', 'SNES', 'F-15 Super Strike Eagle (Japan)', '1992', 'Action', 'MicroProse', '1', 'Jet fighter combat simulation', 'Combat flight simulator featuring the legendary F-15 fighter jet.', 'Complete various military missions across global conflict zones.', 'Take to the skies in F-15 Super Strike Eagle on SNES.', 'Master the cockpit controls and use advanced radar to track targets. A technically impressive 16-bit flight sim with intense dogfights and bombing runs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-europe', 'SNES', 'F-Zero (Europe)', '1990', 'Racing', 'Nintendo', '2', 'Mode 7 futuristic racing', 'Groundbreaking futuristic racing game that launched the SNES.', 'Win the F-Zero Grand Prix by mastering high-speed hovercrafts.', 'Experience the speed of F-Zero on the Super Nintendo.', 'The game that introduced Mode 7. Race at over 400km/h through futuristic cities in a 16-bit masterpiece of speed, music, and design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-japan-rev-0a', 'SNES', 'F-Zero (Japan) (Rev 0A)', '1990', 'Racing', 'Nintendo', '2', 'Mode 7 futuristic racing', 'Groundbreaking futuristic racing game that launched the SNES.', 'Win the F-Zero Grand Prix by mastering high-speed hovercrafts.', 'Experience the original Japanese F-Zero (Rev 0A) on SNES.', 'The initial Japanese release featuring the iconic Big Blue and Mute City tracks. A landmark 16-bit title that defined the futuristic racing genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-usa', 'SNES', 'F-Zero (USA)', '1990', 'Racing', 'Nintendo', '2', 'Mode 7 futuristic racing', 'Groundbreaking futuristic racing game that launched the SNES.', 'Win the F-Zero Grand Prix by mastering high-speed hovercrafts.', 'Experience the speed of F-Zero on the Super Nintendo.', 'Choose from four legendary pilots like Captain Falcon. Master the "power slide" and boost mechanics to survive the 16-bit tracks of the future.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f-zero-usa-hack-by-smkdan-v10-all-track-practice', 'SNES', 'F-Zero (USA) [Hack by Smkdan v1.0] (All Track Practice)', '2005', 'Racing', 'Nintendo', '1', 'Hack practice mode racing', 'A training-focused hack that unlocks all tracks for practice.', 'Master every turn of every track without the pressure of a race.', 'Practice like a pro in the F-Zero All Track Practice mod.', 'A useful tool for speedrunners and veterans. This hack allows you to select any track in the game for solo practice, perfecting your 16-bit racing lines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-pole-position-europe', 'SNES', 'F1 Pole Position (Europe)', '1992', 'Racing', 'Human Entertainment', '2', 'Realistic Formula One racing', 'Realistic Formula 1 racing simulation utilizing Mode 7 graphics.', 'Win the world championship by mastering real-world F1 circuits.', 'Experience the speed of F1 Pole Position on the SNES.', 'Known as "Human Grand Prix" in Japan. Features official licenses, car tuning, and split-screen multiplayer for high-speed 16-bit open-wheel racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-pole-position-usa', 'SNES', 'F1 Pole Position (USA)', '1992', 'Racing', 'Human Entertainment', '2', 'Realistic Formula One racing', 'Realistic Formula 1 racing simulation utilizing Mode 7 graphics.', 'Win the world championship by mastering real-world F1 circuits.', 'Experience the speed of F1 Pole Position on the SNES.', 'Experience the intensity of professional racing. Manage your pit stops and tires while competing against a full grid of 16-bit F1 drivers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-pole-position-usa-beta', 'SNES', 'F1 Pole Position (USA) (Beta)', '1992', 'Racing', 'Human Entertainment', '2', 'Beta Formula One racing', 'Realistic Formula 1 racing simulation utilizing Mode 7 graphics.', 'Explore the early car physics and track layouts of the racing sim.', 'Check out the F1 Pole Position Beta on the SNES.', 'A pre-release version of the popular racing title. Discover how the developers refined the 16-bit Mode 7 effects and car handling before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-pole-position-2-europe', 'SNES', 'F1 Pole Position 2 (Europe)', '1993', 'Racing', 'Human Entertainment', '2', 'Improved Formula One simulation', 'Enhanced Formula 1 simulation with updated rosters and car handling.', 'Defeat rival drivers to claim the top spot on the podium.', 'Master the circuit in F1 Pole Position 2 for the SNES.', 'The sequel offers more refined graphics and a deeper career mode. A technical 16-bit racer that prioritizes simulation accuracy and track detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-roc---race-of-champions-usa', 'SNES', 'F1 ROC - Race of Champions (USA)', '1992', 'Racing', 'U.S. Gold', '2', 'International Formula One racing', 'Realistic Formula 1 racing simulation with an emphasis on car tuning.', 'Build your racing career and win the world championship.', 'Race for glory in F1 ROC: Race of Champions on SNES.', 'Known as "Exhaust Heat" in Japan. Use prize money to upgrade your car''s engine, tires, and wings in this deep and challenging 16-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-roc-ii---race-of-champions-usa', 'SNES', 'F1 ROC II - Race of Champions (USA)', '1993', 'Racing', 'U.S. Gold', '2', 'Enhanced Formula One racing sequel', 'Advanced Formula 1 simulation featuring a comprehensive career path.', 'Climb from the junior leagues to become a Formula 1 legend.', 'Experience the evolution in F1 ROC II for the SNES.', 'The sequel adds a structured progression system. Master different racing classes and manage your team to dominate the 16-bit global circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-world-championship-edition-europe', 'SNES', 'F1 World Championship Edition (Europe)', '1995', 'Racing', 'Video System', '2', 'Official FIA Formula One racing', 'High-end Formula 1 racing game with improved visuals and smooth controls.', 'Compete in the world''s most prestigious racing championship.', 'Play the polished F1 World Championship Edition on SNES.', 'A late-gen racing title known for its high frame rate and detailed sprites. Offers one of the most fluid 16-bit racing experiences on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('faceball-2000-usa', 'SNES', 'Faceball 2000 (USA)', '1992', 'FPS', 'Xanth Software F/X', '4', 'Multiplayer maze-based shooter', 'First-person shooter featuring a unique spherical character theme.', 'Navigate arenas and eliminate rival "faceballs" in 3D combat.', 'Enter the arena in Faceball 2000 for the Super Nintendo.', 'A rare example of a 3D FPS on the SNES. Battle through mazes in single-player or engage in frantic 16-bit multiplayer matches with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fall-guys-world-english', 'SNES', 'Fall Guys World (English)', '2023', 'Platformer', 'Fan Made', '4', 'Modern party-style platformer demake', 'Fan-made mod of a classic 16-bit title with a Fall Guys theme.', 'Complete wacky obstacle courses and mini-games to be the last one standing.', 'Join the fun in Fall Guys World (English) on the SNES.', 'A creative hack (usually of Kunio-kun games) that brings the modern "Battle Royale" party spirit to 16-bit hardware with custom sprites and levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fall-guys-world-pt-br', 'SNES', 'Fall Guys World (PT-BR)', '2023', 'Platformer', 'Fan Made', '4', 'Portuguese-translated party platformer demake', 'Fan-made mod of a classic 16-bit title with a Fall Guys theme.', 'Complete wacky obstacle courses and mini-games in Portuguese.', 'Experimente o Fall Guys World em português no SNES.', 'A Portuguese translation of the popular Fall Guys-themed mod. Enjoy 16-bit party games and competitive challenges with fully localized text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-bunko---hajimari-no-mori-japan-np', 'SNES', 'Famicom Bunko - Hajimari no Mori (Japan) (NP)', '1999', 'Adventure', 'Nintendo', '1', 'Visual novel mystery adventure', 'Charming point-and-click adventure/RPG hybrid.', 'Explore the forest and help the spirits to save your grandfather.', 'Discover the magic of Hajimari no Mori on the SNES.', 'A late-release Japanese exclusive for the Nintendo Power service. Features beautiful 16-bit art and a heartwarming story about childhood and nature.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-tantei-club-part-ii---ushiro-ni-tatsu-shoujo-japan-np', 'SNES', 'Famicom Tantei Club Part II - Ushiro ni Tatsu Shoujo (Japan) (NP)', '1998', 'Adventure', 'Nintendo', '1', 'Detective visual novel sequel', 'Atmospheric murder mystery visual novel with a dark, mature tone.', 'Investigate a high school murder and the legend of the "Girl Behind."', 'Solve the mystery in Famicom Tantei Club Part II on SNES.', 'A stunning 16-bit remake of the Famicom classic. Features cinematic transitions, an eerie soundtrack, and deep investigative gameplay for mystery fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-tantei-club-part-ii---ushiro-ni-tatsu-shoujo-japan-np-en-by-demiforce+tomato-v10-~famicom-detective-club-part-ii', 'SNES', 'Famicom Tantei Club Part II - Ushiro ni Tatsu Shoujo (Japan) (NP) [En by Demiforce+Tomato v1.0] (~Famicom Detective Club Part II)', '1998', 'Adventure', 'Nintendo', '1', 'Fan-translated detective visual novel', 'Atmospheric murder mystery visual novel with a dark, mature tone.', 'Experience the complete horror mystery with full English text.', 'Play Famicom Detective Club Part II in English on SNES.', 'The legendary fan translation by Demiforce and Tomato. Follow the gripping, somber narrative and solve the 16-bit crime with fully translated dialogue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('famicom-tantei-club-part-ii---ushiro-ni-tatsu-shoujo-japan-rev-a-np', 'SNES', 'Famicom Tantei Club Part II - Ushiro ni Tatsu Shoujo (Japan) (Rev A) (NP)', '1998', 'Adventure', 'Nintendo', '1', 'Revised detective visual novel edition', 'Atmospheric murder mystery visual novel with a dark, mature tone.', 'Investigate the school mystery in the refined Rev A version.', 'Play Famicom Tantei Club Part II (Rev A) on the SNES.', 'An updated Japanese revision that fixed minor text and graphical glitches, ensuring the most stable 16-bit investigative experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-dog-europe', 'SNES', 'Family Dog (Europe)', '1993', 'Platformer', 'Realtime Associates', '1', 'Cartoon-based action platformer', 'Side-scrolling platformer based on the short-lived animated series.', 'Help the clumsy family dog navigate household hazards and obstacles.', 'Join the misadventures in Family Dog for the SNES.', 'Features a unique art style based on Brad Bird''s original designs. Navigate through 16-bit domestic levels filled with humor and challenging platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-dog-usa', 'SNES', 'Family Dog (USA)', '1993', 'Platformer', 'Realtime Associates', '1', 'Cartoon-based action platformer', 'Side-scrolling platformer based on the short-lived animated series.', 'Help the clumsy family dog navigate household hazards and obstacles.', 'Join the misadventures in Family Dog for the SNES.', 'Master the dog''s jumping and barking mechanics to clear various stages. A colorful and quirky 16-bit platformer for fans of the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-feud-usa', 'SNES', 'Family Feud (USA)', '1991', 'Trivia', 'GameTek', '2', 'TV game show trivia adaptation', 'Digital adaptation of the classic television game show.', 'Guess the most popular survey answers to win the grand prize.', 'Play Family Feud with your friends on the Super Nintendo.', 'Features digitized images and the iconic theme music. Compete against the AI or another family in this accessible 16-bit trivia game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-feud-usa-rev-a', 'SNES', 'Family Feud (USA) (Rev A)', '1991', 'Trivia', 'GameTek', '2', 'Revised TV game show trivia', 'Digital adaptation of the classic television game show.', 'Guess the survey answers in this refined revision of the game.', 'Play the polished Family Feud (Rev A) on the SNES.', 'An updated version with minor bug fixes and improved AI response times, offering a smoother experience for 16-bit game show enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('farland-story-japan', 'SNES', 'Farland Story (Japan)', '1993', 'RPG', 'Telenet Japan', '1', 'Tactical fantasy role-playing game', 'Tactical turn-based RPG with a focus on party-based combat.', 'Lead your heroes on an epic quest to stop an ancient evil.', 'Experience the strategy of Farland Story on the SNES.', 'A port of the popular PC series. Features detailed 16-bit character sprites and a grid-based combat system that requires careful planning and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('farland-story-2-japan', 'SNES', 'Farland Story 2 (Japan)', '1994', 'RPG', 'Telenet Japan', '1', 'Tactical fantasy RPG sequel', 'Tactical turn-based RPG sequel with expanded mechanics and story.', 'Continue the legend and defeat a new threat to the land.', 'Explore the world of Farland Story 2 for the Super Famicom.', 'Introduces new character classes and more complex mission objectives. A classic 16-bit tactical RPG for fans of high-fantasy storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fat-moot-vorld', 'SNES', 'Fat Moot /v/orld', '2018', 'Action', 'Anonymous', '1', 'Experimental meme-based action game', 'Bizarre and humorous fan-made adventure with internet culture themes.', 'Navigate through a surreal world filled with community memes.', 'Experience the weirdness of Fat Moot /v/orld on SNES.', 'A unique hack that transforms a classic game into a tribute to internet subcultures. Features custom 16-bit graphics and plenty of inside jokes for a niche audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-europe', 'SNES', 'Fatal Fury (Europe)', '1993', 'Fighting', 'SNK', '2', 'Classic one-on-one fighting game', 'One-on-one fighting game featuring the legendary Hungry Wolf, Terry Bogard.', 'Defeat Geese Howard in the King of Fighters tournament.', 'Enter the battle in Fatal Fury for the Super Nintendo.', 'The first entry in SNK''s iconic series. Features a unique "two-plane" combat system that allows fighters to move between the foreground and background.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-usa', 'SNES', 'Fatal Fury (USA)', '1993', 'Fighting', 'SNK', '2', 'Classic one-on-one fighting game', 'One-on-one fighting game featuring the legendary Hungry Wolf, Terry Bogard.', 'Defeat Geese Howard in the King of Fighters tournament.', 'Enter the battle in Fatal Fury for the Super Nintendo.', 'Master Terry Bogard''s Power Wave and Burn Knuckle. A foundational 16-bit fighter that brought arcade-style intensity to the home console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-2-europe', 'SNES', 'Fatal Fury 2 (Europe)', '1994', 'Fighting', 'SNK', '2', 'Fighting game sequel with combos', 'One-on-one fighting game sequel with a much larger roster and faster action.', 'Defeat the new challenger Wolfgang Krauser to prove your strength.', 'Experience the classic Fatal Fury 2 on the SNES.', 'A massive improvement over the original. Introduces the "Desperation Move" mechanic and iconic 16-bit characters like Mai Shiranui and Kim Kaphwan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-2-usa', 'SNES', 'Fatal Fury 2 (USA)', '1994', 'Fighting', 'SNK', '2', 'Fighting game sequel with combos', 'One-on-one fighting game sequel with a much larger roster and faster action.', 'Defeat the new challenger Wolfgang Krauser to prove your strength.', 'Experience the classic Fatal Fury 2 on the SNES.', 'Master the improved plane-switching mechanics and powerful special moves in this essential 16-bit fighting game from the SNK library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-special-europe', 'SNES', 'Fatal Fury Special (Europe)', '1995', 'Fighting', 'SNK', '2', 'Enhanced tournament fighting edition', 'One-on-one fighting game featuring a massive roster of SNK icons.', 'Defeat the ultimate boss, Wolfgang Krauser, in the dream tournament.', 'Master the combos in Fatal Fury Special for the SNES.', 'An upgraded version of Fatal Fury 2. Features faster gameplay, new combos, and the return of classic characters like Duck King and Geese Howard in 16-bit glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-special-europe-beta', 'SNES', 'Fatal Fury Special (Europe) (Beta)', '1995', 'Fighting', 'SNK', '2', 'Beta enhanced tournament fighter', 'One-on-one fighting game featuring a massive roster of SNK icons.', 'Defeat the ultimate boss, Wolfgang Krauser, in the dream tournament.', 'Explore the Fatal Fury Special Beta on the Super Nintendo.', 'A pre-release build of the arcade port. Discover early character balancing and timing tweaks in this 16-bit fighting game masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury-special-usa', 'SNES', 'Fatal Fury Special (USA)', '1995', 'Fighting', 'SNK', '2', 'Enhanced tournament fighting edition', 'One-on-one fighting game featuring a massive roster of SNK icons.', 'Defeat the ultimate boss, Wolfgang Krauser, in the dream tournament.', 'Play the definitive Fatal Fury Special on the SNES.', 'Considered one of the best fighters on the system. Master the plane-switching mechanic and devastating "Hidden Abilities" with 16-bit precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('feda---the-emblem-of-justice-japan', 'SNES', 'Feda - The Emblem of Justice (Japan)', '1994', 'Strategy', 'Max Entertainment', '1', 'Turn-based tactical RPG', 'Tactical turn-based RPG with an isometric perspective.', 'Lead a group of deserters to fight for true justice against an empire.', 'Experience the strategic Feda: The Emblem of Justice on SNES.', 'A beautiful tactical RPG. Your choices (Neutral, Chaos, Law) affect which characters join you and how the 16-bit story unfolds across branching paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('feda---the-emblem-of-justice-japan-beta', 'SNES', 'Feda - The Emblem of Justice (Japan) (Beta)', '1994', 'Strategy', 'Max Entertainment', '1', 'Beta tactical role-playing game', 'Tactical turn-based RPG with an isometric perspective.', 'Lead a group of deserters to fight for true justice against an empire.', 'Check out the Feda: The Emblem of Justice Beta on SNES.', 'A rare development build of this tactical gem. Observe early sprite animations and tactical grid layouts in this 16-bit fantasy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('feda---the-emblem-of-justice-japan-en-by-magic-destiny+stealth-v101', 'SNES', 'Feda - The Emblem of Justice (Japan) [En by Magic Destiny+Stealth v1.01]', '1994', 'Strategy', 'Max Entertainment', '1', 'Fan-translated tactical RPG', 'Tactical turn-based RPG with an isometric perspective.', 'Experience the deep, branching story with a full English translation.', 'Play Feda: The Emblem of Justice in English on the SNES.', 'The fan translation allows Western players to fully understand the complex "Emblem" system and morality-based recruitment of this 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fever-pitch-soccer-europe-beta', 'SNES', 'Fever Pitch Soccer (Europe) (Beta)', '1994', 'Sports', 'U.S. Gold', '2', 'Arcade-style soccer beta', 'Arcade-style soccer simulation with a humorous, aggressive tone.', 'Win the tournament by using power-ups and brutal tackles.', 'Play the high-energy Fever Pitch Soccer on the SNES.', 'Known as "Mario Helmer''s Fever Pitch." Features special moves, environmental hazards, and a fun 16-bit career mode where you can upgrade your team.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fever-pitch-soccer-europe-enfrdeesit', 'SNES', 'Fever Pitch Soccer (Europe) (En,Fr,De,Es,It)', '1995', 'Sports', 'U.S. Gold', '2', 'Arcade-style international soccer', 'Arcade-style soccer simulation with a humorous, aggressive tone.', 'Win the tournament by using power-ups and brutal tackles.', 'Play the high-energy Fever Pitch Soccer on the SNES.', 'A fast-paced 16-bit football game that values fun over realism. Master the "fire shots" and take down your rivals on the pitch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-97---gold-edition-europe-enfrdeesitsv', 'SNES', 'FIFA ''97 - Gold Edition (Europe) (En,Fr,De,Es,It,Sv)', '1996', 'Sports', 'Electronic Arts', '2', 'Advanced licensed soccer simulation', 'Soccer simulation featuring updated rosters and the "Gold Edition" polish.', 'Win the international league and reach the top of the FIFA rankings.', 'Kick off with FIFA ''97 Gold Edition on the Super Nintendo.', 'Features indoor soccer for the first time on the system. Experience the 16-bit evolution of the world''s most popular sports franchise with improved controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-97---gold-edition-usa-enfrdeesitsv', 'SNES', 'FIFA ''97 - Gold Edition (USA) (En,Fr,De,Es,It,Sv)', '1996', 'Sports', 'Electronic Arts', '2', 'Advanced licensed soccer simulation', 'Soccer simulation featuring updated rosters and the "Gold Edition" polish.', 'Win the international league and reach the top of the FIFA rankings.', 'Kick off with FIFA ''97 Gold Edition on the Super Nintendo.', 'Manage your team and play through a full 16-bit season. Includes various camera angles and digitized sound effects for a realistic match day feel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-98---road-to-world-cup-europe-enfrdeesitsv', 'SNES', 'FIFA ''98 - Road to World Cup (Europe) (En,Fr,De,Es,It,Sv)', '1997', 'Sports', 'Electronic Arts', '2', 'World Cup qualifying soccer game', 'The final FIFA entry on the system, focusing on the World Cup journey.', 'Qualify for and win the 1998 World Cup with your favorite nation.', 'Road to World Cup fun in FIFA ''98 for the SNES.', 'A farewell to the 16-bit era. Features a massive selection of national teams and the classic "isometric" gameplay that defined the early series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer-europe', 'SNES', 'FIFA International Soccer (Europe)', '1994', 'Sports', 'Electronic Arts', '2', 'Foundational soccer simulation', 'The game that started it all, featuring an isometric view and crowd chants.', 'Lead your team to the world championship for the first time.', 'Play the original FIFA International Soccer on SNES.', 'A landmark sports title. Features the famous "running away from the referee" glitch and smooth 16-bit animations that set a new standard for soccer games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer-japan', 'SNES', 'FIFA International Soccer (Japan)', '1994', 'Sports', 'Electronic Arts', '2', 'Japanese-market soccer simulation', 'The game that started it all, featuring an isometric view and crowd chants.', 'Lead your team to the world championship for the first time.', 'Experience the Japanese version of FIFA International Soccer.', 'The Super Famicom release of the global hit. Features the same deep 16-bit tactical options and addictive multiplayer that made it a household name.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-international-soccer-usa', 'SNES', 'FIFA International Soccer (USA)', '1994', 'Sports', 'Electronic Arts', '2', 'North American soccer simulation', 'The game that started it all, featuring an isometric view and crowd chants.', 'Lead your team to the world championship for the first time.', 'Play the original FIFA International Soccer on SNES.', 'Master the corner kicks and bicycle shots. A must-play 16-bit sports classic that captured the excitement of the 1994 World Cup era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-96-europe-enfrdeesitsv', 'SNES', 'FIFA Soccer ''96 (Europe) (En,Fr,De,Es,It,Sv)', '1996', 'Sports', 'Electronic Arts', '2', 'International soccer simulation', 'Soccer simulation with real player names and improved physics.', 'Dominate the pitch and win the league in the 1996 edition.', 'Experience the pro action in FIFA Soccer ''96 for SNES.', 'The first entry to feature real players thanks to the FIFPro license. Enjoy more fluid 16-bit passing and a wide array of team management options.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-96-usa-enfrdeesitsv', 'SNES', 'FIFA Soccer ''96 (USA) (En,Fr,De,Es,It,Sv)', '1996', 'Sports', 'Electronic Arts', '2', 'International soccer simulation (USA)', 'Soccer simulation with real player names and improved physics.', 'Dominate the pitch and win the league in the 1996 edition.', 'Experience the pro action in FIFA Soccer ''96 for SNES.', 'Take your favorite club to the top. This 16-bit version offers a deeper simulation experience with realistic player stats and diverse weather conditions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-history---mizoguchi-kikiippatsu!!-japan', 'SNES', 'Fighter''s History - Mizoguchi Kikiippatsu!! (Japan)', '1995', 'Fighting', 'Data East', '2', 'Japanese-exclusive special edition of fighting game', 'One-on-one fighting game featuring the legendary Mizoguchi.', 'Win the tournament and prove your martial arts supremacy.', 'Fight for glory in Fighter''s History: Mizoguchi Kikiippatsu!!', 'A Japanese exclusive update. Features faster combat and new special moves in a colorful 16-bit environment that pays tribute to arcade classics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-history-japan', 'SNES', 'Fighter''s History (Japan)', '1994', 'Fighting', 'Data East', '2', 'Japanese release of arcade fighting game', 'One-on-one fighting game featuring a unique "weak point" system.', 'Defeat the mysterious Karnov and his elite fighters.', 'Master the system in Fighter''s History for the SNES.', 'A cult classic fighter. Exploit your opponent''s 16-bit "weak points" to stun them and unleash devastating special moves in this technical arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-history-usa-beta', 'SNES', 'Fighter''s History (USA) (Beta)', '1994', 'Fighting', 'Data East', '2', 'Beta version of arcade fighting game', 'One-on-one fighting game featuring a unique "weak point" system.', 'Defeat the mysterious Karnov and his elite fighters.', 'Check out the Fighter''s History Beta on the SNES.', 'A pre-release version of the game. Explore the 16-bit fighter''s early character balancing and sprite animations before its final retail launch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-history-usa-rev-a', 'SNES', 'Fighter''s History (USA) (Rev A)', '1994', 'Fighting', 'Data East', '2', 'Revised North American fighting game', 'One-on-one fighting game featuring a unique "weak point" system.', 'Defeat the mysterious Karnov and his elite fighters.', 'Play the polished Fighter''s History (Rev A) on the SNES.', 'The updated 16-bit revision with minor bug fixes and refined move sets, offering the most stable tournament experience on the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-baseball-japan', 'SNES', 'Fighting Baseball (Japan)', '1994', 'Sports', 'Namco', '2', 'Arcade-style baseball game', 'Baseball simulation famous for its "American" player names.', 'Win the baseball league by mastering the diamond.', 'Play the hilarious Fighting Baseball on the Super Famicom.', 'Beyond the famous memes of its fictional players, it''s a solid 16-bit baseball game with smooth controls and a fun arcade feel for sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy---mystic-quest-usa', 'SNES', 'Final Fantasy - Mystic Quest (USA)', '1992', 'RPG', 'Square', '1', 'Simplified RPG for Western audiences', 'Entry-level JRPG with a focus on action-adventure and simple mechanics.', 'Restore the four crystals to save the world from total destruction.', 'Begin your journey in Final Fantasy: Mystic Quest on SNES.', 'Designed for newcomers to the genre. Features visible enemies on the map and a mix of platforming and turn-based 16-bit combat. A lighthearted and melodic RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy---mystic-quest-usa-rev-a', 'SNES', 'Final Fantasy - Mystic Quest (USA) (Rev A)', '1992', 'RPG', 'Square', '1', 'Revised simplified RPG edition', 'Entry-level JRPG with a focus on action-adventure and simple mechanics.', 'Restore the four crystals to save the world from total destruction.', 'Play the polished Rev A of Final Fantasy: Mystic Quest.', 'The updated 16-bit version featuring minor bug fixes and text corrections, ensuring a smooth entry into the world of Final Fantasy for western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-ii-usa', 'SNES', 'Final Fantasy II (USA)', '1991', 'RPG', 'Square', '1', 'North American version of Final Fantasy IV', 'Epic turn-based RPG featuring the "Active Time Battle" system.', 'Lead Cecil the Dark Knight on a quest of redemption and bravery.', 'Experience the legendary Final Fantasy II on the SNES.', 'Actually the western release of FFIV. Follow an emotional story of love and betrayal with a classic 16-bit soundtrack and unforgettable characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-ii-usa-rev-1-bug-fix-by-deathlike2-v10a-yangs-hp-fix', 'SNES', 'Final Fantasy II (USA) (Rev 1) [Bug Fix by Deathlike2 v1.0a] (Yang''s HP Fix)', '1991', 'RPG', 'Square', '1', 'Bug-fixed revision with character HP correction', 'Epic turn-based JRPG with a specific technical fix for character stats.', 'Experience the classic story with Yang''s health bug fully fixed.', 'Play the fixed Final Fantasy II (Yang''s HP Fix) on SNES.', 'A technical patch that resolves a notorious glitch where Yang''s HP wouldn''t grow correctly, ensuring a balanced 16-bit party for the endgame.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-ii-usa-rev-1-hack-by-dragonsbrethren-v10-~final-fantasy-ii-is-easy-type', 'SNES', 'Final Fantasy II (USA) (Rev 1) [Hack by Dragonsbrethren v1.0] (~Final Fantasy II is Easy Type)', '1991', 'RPG', 'Square', '1', 'Easy-type difficulty hack', 'Epic turn-based JRPG modified to match the easier Japanese edition.', 'Enjoy the story of Cecil with reduced difficulty and simplified items.', 'Experience the "Easy Type" mod for Final Fantasy II on SNES.', 'This hack restores the "Easy Type" balance from Japan, making the 16-bit journey more accessible while retaining the epic narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-ii-usa-rev-1-hack-by-jce3000gt-v12-hard-type', 'SNES', 'Final Fantasy II (USA) (Rev 1) [Hack by JCE3000GT v1.2] (Hard Type)', '1991', 'RPG', 'Square', '1', 'Hard-type difficulty hack', 'Epic turn-based JRPG with significantly increased difficulty.', 'Survive the most brutal version of Cecil''s journey.', 'Challenge yourself with Final Fantasy II Hard Type on SNES.', 'Designed for veterans. This mod increases enemy stats and AI complexity, forcing players to master 16-bit strategy to survive even basic encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-ii-usa-rev-a', 'SNES', 'Final Fantasy II (USA) (Rev A)', '1991', 'RPG', 'Square', '1', 'Revised North American release', 'Epic turn-based JRPG featuring the "Active Time Battle" system.', 'Lead Cecil the Dark Knight on a quest of redemption and bravery.', 'Play the refined Rev A version of Final Fantasy II on SNES.', 'The final official 16-bit revision for the US market, fixing several minor script errors and rare crashing bugs found in the original release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-ii-usa-bug-fix-by-deathlike2-v10a-yangs-hp-fix', 'SNES', 'Final Fantasy II (USA) [Bug Fix by Deathlike2 v1.0a] (Yang''s HP Fix)', '1991', 'RPG', 'Square', '1', 'Bug-fixed standalone version', 'Epic turn-based JRPG with a specific technical fix for character stats.', 'Experience the classic story with Yang''s health bug fully fixed.', 'Play the fixed Final Fantasy II (Yang''s HP Fix) on SNES.', 'A bug-fix mod for the initial US release. It ensures Yang remains a viable 16-bit powerhouse by fixing his hit point calculation errors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-ii-usa-hack-by-jce3000gt-v12-hard-type', 'SNES', 'Final Fantasy II (USA) [Hack by JCE3000GT v1.2] (Hard Type)', '1991', 'RPG', 'Square', '1', 'Hard-type standalone hack', 'Epic turn-based JRPG with significantly increased difficulty.', 'Survive the most brutal version of Cecil''s journey.', 'Challenge yourself with Final Fantasy II Hard Type on SNES.', 'A re-balanced version for the first US release. It removes the "hand-holding" of the original western localization for a true 16-bit challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa', 'SNES', 'Final Fantasy III (USA)', '1994', 'RPG', 'Square', '1', 'North American version of Final Fantasy VI', 'Masterpiece JRPG featuring 14 playable characters and a deep story.', 'Stop the mad jester Kefka from destroying the world of magic.', 'Experience the monumental Final Fantasy III on the SNES.', 'Actually the western release of FFVI. A cinematic 16-bit achievement with a complex plot, an opera scene, and an incredible score by Nobuo Uematsu.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-rev-1-hack-by-jce3000gt-v12-hard-type', 'SNES', 'Final Fantasy III (USA) (Rev 1) [Hack by JCE3000GT v1.2] (Hard Type)', '1994', 'RPG', 'Square', '1', 'Hard-type difficulty hack', 'Masterpiece JRPG with a focus on extreme tactical challenge.', 'Overcome the hardest bosses in 16-bit history.', 'Play Final Fantasy III Hard Type by JCE3000GT on SNES.', 'Reworks enemy encounters and character growth. This hack demands a deep understanding of the 16-bit Esper system and equipment synergy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-rev-1-hack-by-sageacrin-v106-evil-type', 'SNES', 'Final Fantasy III (USA) (Rev 1) [Hack by SageAcrin v1.06] (Evil Type)', '1994', 'RPG', 'Square', '1', 'Evil-type difficulty hack', 'Masterpiece JRPG with a focus on "un-fair" and brutal combat.', 'Defeat Kefka in his most powerful and aggressive form.', 'Survive the brutal Final Fantasy III Evil Type on SNES.', 'Notorious for its difficulty. Enemies use devastating spells earlier and more frequently, creating a punishing 16-bit experience for hardcore fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-rev-1-hack-by-zeemis-v10-~final-fantasy---revelations', 'SNES', 'Final Fantasy III (USA) (Rev 1) [Hack by Zeemis v1.0] (~Final Fantasy - Revelations)', '1994', 'RPG', 'Square', '1', 'Alternate translation hack', 'Total conversion hack that reimagines the story and script.', 'Explore a "New Reality" with updated dialogue and lore.', 'Discover Final Fantasy: Revelations on the Super Nintendo.', 'A creative script overhaul that attempts to bridge gaps in the 16-bit lore and provide a fresh perspective on the classic "War of the Magi."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-rev-a', 'SNES', 'Final Fantasy III (USA) (Rev A)', '1994', 'RPG', 'Square', '1', 'Revised North American release', 'Masterpiece JRPG featuring 14 playable characters and a deep story.', 'Stop the mad jester Kefka from destroying the world of magic.', 'Play the polished Rev A of Final Fantasy III on SNES.', 'The updated US release that fixes the famous "Sketch Glitch" and other minor bugs that could corrupt 16-bit save files.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-hack-by-jce3000gt-v12-hard-type', 'SNES', 'Final Fantasy III (USA) [Hack by JCE3000GT v1.2] (Hard Type)', '1994', 'RPG', 'Square', '1', 'Hard-type standalone hack', 'Masterpiece JRPG with a focus on extreme tactical challenge.', 'Overcome the hardest bosses in 16-bit history.', 'Play Final Fantasy III Hard Type by JCE3000GT on SNES.', 'A re-balanced version for the first US release, focusing on providing a consistent and fair 16-bit challenge for RPG experts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-hack-by-makoueyes-v908-~final-fantasy-vi---the-eternal-crystals', 'SNES', 'Final Fantasy III (USA) [Hack by MakouEyes v9.08] (~Final Fantasy VI - The Eternal Crystals)', '1994', 'RPG', 'Square', '1', 'Total conversion fantasy hack', 'Massive expansion hack with new content, items, and dungeons.', 'Restore the Eternal Crystals in this expanded 16-bit adventure.', 'Play FFVI: The Eternal Crystals expansion on the SNES.', 'Features new bosses, restored Japanese content, and a revamped magic system. A massive love letter to the 16-bit original with hours of new gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-hack-by-sageacrin-v106-evil-type', 'SNES', 'Final Fantasy III (USA) [Hack by SageAcrin v1.06] (Evil Type)', '1994', 'RPG', 'Square', '1', 'Evil-type standalone hack', 'Masterpiece JRPG with a focus on "un-fair" and brutal combat.', 'Defeat Kefka in his most powerful and aggressive form.', 'Survive the brutal Final Fantasy III Evil Type on SNES.', 'The initial version of the "Evil" mod, focusing on aggressive enemy AI and punishing 16-bit status effect combinations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-hack-by-tzepish-v12-~final-fantasy-iv---enhanced-editon', 'SNES', 'Final Fantasy III (USA) [Hack by Tzepish v1.2] (~Final Fantasy IV - Enhanced Editon)', '1994', 'RPG', 'Square', '1', 'Enhanced gameplay hack', 'Crossover mod that brings elements of FFIV into the FFVI engine.', 'Experience the story of Cecil with the advanced mechanics of FFVI.', 'Play Final Fantasy IV: Enhanced Edition on the SNES.', 'A unique technical feat that ports the FFIV story into the superior 16-bit engine of FFVI, offering better menus and smoother combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iii-usa-hack-by-zeemis-v10-~final-fantasy---revelations', 'SNES', 'Final Fantasy III (USA) [Hack by Zeemis v1.0] (~Final Fantasy - Revelations)', '1994', 'RPG', 'Square', '1', 'Alternate translation standalone hack', 'Total conversion hack that reimagines the story and script.', 'Explore a "New Reality" with updated dialogue and lore.', 'Discover Final Fantasy: Revelations on the Super Nintendo.', 'Focuses on a more mature and direct translation style, aiming to provide a "director''s cut" feel to the 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv---easy-type-japan', 'SNES', 'Final Fantasy IV - Easy Type (Japan)', '1991', 'RPG', 'Square', '1', 'Japanese easy-type edition', 'Simplified version of FFIV designed for younger audiences.', 'Follow Cecil''s journey with easier battles and unique items.', 'Play the rare Final Fantasy IV Easy Type on SNES.', 'A Japanese exclusive that removes many complex status effects and ability commands, offering a breezy 16-bit adventure through the world of Baron.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-japan', 'SNES', 'Final Fantasy IV (Japan)', '1991', 'RPG', 'Square', '1', 'Original Japanese release', 'The foundational JRPG that introduced the "Active Time Battle."', 'Save the world from the Red Wings in the original FFIV.', 'Experience the original Final Fantasy IV (Japan) on SNES.', 'The unfiltered Japanese classic. Features a higher difficulty and more complex mechanics than the initial 16-bit western release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-japan-rev-1-en-by-j2e-v321', 'SNES', 'Final Fantasy IV (Japan) (Rev 1) [En by J2e v3.21]', '1991', 'RPG', 'Square', '1', 'Fan-translated Japanese version', 'The foundational JRPG with a faithful fan translation.', 'Experience the original story of Cecil with a modern script.', 'Play Final Fantasy IV in English (J2e) on the SNES.', 'One of the first major fan translations. It restores the 16-bit dialogue and darker story elements that were censored in the official US release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-japan-rev-1-en-by-j2e-v321-bug-fix-by-deathlike2-v10a-yangs-hp-fix', 'SNES', 'Final Fantasy IV (Japan) (Rev 1) [En by J2e v3.21] [Bug Fix by Deathlike2 v1.0a] (Yang''s HP Fix)', '1991', 'RPG', 'Square', '1', 'Fan-translated version with bug fixes', 'The foundational JRPG with a faithful fan translation and bug fixes.', 'Play the translated classic with Yang''s stats fully repaired.', 'Play the fixed FFIV J2e translation on the SNES.', 'Combines the famous J2e English script with essential technical patches for a perfect and stable 16-bit RPG experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-iv-japan-rev-a', 'SNES', 'Final Fantasy IV (Japan) (Rev A)', '1991', 'RPG', 'Square', '1', 'Revised Japanese release', 'The foundational JRPG that introduced the "Active Time Battle."', 'Save the world from the Red Wings in the original FFIV.', 'Play the polished Rev A of Final Fantasy IV on SNES.', 'The updated Japanese revision, including minor graphical fixes and stability improvements for the late-game 16-bit lunar dungeons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-usa---mystic-quest-japan', 'SNES', 'Final Fantasy USA - Mystic Quest (Japan)', '1992', 'RPG', 'Square', '1', 'Japanese version of Mystic Quest', 'Entry-level JRPG with a focus on action-adventure (Japanese version).', 'Restore the four crystals to save the world.', 'Play the Japanese version of Final Fantasy USA on SNES.', 'Interestingly, this is the Japanese release of the American-made game. It features the same 16-bit action-RPG gameplay with translated text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-japan', 'SNES', 'Final Fantasy V (Japan)', '1992', 'RPG', 'Square', '1', 'Original Japanese release of Final Fantasy V', 'Deep JRPG featuring the legendary "Job System" for party customization.', 'Stop the warlock Exdeath from returning the world to the "Void."', 'Master the jobs in Final Fantasy V for the Super Famicom.', 'A masterpiece of customization. Mix and match 22 different 16-bit jobs to create the ultimate party in one of the series'' most strategic entries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-japan-en-by-rpge-v11', 'SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1]', '1992', 'RPG', 'Square', '1', 'Fan-translated English version', 'Deep JRPG featuring the legendary "Job System" with English text.', 'Experience the journey of Butz and friends in English.', 'Play the classic Final Fantasy V translation by RPGe.', 'The legendary fan translation that first brought FFV to the West. Experience the complete 16-bit story and deep job system in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-japan-en-by-rpge-v11-hack-by-jce3000gt-v0947-expert-mode', 'SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Hack by JCE3000GT v0.947] (Expert Mode)', '1992', 'RPG', 'Square', '1', 'Expert Mode difficulty hack', 'Deep JRPG modified for a much higher tactical challenge.', 'Conquer the Void in this brutal Expert Mode for FFV.', 'Challenge the Final Fantasy V Expert Mode on SNES.', 'Specifically designed for those who have mastered the job system. Features 16-bit bosses with new patterns and significantly higher stats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-japan-en-by-rpge-v11-hack-by-jce3000gt-v10-easy-type', 'SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Hack by JCE3000GT v1.0] (Easy Type)', '1992', 'RPG', 'Square', '1', 'Easy Type difficulty hack', 'Deep JRPG modified to be more accessible for new players.', 'Enjoy the job system without the punishing difficulty spikes.', 'Play Final Fantasy V Easy Type in English on SNES.', 'A re-balanced version of the RPGe translation, making the 16-bit grind less intense and the boss fights more forgiving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-japan-en-by-rpge-v11-hack-by-jorgur-v050-~final-fantasy-v-plus', 'SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Hack by Jorgur v0.50] (~Final Fantasy V Plus)', '1992', 'RPG', 'Square', '1', 'Gameplay expansion and balance hack', 'Expansion mod that adds quality-of-life features and new secrets.', 'Experience an enhanced version of the classic job system.', 'Play Final Fantasy V Plus on the Super Nintendo.', 'Includes bug fixes, Dash by default, and hidden items. A polished way to experience the 16-bit classic with modern sensibilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-japan-en-by-rpge-v11-text-hack-by-tzepish-v101-~final-fantasy-v-spoof', 'SNES', 'Final Fantasy V (Japan) [En by RPGe v1.1] [Text Hack by Tzepish v1.01] (~Final Fantasy V Spoof)', '1992', 'RPG', 'Square', '1', 'Parody and dialogue spoof hack', 'Humorous and satirical re-write of the original game''s script.', 'Save the world in this bizarre and funny parody version of FFV.', 'Laugh with the Final Fantasy V Spoof on the SNES.', 'A "joke" translation that replaces the epic 16-bit dialogue with 90s internet humor and pop culture references. Pure nostalgic chaos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-v-tweaks', 'SNES', 'Final Fantasy V Tweaks', '1992', 'RPG', 'Square', '1', 'Minor balance and quality-of-life tweaks', 'Collection of quality-of-life improvements for the original game.', 'Enjoy the definitive way to play FFV with modern fixes.', 'Experience the Final Fantasy V Tweaks mod on SNES.', 'Includes auto-dash, balanced job growth, and color correction. A must-have for players seeking the most comfortable 16-bit FFV experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vi-japan', 'SNES', 'Final Fantasy VI (Japan)', '1994', 'RPG', 'Square', '1', 'Original Japanese release of Final Fantasy VI', 'The peak of 16-bit JRPGs, featuring a massive cast and steampunk world.', 'Experience the original Japanese masterpiece of FFVI.', 'Play the legendary Final Fantasy VI on the Super Famicom.', 'The unfiltered version of the game that defined the SNES era. Experience the full 16-bit cinematic vision of the War of the Magi.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vi-japan-en-by-rpgone-v12b', 'SNES', 'Final Fantasy VI (Japan) [En by RPGOne v1.2b]', '1994', 'RPG', 'Square', '1', 'Fan-translated English version', 'The peak of 16-bit JRPGs with a faithful, modern translation.', 'Experience the most accurate English script for FFVI.', 'Play Final Fantasy VI English (RPGOne) on the SNES.', 'A highly respected translation that restores character names and nuances lost in the 16-bit era''s official localization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vi-japan-en-by-rpgone-v12b-all-bug-fixes', 'SNES', 'Final Fantasy VI (Japan) [En by RPGOne v1.2b] [All Bug Fixes]', '1994', 'RPG', 'Square', '1', 'Fan translation with all known bug fixes', 'The peak of 16-bit JRPGs with a faithful translation and all fixes.', 'Play the most stable and accurate version of FFVI.', 'Experience the definitive FFVI RPGOne (All Fixes) on SNES.', 'The ultimate version. Combines the RPGOne script with patches for every known 16-bit bug, including the Sketch and Evade glitches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vi-expanded', 'SNES', 'Final Fantasy VI Expanded', '1994', 'RPG', 'Square', '1', 'Expanded content and gameplay modification', 'A massive content mod that adds new areas and challenges to FFVI.', 'Discover new secrets in the World of Ruin.', 'Explore the Final Fantasy VI Expanded mod on SNES.', 'Adds new Espers, redesigned dungeons, and restored content. It breathes new life into the 16-bit world, offering surprises for long-time fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-europe', 'SNES', 'Final Fight (Europe)', '1991', 'Beat ''em up', 'Capcom', '2', 'European release of arcade beat ''em up', 'Iconic side-scrolling beat ''em up featuring Mike Haggar and Cody.', 'Rescue Jessica and clean up Metro City from the Mad Gear Gang.', 'Experience the arcade hit Final Fight on the SNES.', 'The game that defined the 16-bit brawler. Choose between the powerful Haggar or the agile Cody to fight through diverse urban environments and iconic bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-japan', 'SNES', 'Final Fight (Japan)', '1990', 'Beat ''em up', 'Capcom', '2', 'Original Japanese release', 'Iconic side-scrolling beat ''em up featuring Mike Haggar and Cody.', 'Rescue Jessica and clean up Metro City from the Mad Gear Gang.', 'Play the original Japanese Final Fight on the Super Famicom.', 'Features the uncensored 16-bit experience. Battle through Metro City''s streets and subways with fluid combat and massive character sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-usa', 'SNES', 'Final Fight (USA)', '1990', 'Beat ''em up', 'Capcom', '2', 'North American release', 'Iconic side-scrolling beat ''em up featuring Mike Haggar and Cody.', 'Rescue Jessica and clean up Metro City from the Mad Gear Gang.', 'Battle the Mad Gear Gang in Final Fight for the SNES.', 'Master the art of the pile-driver and the flying kick. A foundation of the 16-bit era, known for its intense action and memorable soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-2-europe', 'SNES', 'Final Fight 2 (Europe)', '1993', 'Beat ''em up', 'Capcom', '2', 'European sequel release', 'Beat ''em up sequel featuring three playable characters and a global setting.', 'Travel the world to rescue Guy''s master and fiancée from Retu.', 'Join the global battle in Final Fight 2 on the SNES.', 'Introduces Maki and Carlos alongside Haggar. Features 2-player co-op mode, taking the 16-bit fight to France, Italy, and Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-2-japan', 'SNES', 'Final Fight 2 (Japan)', '1993', 'Beat ''em up', 'Capcom', '2', 'Japanese sequel release', 'Beat ''em up sequel featuring three playable characters and a global setting.', 'Travel the world to rescue Guy''s master and fiancée from Retu.', 'Experience the original Japanese Final Fight 2 on SNES.', 'Enjoy the balanced 16-bit combat and improved character variety. Master each fighter''s unique special moves to dismantle the neo-Mad Gear threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-2-usa', 'SNES', 'Final Fight 2 (USA)', '1993', 'Beat ''em up', 'Capcom', '2', 'North American sequel release', 'Beat ''em up sequel featuring three playable characters and a global setting.', 'Travel the world to rescue Guy''s master and fiancée from Retu.', 'Master the co-op action in Final Fight 2 for the Super Nintendo.', 'A polished 16-bit brawler that refined the mechanics of the first game, offering diverse locations and secret bonus areas for players to discover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-3-europe', 'SNES', 'Final Fight 3 (Europe)', '1995', 'Beat ''em up', 'Capcom', '2', 'European third installment', 'Advanced beat ''em up featuring a branching path system and four heroes.', 'Clean up the streets of Metro City from the rising Skull Cross Gang.', 'Master the combos in Final Fight 3 for the SNES.', 'Introduces Lucia and Dean. Features multiple endings, dash attacks, and "Super" moves, making it one of the most mechanically deep 16-bit brawlers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-3-usa', 'SNES', 'Final Fight 3 (USA)', '1995', 'Beat ''em up', 'Capcom', '2', 'North American third installment', 'Advanced beat ''em up featuring a branching path system and four heroes.', 'Clean up the streets of Metro City from the rising Skull Cross Gang.', 'Experience the intense action of Final Fight 3 on SNES.', 'Utilize the AI partner mode or 2-player co-op. Explore branching 16-bit levels that change based on your choices and performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-3-usa-beta', 'SNES', 'Final Fight 3 (USA) (Beta)', '1995', 'Beat ''em up', 'Capcom', '2', 'Beta version of third installment', 'Advanced beat ''em up featuring a branching path system and four heroes.', 'Clean up the streets of Metro City from the rising Skull Cross Gang.', 'Explore the Final Fight 3 Beta version on the SNES.', 'A pre-release build showing early combat balancing and environmental assets. A unique look at the development of this 16-bit action masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-guy-japan', 'SNES', 'Final Fight Guy (Japan)', '1992', 'Beat ''em up', 'Capcom', '2', 'Japanese exclusive alternate version', 'Special edition of the first game where Cody is replaced by Guy.', 'Rescue Jessica from the Mad Gear Gang using Guy''s ninja techniques.', 'Play as the legendary ninja in Final Fight Guy on SNES.', 'Features new item placements and Guy''s faster 16-bit combat style. A rare and sought-after variant of the original beat ''em up classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-guy-usa', 'SNES', 'Final Fight Guy (USA)', '1992', 'Beat ''em up', 'Capcom', '2', 'North American alternate version', 'Special edition of the first game where Cody is replaced by Guy.', 'Rescue Jessica from the Mad Gear Gang using Guy''s ninja techniques.', 'Play as the legendary ninja in Final Fight Guy on SNES.', 'Experience the US release of this limited edition. Master Guy''s speed and unique combos to take down the 16-bit bosses of Metro City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fight-tough-japan', 'SNES', 'Final Fight Tough (Japan)', '1995', 'Beat ''em up', 'Capcom', '2', 'Japanese version with expanded content', 'Advanced beat ''em up featuring a branching path system and four heroes.', 'Clean up the streets of Metro City from the rising Skull Cross Gang.', 'Experience the original Final Fight Tough on Super Famicom.', 'The Japanese title for Final Fight 3. Features the complete, unedited 16-bit experience with all secret paths and special moves intact.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-knockout-japan', 'SNES', 'Final Knockout (Japan)', '1992', 'Fighting', 'Konami', '2', 'Boxing-style fighting game', 'One-on-one boxing simulation with an emphasis on arcade-style action.', 'Win the championship belt by knocking out every rival boxer.', 'Enter the ring in Final Knockout for the Super Famicom.', 'Known as "TKO Super Championship Boxing." Features large sprites and a strategic approach to 16-bit boxing, where managing stamina and timing is key.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-stretch-japan', 'SNES', 'Final Stretch (Japan)', '1993', 'Sports', 'Namco', '2', 'Japanese track-and-field style game', 'Realistic Formula 1 racing simulation using Mode 7 for 3D effects.', 'Win the world championship by mastering international racing circuits.', 'Race for the title in Final Stretch for the Super Famicom.', 'A technical 16-bit racer that focuses on precise driving and car setups. Compete against a full grid of cars across diverse global tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finalset-japan', 'SNES', 'Finalset (Japan)', '1993', 'Puzzle', 'Kid', '2', 'Japanese-exclusive puzzle game', 'Tennis simulation with multiple court types and character stats.', 'Win the grand slam tournament by outplaying world-class rivals.', 'Hit the court in Finalset for the Super Famicom.', 'Features realistic ball physics and diverse shot types. A solid 16-bit tennis experience with multiple modes including singles and doubles tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---monshou-no-nazo-japan', 'SNES', 'Fire Emblem - Monshou no Nazo (Japan)', '1994', 'Strategy RPG', 'Nintendo', '1', 'Original Japanese release of Fire Emblem: Mystery of the Emblem', 'Strategic turn-based RPG and remake of the first Famicom title.', 'Lead Marth to reclaim the Kingdom of Altea and defeat the Shadow Dragon.', 'Experience the epic Fire Emblem: Monshou no Nazo on SNES.', 'A monumental 16-bit title. Includes both a remake of the original game and a massive new sequel, defining the core mechanics of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---monshou-no-nazo-japan-rev-a', 'SNES', 'Fire Emblem - Monshou no Nazo (Japan) (Rev A)', '1994', 'Strategy RPG', 'Nintendo', '1', 'Revised Japanese version with minor fixes', 'Strategic turn-based RPG and remake of the first Famicom title.', 'Lead Marth to reclaim the Kingdom of Altea and defeat the Shadow Dragon.', 'Play the refined Rev A version of Monshou no Nazo on SNES.', 'The updated Japanese revision featuring minor balance tweaks and bug fixes for a more stable 16-bit tactical experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---monshou-no-nazo-japan-en-by-rpguy96-v098-~fire-emblem---mystery-of-the-emblem', 'SNES', 'Fire Emblem - Monshou no Nazo (Japan) [En by RPGuy96 v0.98] (~Fire Emblem - Mystery of the Emblem)', '1994', 'Strategy RPG', 'Nintendo', '1', 'Fan-translated English version', 'Strategic turn-based RPG and remake of the first Famicom title.', 'Follow Marth''s legendary journey with a full English translation.', 'Play Fire Emblem: Mystery of the Emblem in English on SNES.', 'The RPGuy96 translation allows Western fans to fully enjoy the intricate 16-bit political plot and permadeath strategy of Marth''s saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---seisen-no-keifu-japan', 'SNES', 'Fire Emblem - Seisen no Keifu (Japan)', '1996', 'Strategy RPG', 'Nintendo', '1', 'Original Japanese release of Genealogy of the Holy War', 'Tactical JRPG featuring a massive generational story and large maps.', 'Lead Sigurd and his son Seliph to restore peace to the continent.', 'Experience the masterpiece Fire Emblem: Seisen no Keifu on SNES.', 'Known for its sprawling 16-bit maps and the "Love" system that determines the stats and skills of the second generation of heroes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---seisen-no-keifu-japan-en-by-dark-twilkitri-net-v087d-~fire-emblem---genealogy-of-the-holy-war', 'SNES', 'Fire Emblem - Seisen no Keifu (Japan) [En by Dark Twilkitri Net v0.87d] (~Fire Emblem - Genealogy of the Holy War)', '1996', 'Strategy RPG', 'Nintendo', '1', 'Fan-translated English version (Dark Twilkitri Net)', 'Tactical JRPG featuring a massive generational story and large maps.', 'Experience the epic "Holy War" story with English text.', 'Play FE: Genealogy of the Holy War in English on the SNES.', 'An essential fan translation that brings the dark and mature 16-bit narrative of the Jugdral continent to English-speaking audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---seisen-no-keifu-japan-en-by-miacis-v101', 'SNES', 'Fire Emblem - Seisen no Keifu (Japan) [En by Miacis v1.01]', '1996', 'Strategy RPG', 'Nintendo', '1', 'Fan-translated English version (Miacis)', 'Tactical JRPG featuring a massive generational story and large maps.', 'Experience the epic "Holy War" story with a refined English script.', 'Play FE: Genealogy of the Holy War (Miacis) on the SNES.', 'A more modern and polished English translation, focusing on narrative flow and character consistency in this 16-bit strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---thracia-776---reverse-boss-recruitment', 'SNES', 'Fire Emblem - Thracia 776 - Reverse Boss Recruitment', '1999', 'Strategy RPG', 'Nintendo', '1', 'Gameplay hack enabling reverse boss recruitment', 'Strategic turn-based RPG fan modification with a unique recruitment twist.', 'Experience the hardest FE game with reversed boss roles.', 'Play the FE: Thracia 776 Reverse Boss mod on the SNES.', 'A creative hack that allows you to recruit bosses instead of standard units, offering a completely fresh 16-bit tactical challenge for veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---thracia-776-english', 'SNES', 'Fire Emblem - Thracia 776 (English)', '1999', 'Strategy RPG', 'Nintendo', '1', 'English fan translation of Thracia 776', 'Tactical JRPG known for its high difficulty and complex mechanics.', 'Lead Leif''s liberation army through the hardest battles in the series.', 'Play Fire Emblem: Thracia 776 in English on the SNES.', 'The final 16-bit Fire Emblem. Features the "Fatigue" and "Capture" systems, demanding absolute tactical mastery from the player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---thracia-776-japan', 'SNES', 'Fire Emblem - Thracia 776 (Japan)', '1999', 'Strategy RPG', 'Nintendo', '1', 'Original Japanese release of Thracia 776', 'Tactical JRPG known for its high difficulty and complex mechanics.', 'Lead Leif''s liberation army through the hardest battles in the series.', 'Experience the original Thracia 776 on the Super Famicom.', 'Originally a late-gen release. Features some of the most intricate map designs and challenging 16-bit scenarios ever created by Intelligent Systems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---thracia-776-japan-np', 'SNES', 'Fire Emblem - Thracia 776 (Japan) (NP)', '1999', 'Strategy RPG', 'Nintendo', '1', 'Nintendo Power flash cartridge release', 'Tactical JRPG known for its high difficulty and complex mechanics.', 'Lead Leif''s liberation army through the hardest battles in the series.', 'Discover the Nintendo Power version of Thracia 776.', 'The initial release via the NP flash service. Features the complete 16-bit tactical experience that solidified the series'' hardcore reputation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---thracia-776-japan-rev-a-np', 'SNES', 'Fire Emblem - Thracia 776 (Japan) (Rev A) (NP)', '1999', 'Strategy RPG', 'Nintendo', '1', 'Revised Nintendo Power release', 'Tactical JRPG known for its high difficulty and complex mechanics.', 'Lead Leif''s liberation army through the hardest battles in the series.', 'Play the refined Rev A (NP) version of Thracia 776 on SNES.', 'The final official 16-bit revision, fixing several minor technical issues and balancing certain map triggers for a smoother gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-emblem---thracia-776-japan-en-by-shaya-v005-incomplete', 'SNES', 'Fire Emblem - Thracia 776 (Japan) [En by Shaya v0.05] (Incomplete)', '1999', 'Strategy RPG', 'Nintendo', '1', 'Incomplete English fan translation', 'Tactical JRPG known for its high difficulty and complex mechanics.', 'Experience the technical 16-bit combat with partial English text.', 'Explore the FE: Thracia 776 (Shaya) translation on the SNES.', 'One of the earliest translation efforts for this title. While incomplete, it laid the groundwork for future 16-bit fans to enjoy the game''s deep strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-fighting-japan', 'SNES', 'Fire Fighting (Japan)', '1994', 'Action', 'Sunsoft', '2', 'Japanese-exclusive firefighting action game', 'Action-simulation focusing on firefighting and rescue operations.', 'Extinguish fires and rescue civilians within a strict time limit.', 'Experience the intense Fire Fighting on the Super Famicom.', 'Known in the West as The Ignition Factor. Use specialized gear and tactical planning to navigate burning buildings in this unique 16-bit rescue simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-pro-joshi-all-star-dream-slam-japan', 'SNES', 'Fire Pro Joshi All Star Dream Slam (Japan)', '1994', 'Sports', 'Human', '2', 'Japanese women’s professional wrestling game', 'Professional women''s wrestling featuring a massive roster of icons.', 'Win the championship by mastering grappling and strike timing.', 'Enter the ring in Fire Pro Joshi: Dream Slam on SNES.', 'A deep wrestling simulation with the iconic Fire Pro engine. Features legendary Japanese female wrestlers and a complex 16-bit move set for hardcore fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-striker-usa', 'SNES', 'Fire Striker (USA)', '1993', 'Sports', 'Action', '2', 'North American futuristic soccer title', 'Action-puzzle hybrid that plays like a combat-focused version of Arkanoid.', 'Defeat the Archmage by bouncing your warrior-ball through levels.', 'Experience the unique Fire Striker for the Super Nintendo.', 'Control your character to deflect a fireball into enemies and obstacles. A creative 16-bit blend of breakout-style mechanics and fantasy action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fire-striker-usa-beta', 'SNES', 'Fire Striker (USA) (Beta)', '1993', 'Sports', 'Action', '2', 'Beta version of Fire Striker', 'Action-puzzle hybrid that plays like a combat-focused version of Arkanoid.', 'Test the early physics and level designs of this unique hybrid.', 'Check out the Fire Striker Beta on the Super Nintendo.', 'A pre-release build featuring early mechanical tweaks. Explore how the 16-bit "ball-bouncing" combat was balanced during development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('firemen-the-europe-enfrde', 'SNES', 'Firemen, The (Europe) (En,Fr,De)', '1994', 'Action', 'Titus', '2', 'European release of firefighting action game', 'Top-down action-adventure where you play as a team of firefighters.', 'Navigate a burning skyscraper to stop a chemical fire disaster.', 'Heroic action awaits in The Firemen for the Super Nintendo.', 'Control Pete and Danny in a cinematic rescue mission. Use your hose to clear paths and fight "fire bosses" in this atmospheric 16-bit cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('firemen-the-japan', 'SNES', 'Firemen, The (Japan)', '1994', 'Action', 'Human', '2', 'Original Japanese release', 'Top-down action-adventure where you play as a team of firefighters.', 'Navigate a burning skyscraper to stop a chemical fire disaster.', 'Heroic action awaits in The Firemen for the Super Nintendo.', 'The original Japanese release of this high-intensity action game. Features beautiful 16-bit fire effects and a gripping real-time disaster narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('firemen-the-usa-proto', 'SNES', 'Firemen, The (USA) (Proto)', '1994', 'Action', 'Human', '2', 'Prototype North American version', 'Top-down action-adventure where you play as a team of firefighters.', 'Explore an unreleased prototype of the US localized version.', 'Discover The Firemen Prototype on the Super Nintendo.', 'A rare look at the cancelled North American release. It features translated text and the complete 16-bit firefighting experience that fans missed out on.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('firepower-2000-usa', 'SNES', 'Firepower 2000 (USA)', '1992', 'Action', 'Jaleco', '2', 'Arcade-style action shooter', 'Action-packed shoot ''em up with both land and air vehicles.', 'Destroy enemy forces across various terrains in a high-tech tank or jet.', 'Blast away in Firepower 2000 for the Super Nintendo.', 'Known as "Super SWIV." Features intense 2-player co-op action where one player flies a helicopter while the other drives a 16-bit armored vehicle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fireteam-rogue-usa-proto', 'SNES', 'Fireteam Rogue (USA) (Proto)', '1996', 'Action', 'Seika', '2', 'Prototype military action game', 'Action-adventure platformer with tactical combat (Unreleased Prototype).', 'Lead a rebel squad to infiltrate enemy bases and complete missions.', 'Explore the unreleased Fireteam Rogue on the Super Nintendo.', 'A sophisticated prototype featuring large sprites and complex mission objectives. A fascinating "what if" of 16-bit tactical action gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('first-queen---ornic-senki-japan', 'SNES', 'First Queen - Ornic Senki (Japan)', '1989', 'Strategy', 'RPG', 'SystemSoft', '1', 'Hybrid of a real-time strategy game and an action-RPG.', 'Unite the kingdoms and defeat the Ornic Empire in massive battles.', 'Command your army in First Queen: Ornic Senki on SNES.', 'A unique Japanese title where you control a lead hero while commanding dozens of AI soldiers in real-time 16-bit chaotic skirmishes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('first-samurai-europe', 'SNES', 'First Samurai (Europe)', '1992', 'Action', 'Virgin Interactive', '2', 'European release of sword-fighting action game', 'Action-platformer with a magical sword and Japanese folklore themes.', 'Avenge your clan and defeat the Demon King through the ages.', 'Master the blade in First Samurai for the Super Nintendo.', 'A stylish 16-bit adventure where you collect magical energy to empower your sword. Features large levels and unique environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('first-samurai-europe-beta', 'SNES', 'First Samurai (Europe) (Beta)', '1992', 'Action', 'Virgin Interactive', '2', 'Beta European version', 'Action-platformer with a magical sword and Japanese folklore themes.', 'Test the early combat and level layouts of this samurai epic.', 'Check out the First Samurai Beta on the SNES.', 'A pre-release version showing the development of the game''s unique weapon mechanics and 16-bit sprite animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('first-samurai-japan', 'SNES', 'First Samurai (Japan)', '1992', 'Action', 'Virgin Interactive', '2', 'Japanese release', 'Action-platformer with a magical sword and Japanese folklore themes.', 'Experience the original Japanese vision of this samurai quest.', 'Play the Japanese First Samurai on the Super Famicom.', 'Features the original difficulty and sound effects. Use your 16-bit ninja skills to navigate through time and defeat ancient evils.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('first-samurai-usa', 'SNES', 'First Samurai (USA)', '1992', 'Action', 'Virgin Interactive', '2', 'North American release', 'Action-platformer with a magical sword and Japanese folklore themes.', 'Avenge your clan and defeat the Demon King through the ages.', 'Master the blade in First Samurai for the Super Nintendo.', 'Defeat mythical creatures and find hidden secrets. A challenging 16-bit platformer that blends Eastern aesthetics with European game design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fishing-koushien-japan', 'SNES', 'Fishing Koushien (Japan)', '1995', 'Sports', 'Victor Interactive', '2', 'Japanese fishing tournament game', 'Deep fishing simulation with a focus on competitive tournament play.', 'Catch the biggest fish to win the prestigious Koushien tournament.', 'Cast your line in Fishing Koushien for the Super Famicom.', 'A realistic 16-bit fishing sim with detailed rod physics and multiple lures. Perfect for players who enjoy the patient strategy of professional angling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback---the-quest-for-identity-usa-enfrde', 'SNES', 'Flashback - The Quest for Identity (USA) (En,Fr,De)', '1993', 'Action-Adventure', 'Delphine Software', '2', 'North American cinematic platformer release', 'Cinematic platformer featuring rotoscoped animation and sci-fi mystery.', 'Recover your memory and stop an alien conspiracy to save Earth.', 'Experience the sci-fi epic Flashback on the SNES.', 'A masterpiece of 16-bit storytelling. Features fluid "Prince of Persia" style movement, a complex plot, and atmospheric rotoscoped cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback-europe-enfrde', 'SNES', 'Flashback (Europe) (En,Fr,De)', '1992', 'Action-Adventure', 'Delphine Software', '2', 'European release (multi-language)', 'Cinematic platformer featuring rotoscoped animation and sci-fi mystery.', 'Recover your memory and stop an alien conspiracy to save Earth.', 'Experience the sci-fi epic Flashback on the SNES.', 'The European PAL release, featuring multiple language options. Master the 16-bit gunplay and environmental puzzles in this legendary quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback-europe-enfr', 'SNES', 'Flashback (Europe) (En,Fr)', '1992', 'Action-Adventure', 'Delphine Software', '2', 'European alternate language release', 'Cinematic platformer featuring rotoscoped animation and sci-fi mystery.', 'Recover your memory and stop an alien conspiracy to save Earth.', 'Experience the sci-fi epic Flashback on the SNES.', 'A localized version for French and English speakers, ensuring the deep 16-bit narrative about Conrad Hart is accessible to all.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flashback-japan', 'SNES', 'Flashback (Japan)', '1995', 'Action-Adventure', 'Delphine Software', '2', 'Japanese release', 'Cinematic platformer featuring rotoscoped animation and sci-fi mystery.', 'Recover your memory and stop an alien conspiracy to save Earth.', 'Experience the Japanese version of Flashback on SNES.', 'The Super Famicom edition of the global hit. Features the same high-quality 16-bit rotoscoped visuals and challenging sci-fi platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the---the-treasure-of-sierra-madrock-europe', 'SNES', 'Flintstones, The - The Treasure of Sierra Madrock (Europe)', '1994', 'Platform', 'Taito', '2', 'Side-scrolling', 'Action-platformer featuring a mix of board game and side-scrolling levels.', 'Win the race to find the treasure before your rivals.', 'Join Fred Flintstone in The Treasure of Sierra Madrock.', 'Explore a 16-bit Bedrock in a game that mixes board-game progression with classic platforming action and "Mode 7" vehicle racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the---the-treasure-of-sierra-madrock-japan', 'SNES', 'Flintstones, The - The Treasure of Sierra Madrock (Japan)', '1994', 'Platform', 'Taito', '2', 'Side-scrolling', 'Action-platformer featuring a mix of board game and side-scrolling levels.', 'Win the race to find the treasure before your rivals.', 'Join Fred Flintstone in The Treasure of Sierra Madrock.', 'The Japanese release of the Picapiedra adventure. Features vibrant 16-bit graphics and the same quirky mix of gameplay styles for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the---the-treasure-of-sierra-madrock-usa', 'SNES', 'Flintstones, The - The Treasure of Sierra Madrock (USA)', '1994', 'Platform', 'Taito', '2', 'Side-scrolling', 'Action-platformer featuring a mix of board game and side-scrolling levels.', 'Win the race to find the treasure before your rivals.', 'Join Fred Flintstone in The Treasure of Sierra Madrock.', 'Navigate through the prehistoric world, play mini-games, and master the 16-bit platforming stages in this polished licensed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the-europe-enfrdeesit', 'SNES', 'Flintstones, The (Europe) (En,Fr,De,Es,It)', '1993', 'Platform', 'Taito', '2', 'Side-scrolling', 'Action-platformer based on the live-action Flintstones movie.', 'Rescue Dino and Hoppy from the hands of the evil Cliff Vandercave.', 'Play The Flintstones movie game on the Super Nintendo.', 'Features digitized-style sprites and detailed 16-bit environments inspired by the 1994 film. Master Fred''s club-swinging action to save your family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the-europe-enfrdeesit-beta', 'SNES', 'Flintstones, The (Europe) (En,Fr,De,Es,It) (Beta)', '1993', 'Platform', 'Taito', '2', 'Side-scrolling', 'Action-platformer based on the live-action Flintstones movie.', 'Test the early mechanics and movie-inspired level designs.', 'Check out The Flintstones Movie Beta for the SNES.', 'A pre-release build showing early stage layouts and character animations for this 16-bit cinematic adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the-usa-beta', 'SNES', 'Flintstones, The (USA) (Beta)', '1993', 'Platform', 'Taito', '2', 'Side-scrolling', 'Action-platformer based on the live-action Flintstones movie.', 'Test the early mechanics and movie-inspired level designs.', 'Check out The Flintstones Movie Beta for the SNES.', 'An early US-based development build. Experience how the 16-bit platforming mechanics were tuned to match the movie''s prehistoric aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the-usa-enfrdeesit', 'SNES', 'Flintstones, The (USA) (En,Fr,De,Es,It)', '1993', 'Platform', 'Taito', '2', 'Side-scrolling', 'Action-platformer based on the live-action Flintstones movie.', 'Rescue Dino and Hoppy from the hands of the evil Cliff Vandercave.', 'Play The Flintstones movie game on the Super Nintendo.', 'Experience the "modern Stone Age" family''s 16-bit debut. Navigate through Bedrock, the quarry, and beyond in this challenging licensed platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flying-hero---bugyuru-no-daibouken-japan', 'SNES', 'Flying Hero - Bugyuru no Daibouken (Japan)', '1992', 'Action Platform', 'Irem', '2', 'Side-scrolling', 'Vertical-scrolling shoot ''em up with a cute and whimsical theme.', 'Blast through waves of enemies and bosses to save the fantasy world.', 'Fly to victory in Flying Hero for the Super Famicom.', 'A colorful "cute ''em up" featuring a flying hero instead of a ship. Master the power-up system and enjoy the vibrant 16-bit art style and smooth gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('football-fury-usa', 'SNES', 'Football Fury (USA)', '1992', 'Sports', 'Taito', '2', 'Arcade-style', 'Arcade-style American football simulation with high-energy action.', 'Win the championship using powerful special plays and tackles.', 'Hit the gridiron in Football Fury for the Super Nintendo.', 'A fast-paced 16-bit football game that skips the heavy simulation for pure arcade fun. Features "Hyper" plays and intense 2-player competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('foreman-for-real-europe', 'SNES', 'Foreman For Real (Europe)', '1994', 'Sports', 'Gray Matter', '2', 'Simulation', 'Boxing simulation featuring an "over-the-shoulder" 3D-style view.', 'Climb the rankings and defeat George Foreman for the title.', 'Enter the ring in Foreman For Real for the Super Nintendo.', 'Utilizes digitized sprites and a unique perspective. Manage your stamina and land heavy punches in this 16-bit simulation of professional boxing endorsed by the legend himself.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('foreman-for-real-japan', 'SNES', 'Foreman For Real (Japan)', '1994', 'Sports', 'Gray Matter', '2', 'Simulation', 'Boxing simulation featuring an "over-the-shoulder" 3D-style view.', 'Climb the rankings and defeat George Foreman for the title.', 'Experience the Japanese version of Foreman For Real on SNES.', 'The Super Famicom release of the heavy-hitting boxing sim. Features multiple modes including Career and Exhibition with detailed 16-bit character graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('foreman-for-real-usa', 'SNES', 'Foreman For Real (USA)', '1994', 'Sports', 'Gray Matter', '2', 'Simulation', 'Boxing simulation featuring an "over-the-shoulder" 3D-style view.', 'Climb the rankings and defeat George Foreman for the title.', 'Enter the ring in Foreman For Real for the Super Nintendo.', 'Master the 16-bit defensive maneuvers and powerful hooks. A simulation-heavy boxing title that focuses on timing and ring positioning to achieve a knockout.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forer---barnum-v140', 'SNES', 'Forer - Barnum v1.40', '1995', 'Demo / Multimedia', 'Unknown', '1', 'Interactive demo', 'Technical software or homebrew utility for the SNES.', 'Experience a unique 16-bit hardware demonstration or utility.', 'Explore the Forer - Barnum utility on the Super Nintendo.', 'A specialized software tool or homebrew project. It showcases technical 16-bit capabilities, often used for testing hardware or specific code execution on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fortune-quest---dice-o-korogase-japan', 'SNES', 'Fortune Quest - Dice o Korogase (Japan)', '1991', 'Role-playing', 'Game Freak', '1', 'Turn-based', 'Board-game style RPG based on the light novel and anime series.', 'Navigate the board and defeat monsters to complete your quest.', 'Play the charming Fortune Quest on the Super Famicom.', 'A unique 16-bit hybrid of a board game and a JRPG. Roll the dice to move across the map and engage in turn-based battles with your favorite characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frank-thomas-big-hurt-baseball-europe', 'SNES', 'Frank Thomas Big Hurt Baseball (Europe)', '1994', 'Sports', 'High Score Productions', '2', 'Simulation', 'Realistic baseball simulation endorsed by "The Big Hurt" Frank Thomas.', 'Win the world series by mastering realistic pitching and batting.', 'Step up to the plate in Frank Thomas Big Hurt Baseball.', 'Features digitized players and motion-captured animations. Manage a full 16-bit roster and play through a complete season with authentic stats and gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frank-thomas-big-hurt-baseball-japan', 'SNES', 'Frank Thomas Big Hurt Baseball (Japan)', '1994', 'Sports', 'High Score Productions', '2', 'Simulation', 'Realistic baseball simulation endorsed by "The Big Hurt" Frank Thomas.', 'Win the world series by mastering realistic pitching and batting.', 'Play the Japanese version of Frank Thomas Big Hurt Baseball.', 'The Super Famicom edition of the realistic baseball sim. Experience high-fidelity 16-bit graphics and the intensity of a professional major league season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frank-thomas-big-hurt-baseball-usa', 'SNES', 'Frank Thomas Big Hurt Baseball (USA)', '1994', 'Sports', 'High Score Productions', '2', 'Simulation', 'Realistic baseball simulation endorsed by "The Big Hurt" Frank Thomas.', 'Win the world series by mastering realistic pitching and batting.', 'Step up to the plate in Frank Thomas Big Hurt Baseball.', 'Known for its realistic physics and TV-style presentation. Master the 16-bit batting mechanics to hit home runs with one of baseball''s greatest legends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frantic-flea-europe', 'SNES', 'Frantic Flea (Europe)', '1996', 'Platform', 'Human Entertainment', '2', 'Side-scrolling', 'Fast-paced side-scrolling platformer with a microscopic theme.', 'Rescue your flea friends from the evil "Inside-Outers."', 'Join the frantic fun in Frantic Flea for the SNES.', 'Control a flea in a vibrant, organic world. Use various power-ups and weapons to protect your swarm in this colorful and chaotic 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frantic-flea-europe-beta', 'SNES', 'Frantic Flea (Europe) (Beta)', '1996', 'Platform', 'Human Entertainment', '2', 'Side-scrolling', 'Fast-paced side-scrolling platformer with a microscopic theme.', 'Explore the early level designs of this frantic platformer.', 'Check out the Frantic Flea Beta version on the SNES.', 'A pre-release development build. Discover initial mechanical tweaks and sprite designs for this high-speed 16-bit insect odyssey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frantic-flea-usa', 'SNES', 'Frantic Flea (USA)', '1996', 'Platform', 'Human Entertainment', '2', 'Side-scrolling', 'Fast-paced side-scrolling platformer with a microscopic theme.', 'Rescue your flea friends from the evil "Inside-Outers."', 'Experience the chaotic Frantic Flea on the Super Nintendo.', 'Navigate through bizarre, fleshy levels and master the flea''s unique physics. A quirky and visually distinct 16-bit platforming challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-usa', 'SNES', 'Frogger (USA)', '1997', 'Action', 'Parker Brothers', '2', 'Arcade-style', 'Modern remake of the arcade classic with updated 16-bit graphics.', 'Guide the frog safely across the road and river to its home.', 'Play the timeless Frogger on the Super Nintendo.', 'A late-gen release that brings the classic arcade gameplay to the SNES. Features improved 16-bit visuals, new hazards, and the same addictive loop of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-tv-animation-slam-dunk---dream-team---shueisha-limited-japan', 'SNES', 'From TV Animation Slam Dunk - Dream Team - Shueisha Limited (Japan)', '1994', 'Sports', 'Toei Animation', '2', 'Anime-style', 'Basketball simulation based on the hit anime and manga.', 'Lead Hanamichi Sakuragi and the Shohoku team to victory.', 'Experience Slam Dunk: Dream Team on the Super Famicom.', 'A limited edition release featuring a focus on team management and special anime-style sequences during intense 16-bit basketball matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-tv-animation-slam-dunk---sd-heat-up!!-japan', 'SNES', 'From TV Animation Slam Dunk - SD Heat Up!! (Japan)', '1994', 'Sports', 'Toei Animation', '2', 'Anime-style', 'Basketball game featuring a "super-deformed" (SD) character style.', 'Win the tournament with cute but powerful versions of the cast.', 'Play the high-energy Slam Dunk: SD Heat Up on SNES.', 'Features fast-paced arcade gameplay and flashy special moves. A fun and visually charming 16-bit take on the Slam Dunk basketball universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-tv-animation-slam-dunk---shikyou-gekitotsu!!-japan', 'SNES', 'From TV Animation Slam Dunk - Shikyou Gekitotsu!! (Japan)', '1995', 'Sports', 'Toei Animation', '2', 'Anime-style', 'Basketball simulation featuring realistic proportions and anime story.', 'Experience the high-school basketball drama of Shohoku.', 'Join the match in Slam Dunk: Shikyou Gekitotsu on SNES.', 'Focuses on the rivalry between teams. Master the timing for dunks and rebounds in this authentic 16-bit adaptation of the legendary sports anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-tv-animation-slam-dunk-2---ih-yosen-kanzen-ban!!-japan', 'SNES', 'From TV Animation Slam Dunk 2 - IH Yosen Kanzen Ban!! (Japan)', '1995', 'Sports', 'Toei Animation', '2', 'Anime-style', 'Comprehensive basketball sequel covering the Inter-High tournament.', 'Lead Shohoku to the national championship in this ultimate version.', 'Play the definitive Slam Dunk 2 on the Super Famicom.', 'The most complete Slam Dunk game on the system. Features a deep story mode, improved 16-bit visuals, and a massive roster of rival high school players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-japan', 'SNES', 'Front Mission (Japan)', '1995', 'Tactical RPG', 'Square', '1', 'Turn-based', 'Strategic mecha-RPG featuring deep customization of "Wanzers."', 'Lead your mercenary squad through a gritty political conflict.', 'Experience the legendary Front Mission on the Super Famicom.', 'A masterpiece of mecha strategy. Customize every part of your 16-bit robot—from arms to legs—and engage in tactical grid-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-japan-rev-a', 'SNES', 'Front Mission (Japan) (Rev A)', '1995', 'Tactical RPG', 'Square', '1', 'Turn-based', 'Strategic mecha-RPG featuring deep customization of "Wanzers."', 'Lead your mercenary squad through a gritty political conflict.', 'Play the refined Front Mission (Rev A) on the SNES.', 'The updated Japanese revision with minor balance tweaks and bug fixes, ensuring a stable 16-bit tactical experience for hardcore mecha fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-japan-en-by-fh-v10b', 'SNES', 'Front Mission (Japan) [En by FH v1.0b]', '1995', 'Tactical RPG', 'Square', '1', 'Turn-based', 'Strategic mecha-RPG featuring a full English fan translation.', 'Experience the gritty mecha war story with English text.', 'Play Front Mission in English on the Super Nintendo.', 'The essential fan translation that finally allowed Western players to enjoy the deep "Wanzer" customization and mature 16-bit narrative of the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-series---gun-hazard-japan', 'SNES', 'Front Mission Series - Gun Hazard (Japan)', '1996', 'Action RPG', 'Square', '1', 'Side-scrolling', 'Side-scrolling action-RPG spin-off of the mecha series.', 'Navigate hazardous zones in your Wanzer to complete missions.', 'Experience the intense Gun Hazard for the Super Famicom.', 'Combines "Assault Suits Valken" style action with RPG progression. Upgrade your mecha and pilot to survive a sprawling 16-bit sci-fi political thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-series---gun-hazard-japan-en-by-aeon-genesis-v101', 'SNES', 'Front Mission Series - Gun Hazard (Japan) [En by Aeon Genesis v1.01]', '1996', 'Action RPG', 'Square', '1', 'Side-scrolling', 'Side-scrolling action-RPG spin-off with a full English translation.', 'Experience the action-packed mecha story in English.', 'Play Front Mission Series: Gun Hazard in English on SNES.', 'The Aeon Genesis translation brings this action-RPG masterpiece to the West. Experience the perfect blend of 16-bit shooting and deep RPG mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('full-power-japan', 'SNES', 'Full Power (Japan)', '1993', 'Action', 'NCS', '2', 'Arcade-style', 'Futuristic 3D racing game using Mode 7 and scaling effects.', 'Win the high-speed racing championship across the galaxy.', 'Race at light speed in Full Power for the Super Famicom.', 'A technical showpiece featuring fast scaling and rotation. Navigate complex 16-bit tracks and outrun futuristic rivals in this adrenaline-fueled racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('full-throttle-racing-europe', 'SNES', 'Full Throttle Racing (Europe)', '1994', 'Racing', 'Gremlin Graphics', '2', 'Simulation', 'High-speed racing game featuring bikes and diverse environments.', 'Outrun the competition in a cross-country racing tournament.', 'Experience the speed of Full Throttle Racing on the SNES.', 'Focuses on raw speed and arcade handling. Master the 16-bit tracks across various terrains, from urban streets to desert dunes, in this fast-paced title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('full-throttle-racing-usa', 'SNES', 'Full Throttle Racing (USA)', '1994', 'Racing', 'Gremlin Graphics', '2', 'Simulation', 'High-speed racing game featuring bikes and diverse environments.', 'Outrun the competition in a cross-country racing tournament.', 'Experience the speed of Full Throttle Racing on the SNES.', 'Choose your vehicle and blast through checkpoints. A solid 16-bit racer that prioritizes fun and accessible controls for fans of arcade driving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('full-throttle-racing-usa-beta', 'SNES', 'Full Throttle Racing (USA) (Beta)', '1994', 'Racing', 'Gremlin Graphics', '2', 'Simulation', 'High-speed racing game featuring bikes and diverse environments.', 'Explore the early track designs and physics of this racer.', 'Check out the Full Throttle Racing Beta on the SNES.', 'A pre-release development build showing early car and bike models. See how the 16-bit racing mechanics were refined before the final launch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fun-n-games-europe', 'SNES', 'Fun ''n Games (Europe)', '1993', 'Educational', 'Radical Entertainment', '2', 'Mini-games', 'Creative mini-game collection and art tool for young players.', 'Express your creativity through drawing and simple games.', 'Get creative with Fun ''n Games for the Super Nintendo.', 'Includes a drawing app, music composer, and various arcade-style mini-games. A versatile 16-bit tool that encourages imagination and fun for kids.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fun-n-games-usa', 'SNES', 'Fun ''n Games (USA)', '1993', 'Educational', 'Radical Entertainment', '2', 'Mini-games', 'Creative mini-game collection and art tool for young players.', 'Express your creativity through drawing and simple games.', 'Get creative with Fun ''n Games for the Super Nintendo.', 'Features the "Style Shack," music studio, and multiple 16-bit mini-games. A great educational and creative software package for the SNES era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('funaki-masakatsu-hybrid-wrestler---tougi-denshou-japan', 'SNES', 'Funaki Masakatsu Hybrid Wrestler - Tougi Denshou (Japan)', '1994', 'Wrestling', 'Human Entertainment', '2', 'Simulation', 'Professional wrestling simulation featuring a unique hybrid style.', 'Win the championship using a mix of grappling and MMA techniques.', 'Enter the ring in Hybrid Wrestler for the Super Famicom.', 'Inspired by shoot-style wrestling. Features a deep move set and realistic 16-bit grappling mechanics for fans of technical professional wrestling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('funaki-masakatsu-hybrid-wrestler---tougi-denshou-japan-en-by-phil-v10', 'SNES', 'Funaki Masakatsu Hybrid Wrestler - Tougi Denshou (Japan) [En by Phil v1.0]', '1994', 'Wrestling', 'Human Entertainment', '2', 'Simulation', 'Professional wrestling simulation with a full English fan translation.', 'Experience the technical wrestling action with English text.', 'Play Hybrid Wrestler in English on the Super Nintendo.', 'The fan translation makes the deep move lists and menu systems accessible, allowing Western fans to master this unique 16-bit wrestling sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fune-tarou-japan', 'SNES', 'Fune Tarou (Japan)', '1995', 'Action', 'Sunsoft', '1', 'Arcade-style', 'Whimsical fishing simulation featuring a story-driven adventure.', 'Travel the land and catch legendary fish to become a master.', 'Embark on a journey in Fune Tarou for the Super Famicom.', 'A charming 16-bit fishing adventure. Explore various locations, talk to NPCs, and master the art of the catch in this relaxing and colorful Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('furuta-atsuya-no-simulation-pro-yakyuu-2-japan', 'SNES', 'Furuta Atsuya no Simulation Pro Yakyuu 2 (Japan)', '1994', 'Sports', 'Namco', '1', 'Simulation', 'Deep baseball simulation focusing on strategic management and statistics.', 'Manage your team to a championship victory through tactical choices.', 'Master strategy in Furuta Atsuya no Simulation Pro Yakyuu 2.', 'A technical baseball sim endorsed by the legendary catcher. Focuses on the mental game of professional baseball with detailed 16-bit data and management screens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon-2---fuurai-no-shiren-japan', 'SNES', 'Fushigi no Dungeon 2 - Fuurai no Shiren (Japan)', '1995', 'Roguelike', 'Chunsoft', '1', 'Turn-based', 'The definitive 16-bit roguelike with turn-based movement in random dungeons.', 'Reach the top of Table Mountain to find the Golden Condor.', 'Experience the original Shiren the Wanderer on Super Famicom.', 'A masterpiece of the "Mysterious Dungeon" series. Master item management and tactical movement in ever-changing 16-bit dungeons where every death is a new beginning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon-2---fuurai-no-shiren-japan-rev-a-np', 'SNES', 'Fushigi no Dungeon 2 - Fuurai no Shiren (Japan) (Rev A) (NP)', '1995', 'Roguelike', 'Chunsoft', '1', 'Turn-based', 'The definitive 16-bit roguelike with turn-based movement in random dungeons.', 'Reach the top of Table Mountain in this refined revision.', 'Play the polished Shiren the Wanderer (Rev A) on SNES.', 'The Nintendo Power revision of the roguelike classic, featuring minor bug fixes and stability improvements for the most demanding 16-bit explorers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fushigi-no-dungeon-2---fuurai-no-shiren-japan-en-by-aeon-genesis-v10-~mysterious-dungeon-2-~-shiren-the-wanderer', 'SNES', 'Fushigi no Dungeon 2 - Fuurai no Shiren (Japan) [En by Aeon Genesis v1.0] (~Mysterious Dungeon 2 ~ Shiren the Wanderer)', '1995', 'Roguelike', 'Chunsoft', '1', 'Turn-based', 'The definitive 16-bit roguelike with turn-based movement in English.', 'Conquer the Mysterious Dungeon with a full English translation.', 'Play Shiren the Wanderer in English on the Super Nintendo.', 'The Aeon Genesis translation opens this deep roguelike to the West. Experience the beautiful 16-bit art and challenging permadeath mechanics in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('futebol-brasileiro-96', 'SNES', 'Futebol Brasileiro ''96', '1996', 'Sports', 'Unknown', '2', 'Arcade-style', 'Fan-made soccer modification based on the International Superstar Soccer engine.', 'Win the Brazilian league with updated 1996 team rosters.', 'Play the classic Futebol Brasileiro ''96 on the SNES.', 'A legendary Brazilian hack that localizes the rosters and atmosphere of 16-bit soccer, creating one of the most popular sports mods in South American history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('god---mezame-yo-to-yobu-koe-ga-kikoe-japan', 'SNES', 'G.O.D - Mezame yo to Yobu Koe ga Kikoe (Japan)', '1996', 'RPG', 'Square', '1', 'Turn-based', 'Traditional turn-based RPG set in a modern world with psychic powers.', 'Prevent a global catastrophe by uncovering ancient secrets.', 'Discover the epic G.O.D: Mezame yo on the Super Famicom.', 'A visually stunning late-gen RPG. Features a unique "Growth" system and high-quality 16-bit sprites in a story that blends science fiction with ancient mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gaia-gensouki-japan', 'SNES', 'Gaia Gensouki (Japan)', '1994', 'Action RPG', 'Enix', '1', 'Side-scrolling', 'Action-RPG following a young man with the power to transform.', 'Save the world by restoring the light to the ancient ruins.', 'Experience Gaia Gensouki (Illusion of Gaia) on the SNES.', 'The Japanese original of the beloved action-RPG. Solve environmental puzzles and transform into powerful warriors in this 16-bit journey across a mystical Earth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gaia-saver---hero-saidai-no-sakusen-japan', 'SNES', 'Gaia Saver - Hero Saidai no Sakusen (Japan)', '1994', 'Action', 'Banpresto', '1', 'Side-scrolling', 'Tactical RPG featuring iconic Japanese superheroes and robots.', 'Lead a team of heroes to stop a massive alien invasion.', 'Play the crossover epic Gaia Saver on the Super Famicom.', 'Command icons like Ultraman and Kamen Rider in grid-based 16-bit combat. Manage your squad''s energy to unleash devastating special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gakkou-de-atta-kowai-hanashi-japan', 'SNES', 'Gakkou de Atta Kowai Hanashi (Japan)', '1995', 'Adventure', 'Banpresto', '1', 'Narrative', 'Horror-themed visual novel set in a haunted high school.', 'Listen to seven scary stories and survive the night.', 'Experience the terror of Gakkou de Atta Kowai Hanashi on SNES.', 'A masterpiece of 16-bit psychological horror. Use the branching dialogue system to uncover different endings in this atmospheric and chilling Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-robo-japan', 'SNES', 'Galaxy Robo (Japan)', '1995', 'Action', 'Namco', '2', 'Arcade-style', 'Turn-based tactical strategy game featuring giant mechs.', 'Engage in intergalactic warfare and defeat the enemy robot army.', 'Master the mechs in Galaxy Robo for the Super Famicom.', 'Features detailed mecha designs and hex-based strategy. Command your fleet through deep space in this technically impressive 16-bit tactical simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-wars-japan', 'SNES', 'Galaxy Wars (Japan)', '1993', 'Shooter', 'Imagineer', '2', 'Top-down', 'Fixed-screen shooter based on the classic arcade hit.', 'Defend your ship from waves of incoming space invaders.', 'Blast aliens in Galaxy Wars for the Super Famicom.', 'A modern 16-bit take on the arcade classic. Features updated graphics and faster gameplay while retaining the addictive "shoot-and-dodge" mechanics of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gambler-jikochuushinha---mahjong-kouisen-japan', 'SNES', 'Gambler Jikochuushinha - Mahjong Kouisen (Japan)', '1992', 'Mahjong', 'Nichibutsu', '1', 'Board game', 'Competitive Mahjong simulation based on a popular manga.', 'Win the tournament by outsmarting eccentric Mahjong masters.', 'Play the tactical Gambler Jikochuushinha on the SNES.', 'A polished 16-bit Mahjong title featuring humorous character interactions and a deep career mode for fans of the traditional Japanese tile game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gambler-jikochuushinha-2---dorapon-quest-japan', 'SNES', 'Gambler Jikochuushinha 2 - Dorapon Quest (Japan)', '1994', 'RPG', 'Nichibutsu', '1', 'Turn-based', 'Mahjong simulation with a unique RPG-style quest mode.', 'Navigate a fantasy board and defeat enemies through Mahjong.', 'Experience the quest in Gambler Jikochuushinha 2 on SNES.', 'A creative blend of 16-bit RPG exploration and Mahjong matches. Use special items to tip the scales in your favor during the high-stakes "Dorapon" quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gambling-hourouki-japan', 'SNES', 'Gambling Hourouki (Japan)', '1993', 'Mahjong', 'Nichibutsu', '1', 'Board game', 'Authentic gambling simulation featuring various Japanese parlor games.', 'Travel the country and win big at different gambling halls.', 'Test your luck in Gambling Hourouki for the Super Famicom.', 'Includes realistic Mahjong and board games. Features a story-driven "wandering" mode where you manage your 16-bit finances to become a gambling legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-no-tatsujin-japan', 'SNES', 'Game no Tatsujin (Japan)', '1991', 'Trivia', 'Sunsoft', '1', 'Quiz', 'Collection of classic board and card games with a professional polish.', 'Master a variety of traditional games against skilled AI.', 'Enjoy the variety of Game no Tatsujin on the SNES.', 'Includes high-quality versions of Shogi, Go, and Mahjong. A perfect 16-bit compilation for players seeking a refined and relaxing mental challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('game-no-tetsujin---the-shanghai-japan', 'SNES', 'Game no Tetsujin - The Shanghai (Japan)', '1994', 'Puzzle', 'Sunsoft', '2', 'Tile-matching', 'Polished Mahjong and puzzle compilation focusing on the Shanghai style.', 'Clear the boards of tiles using logic and speed.', 'Master the tiles in Game no Tetsujin: The Shanghai for SNES.', 'Features various tile-matching modes and competitive play. Offers a smooth 16-bit interface and high-fidelity tile designs for a premium puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gamera---gyaos-gekimetsu-sakusen-japan', 'SNES', 'Gamera - Gyaos Gekimetsu Sakusen (Japan)', '1995', 'Action', 'Sammy', '1', 'Side-scrolling', 'Strategy-action hybrid based on the legendary kaiju Gamera.', 'Defend Japanese cities from the destructive Gyaos invasion.', 'Save Japan in Gamera: Gyaos Gekimetsu Sakusen on SNES.', 'Part tactical simulation, part monster battle. Manage defense forces and command the giant turtle Gamera in 16-bit combat against his aerial arch-nemesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon---yuki-hime-kyuushutsu-emaki-japan', 'SNES', 'Ganbare Goemon - Yuki Hime Kyuushutsu Emaki (Japan)', '1991', 'Action-Adventure', 'Konami', '2', 'Side-scrolling', 'Action-adventure hybrid with platforming and overhead exploration.', 'Rescue Princess Yuki from the ghost army in feudal Japan.', 'Join the adventure in Ganbare Goemon (The Legend of the Mystical Ninja).', 'A masterpiece of 16-bit charm. Explore vibrant towns, play mini-games, and master the pipe-wielding action in this quirky and colorful Japanese classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon---yuki-hime-kyuushutsu-emaki-japan-rev-b', 'SNES', 'Ganbare Goemon - Yuki Hime Kyuushutsu Emaki (Japan) (Rev B)', '1991', 'Action-Adventure', 'Konami', '2', 'Side-scrolling', 'Action-adventure hybrid with platforming and overhead exploration.', 'Rescue Princess Yuki from the ghost army in feudal Japan.', 'Play the refined Rev B version of Ganbare Goemon on SNES.', 'The most stable 16-bit version of the first Goemon adventure, featuring bug fixes and smoother transitions between the overhead and side-scrolling stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon-2---kiteretsu-shougun-magginesu-japan', 'SNES', 'Ganbare Goemon 2 - Kiteretsu Shougun Magginesu (Japan)', '1993', 'Action-Adventure', 'Konami', '2', 'Side-scrolling', 'Action-platformer sequel with a focus on humor and mecha combat.', 'Stop the evil Shogun and his army of clockwork soldiers.', 'Experience the hilarity of Ganbare Goemon 2 on the SNES.', 'Introduces the giant robot Impact! Enjoy 2-player co-op across 16-bit feudal Japan with improved graphics and even more eccentric mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon-3---shishi-juuroku-hyoue-no-karakuri-manjigatame-japan', 'SNES', 'Ganbare Goemon 3 - Shishi Juuroku Hyoue no Karakuri Manjigatame (Japan)', '1994', 'Action-Adventure', 'Konami', '2', 'Side-scrolling', 'Action-adventure with an open-world "Zelda-style" progression.', 'Explore a futuristic Neo-Edo to rescue your friends.', 'Discover the massive world of Ganbare Goemon 3 on SNES.', 'A shift to a more exploratory structure. Switch between four characters with unique abilities to solve 16-bit puzzles and navigate a large, interconnected world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon-kirakira-douchuu---boku-ga-dancer-ni-natta-riyuu-japan', 'SNES', 'Ganbare Goemon Kirakira Douchuu - Boku ga Dancer ni Natta Riyuu (Japan)', '1995', 'Action-Adventure', 'Konami', '2', 'Side-scrolling', 'Intergalactic action-platformer featuring bizarre comedy.', 'Travel to distant planets to find the missing Dancer.', 'Blast off in Goemon Kirakira Douchuu for the Super Famicom.', 'Features some of the best 16-bit graphics on the system. Travel across multiple planets with unique themes in this high-energy and hilarious action epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare-goemon-kirakira-douchuu---boku-ga-dancer-ni-natta-riyuu-japan-rev-b-np', 'SNES', 'Ganbare Goemon Kirakira Douchuu - Boku ga Dancer ni Natta Riyuu (Japan) (Rev B) (NP)', '1995', 'Action-Adventure', 'Konami', '2', 'Side-scrolling', 'Intergalactic action-platformer featuring bizarre comedy.', 'Travel to distant planets in the refined Rev B revision.', 'Experience the polished Goemon Kirakira Douchuu on SNES.', 'The Nintendo Power revision fixing minor timing issues in the "Impact" battles. The definitive way to enjoy this 16-bit space-traveling comedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganbare!-daiku-no-gen-san-japan', 'SNES', 'Ganbare! Daiku no Gen-san (Japan)', '1991', 'Action', 'Irem', '2', 'Arcade-style', 'Action-platformer featuring the hammer-wielding Gen-san.', 'Stop the evil construction company from taking over the city.', 'Swing the hammer in Ganbare! Daiku no Gen-san on SNES.', 'Based on the arcade classic (Hammerin'' Harry). Features fast-paced 16-bit platforming and massive bosses that require precise timing and powerful hammer strikes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gangan-gan-chan-japan', 'SNES', 'Gangan Gan-chan (Japan)', '1993', 'Action', 'Namco', '2', 'Arcade-style', 'Puzzle-action game where you guide a rolling ball through mazes.', 'Navigate through colorful obstacles to reach the goal.', 'Roll to victory in Gangan Gan-chan for the Super Famicom.', 'A cute and challenging 16-bit puzzler. Use environmental objects and special power-ups to clear paths through increasingly complex and vibrant mazes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganpuru---gunmans-proof-japan', 'SNES', 'Ganpuru - Gunman''s Proof (Japan)', '1997', 'Action RPG', 'Lenar', '1', 'Top-down', 'Action-RPG with a Wild West theme and sci-fi elements.', 'Save the frontier town from alien outlaws and mysterious monsters.', 'Experience the unique Ganpuru: Gunman''s Proof on SNES.', 'A late-gen gem. Plays like "The Legend of Zelda" with guns. Features fluid 16-bit movement, humorous dialogue, and a world full of secrets to discover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganpuru---gunmans-proof-japan-en-by-aeon-genesis-v103', 'SNES', 'Ganpuru - Gunman''s Proof (Japan) [En by Aeon Genesis v1.03]', '1997', 'Action RPG', 'Lenar', '1', 'Top-down', 'Action-RPG with a Wild West theme and sci-fi elements.', 'Experience the alien-frontier story with a full English translation.', 'Play Gunman''s Proof in English on the Super Nintendo.', 'The Aeon Genesis translation makes this 16-bit masterpiece accessible. Follow a boy possessed by an alien as he fights to save the West from intergalactic threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganso-pachi-slot-nihonichi-japan', 'SNES', 'Ganso Pachi-Slot Nihonichi (Japan)', '1995', 'Gambling', 'Coconuts Japan', '1', 'Simulation', 'Pachi-slot simulation featuring realistic slot machine mechanics.', 'Win the national slot tournament by mastering the reels.', 'Test your luck in Ganso Pachi-Slot Nihonichi on SNES.', 'A detailed 16-bit simulation of Japanese slot parlors. Manage your virtual budget and master the timing of various machines to become the number one player in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ganso-pachinko-ou-japan', 'SNES', 'Ganso Pachinko Ou (Japan)', '1993', 'Gambling', 'Coconuts Japan', '1', 'Simulation', 'Authentic Pachinko simulation with multiple machine types.', 'Master the physics of the silver balls to hit the jackpot.', 'Play the classic Ganso Pachinko Ou on the Super Famicom.', 'Experience the sights and sounds of a 16-bit Pachinko parlor. Features realistic ball physics and a variety of themed machines to master for high-score payouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu---shukumei-no-tatakai-japan', 'SNES', 'Garou Densetsu - Shukumei no Tatakai (Japan)', '1991', 'Fighting', 'SNK', '2', 'Arcade-style', 'One-on-one fighting game that launched the legendary SNK series.', 'Defeat Geese Howard and avenge your father in the King of Fighters.', 'Experience the original Garou Densetsu (Fatal Fury) on SNES.', 'The 16-bit home version of the arcade hit. Introduces the unique two-plane system where fighters can jump between foreground and background to dodge attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu---shukumei-no-tatakai-japan-rev-a', 'SNES', 'Garou Densetsu - Shukumei no Tatakai (Japan) (Rev A)', '1991', 'Fighting', 'SNK', '2', 'Arcade-style', 'One-on-one fighting game that launched the legendary SNK series.', 'Defeat Geese Howard in this refined revision.', 'Play the polished Garou Densetsu (Rev A) on the SNES.', 'An updated Japanese revision featuring minor balance tweaks and bug fixes for a smoother 16-bit combat experience against the Mad Dog, Terry Bogard.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu-2---aratanaru-tatakai-japan', 'SNES', 'Garou Densetsu 2 - Aratanaru Tatakai (Japan)', '1992', 'Fighting', 'SNK', '2', 'Arcade-style', 'Fighting game sequel with a larger roster and faster combat.', 'Defeat the new threat, Wolfgang Krauser, across the globe.', 'Master the 16-bit battle in Garou Densetsu 2 on SNES.', 'Significant improvement over the first game. Introduces iconic characters like Mai Shiranui and Kim Kaphwan with fluid animations and devastating special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu-2---aratanaru-tatakai-japan-rev-a', 'SNES', 'Garou Densetsu 2 - Aratanaru Tatakai (Japan) (Rev A)', '1992', 'Fighting', 'SNK', '2', 'Arcade-style', 'Fighting game sequel with a larger roster and faster combat.', 'Defeat the new threat, Wolfgang Krauser, across the globe.', 'Play the refined Garou Densetsu 2 (Rev A) on SNES.', 'The updated 16-bit revision that balances character damage and fixes rare sprite glitches, offering the most stable tournament experience of the sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('garou-densetsu-special-japan', 'SNES', 'Garou Densetsu Special (Japan)', '1993', 'Fighting', 'SNK', '2', 'Arcade-style', 'The ultimate 16-bit update to the Fatal Fury series.', 'Win the "Dream Match" against a massive roster of SNK legends.', 'Experience the epic Garou Densetsu Special on SNES.', 'Features the return of classic characters and a much faster gameplay speed. Master the 16-bit combos and hidden desperation moves in this fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gdleen-japan', 'SNES', 'Gdleen (Japan)', '1994', 'RPG', 'ASCII', '1', 'Turn-based', 'Traditional turn-based JRPG set in a sci-fi and fantasy world.', 'Explore the alien planet of Gdleen and stop an interstellar war.', 'Discover the sci-fi RPG Gdleen on the Super Famicom.', 'A unique RPG with a focus on exploration and party interaction. Features high-quality 16-bit character portraits and a deep, multi-layered story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gdleen-japan-rev-a', 'SNES', 'Gdleen (Japan) (Rev A)', '1994', 'RPG', 'ASCII', '1', 'Turn-based', 'Traditional turn-based JRPG set in a sci-fi and fantasy world.', 'Explore the alien planet of Gdleen and stop an interstellar war.', 'Play the polished Gdleen (Rev A) on the Super Famicom.', 'The updated revision featuring minor text fixes and balanced encounter rates for a more consistent 16-bit role-playing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gegege-no-kitarou---fukkatsu!-tenma-daiou-japan', 'SNES', 'Gegege no Kitarou - Fukkatsu! Tenma Daiou (Japan)', '1994', 'Action', 'TOSE', '1', 'Side-scrolling', 'Side-scrolling action-platformer based on the famous youkai anime.', 'Defeat the Great Demon King and his army of supernatural monsters.', 'Join Kitarou in Fukkatsu! Tenma Daiou for the SNES.', 'Utilize Kitarou''s unique youkai powers, like his needle hair and wooden clogs, to fight through eerie and beautiful 16-bit Japanese landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gegege-no-kitarou---youkai-donjara-japan-st', 'SNES', 'Gegege no Kitarou - Youkai Donjara (Japan) (ST)', '1996', 'Mahjong', 'TOMY', '4', 'Board game', 'Board-game style title using the Sufami Turbo accessory.', 'Win the youkai tournament in this unique digital board game.', 'Play the rare Gegege no Kitarou: Youkai Donjara on SNES.', 'A competitive 16-bit board game featuring the Kitarou cast. Use special items and strategy to move across the map and outsmart your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekisou-sentai-car-ranger---zenkai!-racer-senshi-japan-st', 'SNES', 'Gekisou Sentai Car Ranger - Zenkai! Racer Senshi (Japan) (ST)', '1996', 'Racing', 'Banpresto', '2', 'Arcade-style', 'Futuristic mecha-racing game using the Sufami Turbo accessory.', 'Win the high-speed mecha races and protect the galaxy.', 'Race for glory in Gekisou Sentai Car Ranger for SNES.', 'A unique 16-bit racing title based on the Sentai series. Customize your vehicle and use special abilities to outpace rival mechs on sci-fi tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekitotsu-dangan-jidousha-kessen---battle-mobile-japan', 'SNES', 'Gekitotsu Dangan Jidousha Kessen - Battle Mobile (Japan)', '1995', 'Action', 'Namco', '2', 'Top-down', 'Frenetic vehicular combat and racing game with a top-down view.', 'Destroy rival vehicles and survive the high-speed highway battles.', 'Experience the intense Battle Mobile on the Super Famicom.', 'Master the art of 16-bit car combat. Use mounted weapons and ramming tactics to take down enemies in this fast-paced and explosive action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekitou-burning-pro-wrestling-japan', 'SNES', 'Gekitou Burning Pro Wrestling (Japan)', '1994', 'Wrestling', 'Human Entertainment', '2', 'Simulation', 'Deep professional wrestling simulation with a focus on custom characters.', 'Create the ultimate wrestler and win the world championship belt.', 'Enter the ring in Gekitou Burning Pro Wrestling on SNES.', 'Known for its deep "Edit Mode." Master the 16-bit grappling system and technical strikes in this highly-regarded Japanese wrestling sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekitou-burning-pro-wrestling-japan-en-by-phil-v10', 'SNES', 'Gekitou Burning Pro Wrestling (Japan) [En by Phil v1.0]', '1995', 'Wrestling', 'Human Entertainment', '2', 'Simulation', 'Deep professional wrestling simulation with a full English translation.', 'Experience the deep wrestling mechanics with English text.', 'Play Gekitou Burning Pro Wrestling in English on SNES.', 'The fan translation makes the extensive menus and character creation accessible, allowing Western fans to enjoy one of the best 16-bit wrestling engines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gemfire-usa', 'SNES', 'Gemfire (USA)', '1991', 'Strategy', 'Koei', '1', 'Turn-based', 'Tactical fantasy strategy game featuring the "Gems" of power.', 'Unite the island of Ishmeria and defeat the dark wizard Eselred.', 'Master the strategy of Gemfire for the Super Nintendo.', 'A classic Koei title. Manage your territory, recruit legendary monsters, and use the power of the 16-bit wizards to conquer rival kingdoms in turn-based war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genghis-khan-ii---clan-of-the-gray-wolf-usa', 'SNES', 'Genghis Khan II - Clan of the Gray Wolf (USA)', '1993', 'Strategy', 'Koei', '1', 'Turn-based', 'Grand-scale historical strategy game set in the Mongol Empire.', 'Unite the Mongolian tribes and conquer the world as Genghis Khan.', 'Experience Genghis Khan II: Clan of the Gray Wolf on SNES.', 'Command massive armies and manage complex diplomacy. A deep 16-bit simulation of world conquest, trade, and family legacy across multiple continents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genjuu-ryodan-japan-np', 'SNES', 'Genjuu Ryodan (Japan) (NP)', '1996', 'RPG', 'Hudson Soft', '1', 'Turn-based', 'Tactical RPG with a focus on monster recruitment and combat.', 'Lead your "Phantom Brigade" to victory in strategic battles.', 'Command the monsters in Genjuu Ryodan for the Super Famicom.', 'A late-gen strategy gem from Nintendo Power. Capture and train mythical creatures to fight in grid-based 16-bit tactical scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genocide-2-japan', 'SNES', 'Genocide 2 (Japan)', '1993', 'Shooter', 'Bits Studio', '1', 'Vertical scrolling', 'Fast-paced sci-fi side-scrolling action game with giant robots.', 'Fight through hordes of machines to reach the city of Genocide.', 'Experience the intense Genocide 2 on the Super Famicom.', 'Control a powerful mecha equipped with a laser blade. Master the fast 16-bit combat and fluid movement to survive this challenging futuristic brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genocide-2-japan-beta', 'SNES', 'Genocide 2 (Japan) (Beta)', '1993', 'Shooter', 'Bits Studio', '1', 'Vertical scrolling', 'Fast-paced sci-fi side-scrolling action game with giant robots.', 'Explore the early mecha combat and level designs of this sequel.', 'Check out the Genocide 2 Beta version on the SNES.', 'A pre-release development build. Witness the early tuning of the 16-bit robot''s movement and weapon range before the final Japanese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-foremans-ko-boxing-europe', 'SNES', 'George Foreman''s KO Boxing (Europe)', '1992', 'Boxing', 'Acclaim', '2', 'Sports', 'Arcade-style boxing game with large character sprites.', 'Defeat a series of eccentric boxers to claim the world title.', 'Hit the ring in George Foreman''s KO Boxing on the SNES.', 'A fun and accessible 16-bit boxing game. Focuses on timing your punches and dodges while managing your stamina against large, colorful opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-foremans-ko-boxing-usa', 'SNES', 'George Foreman''s KO Boxing (USA)', '1992', 'Boxing', 'Acclaim', '2', 'Sports', 'Arcade-style boxing game with large character sprites.', 'Defeat a series of eccentric boxers to claim the world title.', 'Hit the ring in George Foreman''s KO Boxing on the SNES.', 'Master the patterns of each rival boxer. A classic 16-bit sports title that emphasizes arcade action over complex simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-foremans-ko-boxing-usa-doritos-promo', 'SNES', 'George Foreman''s KO Boxing (USA) (Doritos Promo)', '1992', 'Boxing', 'Acclaim', '2', 'Sports', 'Arcade-style boxing game with a unique snack-brand promotion.', 'Win the championship in this special promotional version.', 'Play the rare Doritos Promo version of KO Boxing on SNES.', 'A unique promotional release featuring Doritos branding within the game. A rare 16-bit curiosity for collectors of licensed sports titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('george-foremans-ko-boxing-usa-rev-a', 'SNES', 'George Foreman''s KO Boxing (USA) (Rev A)', '1992', 'Boxing', 'Acclaim', '2', 'Sports', 'Arcade-style boxing game with large character sprites.', 'Defeat a series of eccentric boxers in the refined Rev A version.', 'Play the polished George Foreman''s KO Boxing on SNES.', 'The updated 16-bit revision featuring minor bug fixes and improved hit detection for a more consistent and fair boxing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('get-in-the-hole-japan', 'SNES', 'Get in the Hole (Japan)', '1997', 'Golf', 'Sigma Enterprises', '1', 'Sports', 'Whimsical golf simulation featuring colorful characters and courses.', 'Win the tournament by mastering the wind and terrain.', 'Tee off in Get in the Hole for the Super Famicom.', 'A fun and stylized 16-bit golf game. Features intuitive controls and a variety of imaginative courses that challenge your precision and planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('getsumen-no-anubis-japan', 'SNES', 'Getsumen no Anubis (Japan)', '1994', 'Action', 'KCE Japan', '1', 'Side-scrolling', 'First-person horror adventure with a focus on investigation.', 'Uncover the dark secrets of a lunar base and survive the Anubis.', 'Experience the eerie Getsumen no Anubis on Super Famicom.', 'A unique 16-bit horror title set on the Moon. Use your investigative skills to navigate a claustrophobic base and solve environmental puzzles to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-chaser-densei-japan', 'SNES', 'Ghost Chaser Densei (Japan)', '1994', 'Action', 'Banpresto', '1', 'Side-scrolling', 'High-energy beat ''em up with deep move sets and 2-player co-op.', 'Eliminate the criminal syndicate and restore order to the city.', 'Master the combat in Ghost Chaser Densei on the SNES.', 'The Super Famicom version of the arcade hit "Denjin Makai." Features incredible 16-bit sprites and a complex combo system that rewards technical mastery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-sweeper-mikami---joreishi-wa-nice-body-japan', 'SNES', 'Ghost Sweeper Mikami - Joreishi wa Nice Body (Japan)', '1993', 'Action-adventure', 'Banpresto', '1', 'Side-scrolling', 'Side-scrolling action platformer based on the supernatural anime.', 'Exorcise ghosts and spirits to earn a massive fortune.', 'Join Reiko in Ghost Sweeper Mikami for the Super Famicom.', 'A visually polished 16-bit action game. Use Mikami''s magic rod to grapple and fight youkai in vibrant stages inspired by the iconic manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghoul-patrol-europe', 'SNES', 'Ghoul Patrol (Europe)', '1994', 'Action', 'LucasArts', '2', 'Top-down', 'Top-down action-adventure and sequel to Zombies Ate My Neighbors.', 'Save historical periods from a rogue gallery of spirits and ghouls.', 'Blast ghosts in Ghoul Patrol for the Super Nintendo.', 'Control Zeke and Julie across 16-bit urban and historical levels. Use a variety of gadgets and weapons to rescue survivors in this cult classic sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghoul-patrol-japan', 'SNES', 'Ghoul Patrol (Japan)', '1994', 'Action', 'LucasArts', '2', 'Top-down', 'Top-down action-adventure and sequel to Zombies Ate My Neighbors.', 'Save historical periods from a rogue gallery of spirits and ghouls.', 'Play the Japanese version of Ghoul Patrol on the SNES.', 'Experience the intense 16-bit ghost-hunting action. Features the same frantic gameplay and colorful graphics that defined LucasArts'' console adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghoul-patrol-usa', 'SNES', 'Ghoul Patrol (USA)', '1994', 'Action', 'LucasArts', '2', 'Top-down', 'Top-down action-adventure and sequel to Zombies Ate My Neighbors.', 'Save historical periods from a rogue gallery of spirits and ghouls.', 'Blast ghosts in Ghoul Patrol for the Super Nintendo.', 'Master the slide-jump and new power-ups. A challenging 16-bit action title that rewards quick reflexes and careful resource management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gindama-oyakata-no-pachinko-hisshouhou-japan', 'SNES', 'Gindama Oyakata no Pachinko Hisshouhou (Japan)', '1995', 'Gambling', 'Athena', '1', 'Simulation', 'Authentic Pachinko simulation with detailed machine physics.', 'Win big at the parlor by mastering the silver ball''s trajectory.', 'Test your luck in Gindama Oyakata no Pachinko on SNES.', 'A realistic 16-bit recreation of Japanese Pachinko halls. Features multiple machine types and a management mode to track your virtual earnings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ginga-eiyuu-densetsu-japan', 'SNES', 'Ginga Eiyuu Densetsu (Japan)', '1992', 'Strategy', 'Bothtec', '1', 'Turn-based', 'Grand-scale space opera strategy based on the epic anime series.', 'Command massive fleets to achieve galactic domination.', 'Master the strategy of Legend of the Galactic Heroes on SNES.', 'A deep 16-bit tactical sim where you manage resources, political alliances, and large-scale space battles involving thousands of ships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ginga-sengoku-gunyuuden-rai-japan', 'SNES', 'Ginga Sengoku Gunyuuden Rai (Japan)', '1993', 'Strategy', 'Angel', '1', 'Turn-based', 'Strategic space-warfare sim based on the "Thunder Jet" manga.', 'Conquer the galaxy by leading your fleet through tactical combat.', 'Experience Ginga Sengoku Gunyuuden Rai on the Super Famicom.', 'Combines fleet management with turn-based 16-bit combat. Command iconic starships and heroes in an epic struggle for galactic supremacy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gionbana-japan', 'SNES', 'Gionbana (Japan)', '1996', 'Adventure', 'Hect', '1', 'Visual novel', 'Traditional Japanese card game (Hanafuda) with a professional polish.', 'Defeat rival players in the classic game of Gionbana.', 'Play the traditional Gionbana on the Super Famicom.', 'Features beautiful 16-bit card art and a relaxing atmosphere. Master the rules of Koi-Koi and other hanafuda variants in this refined simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('girthbound-v19', 'SNES', 'Girthbound v1.9', '2023', 'RPG', 'Fan-made', '1', 'Turn-based', 'Surreal and humorous fan-made modification of EarthBound.', 'Experience a "weighted" adventure with new dialogue and items.', 'Explore the quirky Girthbound mod on the Super Nintendo.', 'A parody hack that changes the narrative tone and character designs. Features custom 16-bit sprites and a script full of internet-era humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-go-ackman-japan', 'SNES', 'Go Go Ackman (Japan)', '1994', 'Action', 'Toei Animation', '1', 'Side-scrolling', 'Action-platformer starring a demon boy designed by Akira Toriyama.', 'Collect souls and defeat angelic rivals to please the Dark Lord.', 'Experience the wacky Go Go Ackman on the Super Famicom.', 'A masterpiece of 16-bit character design. Use bombs and a sword to fight through colorful levels in this high-energy Toriyama classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-go-ackman-japan-en-by-ackman-v10', 'SNES', 'Go Go Ackman (Japan) [En by Ackman v1.0]', '1994', 'Action', 'Toei Animation', '1', 'Side-scrolling', 'Action-platformer starring a demon boy with a full English translation.', 'Experience the demon-boy adventure with translated text.', 'Play Go Go Ackman in English on the Super Nintendo.', 'The fan translation brings the humor and story of Ackman to the West. Enjoy the beautiful 16-bit visuals and refined platforming in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-go-ackman-2-japan', 'SNES', 'Go Go Ackman 2 (Japan)', '1995', 'Action', 'Toei Animation', '1', 'Side-scrolling', 'Action-platformer sequel with new weapons and vehicle segments.', 'Continue the soul-collecting journey and stop the Angel Corps.', 'Master the sequel Go Go Ackman 2 on the Super Famicom.', 'Adds a shop system and more diverse 16-bit levels. Master new abilities and defeat massive bosses in this polished action-packed follow-up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go-go-ackman-3-japan', 'SNES', 'Go Go Ackman 3 (Japan)', '1995', 'Action', 'Toei Animation', '1', 'Side-scrolling', 'The final entry in the trilogy featuring character-switching mechanics.', 'Switch between Ackman and Tenshi to solve puzzles and fight.', 'Play the epic Go Go Ackman 3 on the Super Famicom.', 'The most mechanically deep entry. Use the unique powers of both rivals to navigate complex 16-bit stages and finish the trilogy in style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go!-go!-dodge-league-japan', 'SNES', 'Go! Go! Dodge League (Japan)', '1993', 'Sports', 'Human Entertainment', '4', 'Arcade-style', 'Arcade-style dodgeball simulation with a focus on special moves.', 'Defeat rival schools and become the national dodgeball champion.', 'Hit the court in Go! Go! Dodge League for the SNES.', 'A fast-paced 16-bit sports title. Features flashy "super shots" and strategic team management in a colorful anime-inspired setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('go!-go!-dodge-league-japan-rev-a', 'SNES', 'Go! Go! Dodge League (Japan) (Rev A)', '1993', 'Sports', 'Human Entertainment', '4', 'Arcade-style', 'Arcade-style dodgeball simulation with a focus on special moves.', 'Defeat rival schools in this refined revision of the game.', 'Play the polished Go! Go! Dodge League (Rev A) on SNES.', 'The updated 16-bit revision featuring minor AI balancing and bug fixes for a more consistent and competitive dodgeball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goal!-usa', 'SNES', 'Goal! (USA)', '1994', 'Sports', 'Taito', '2', 'Arcade-style', 'Soccer simulation with a top-down view and simple controls.', 'Win the international cup through precise passing and shooting.', 'Kick off the action in Goal! for the Super Nintendo.', 'A classic 16-bit soccer game known for its accessibility. Features multiple team formations and weather conditions that affect the ball''s physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gods-europe', 'SNES', 'Gods (Europe)', '1991', 'Action', 'Psygnosis', '1', 'Platformer', 'Puzzle-platformer with a focus on Greek mythology and exploration.', 'Navigate ancient temples to claim the power of the gods.', 'Conquer the ancient world in Gods for the Super Nintendo.', 'A challenging Bitmap Brothers classic. Features a complex AI that adapts to your skill level and detailed 16-bit environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gods-usa', 'SNES', 'Gods (USA)', '1991', 'Action', 'Psygnosis', '1', 'Platformer', 'Puzzle-platformer with a focus on Greek mythology and exploration.', 'Navigate ancient temples to claim the power of the gods.', 'Conquer the ancient world in Gods for the Super Nintendo.', 'Known for its atmospheric 16-bit graphics and rewarding secret hunting. Use your wits and weapons to survive the trials of the gods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('godzilla---kaijuu-daikessen-japan', 'SNES', 'Godzilla - Kaijuu Daikessen (Japan)', '1993', 'Fighting', 'Toho', '2', 'Arcade fighting', 'One-on-one fighting game featuring legendary Toho monsters.', 'Battle for supremacy as Godzilla, Mothra, or King Ghidorah.', 'Experience the colossal Godzilla: Kaijuu Daikessen on SNES.', 'A visually impressive 16-bit fighter. Unleash iconic special moves and destroy cities as you fight the most famous monsters in cinema history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokinjo-boukentai-japan', 'SNES', 'Gokinjo Boukentai (Japan)', '1996', 'Adventure', 'ITL', '1', 'Action-adventure', 'Charming town-based RPG featuring a young girl and her friends.', 'Explore your neighborhood and help your neighbors with their quests.', 'Discover the heartwarming Gokinjo Boukentai on the SNES.', 'A unique 16-bit RPG that focuses on childhood wonder. Features beautiful hand-drawn art and a turn-based combat system using imaginary monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokujou-parodius-japan', 'SNES', 'Gokujou Parodius (Japan)', '1994', 'Shooter', 'Hudson Soft', '2', 'Horizontal scrolling', 'Absurdist side-scrolling shoot ''em up with a focus on humor.', 'Blast through waves of dancing penguins and flying pigs.', 'Experience the insane Gokujou Parodius on the SNES.', 'A peak 16-bit shooter. Features incredible parody stages, a huge cast of playable characters, and some of the best music on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokujou-parodius-japan-beta', 'SNES', 'Gokujou Parodius (Japan) (Beta)', '1994', 'Shooter', 'Hudson Soft', '2', 'Horizontal scrolling', 'Absurdist side-scrolling shoot ''em up with a focus on humor.', 'Test the early level designs and hilarious boss fights.', 'Check out the Gokujou Parodius Beta on the Super Famicom.', 'A pre-release development build. Witness how the 16-bit comedy and chaotic shooter mechanics were tuned before the final Japanese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-yoshi-returns', 'SNES', 'Golden Yoshi Returns', '2022', 'Platformer', 'Fan-made', '1', 'Side-scrolling', 'Fan-made mod of Yoshi''s Island with brand new levels.', 'Lead Baby Mario to safety in a completely redesigned 16-bit world.', 'Play the challenging Golden Yoshi Returns on the SNES.', 'A creative romhack that offers much higher difficulty. Features clever level design and new 16-bit puzzles for veterans of the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gon-japan', 'SNES', 'Gon (Japan)', '1994', 'Action', 'Bandai', '1', 'Platformer', 'Experimental action-platformer featuring the iconic little dinosaur.', 'Survive in a prehistoric world as the indestructible Gon.', 'Experience the unique Gon on the Super Famicom.', 'Based on the silent manga. Features beautiful 16-bit environments and a unique "no-UI" approach where you interact with the world through raw instinct.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goof-troop-europe', 'SNES', 'Goof Troop (Europe)', '1993', 'Action', 'Capcom', '2', 'Cooperative action', 'Cooperative action-puzzle adventure featuring Goofy and Max.', 'Solve environmental puzzles and defeat pirates to rescue Pete and PJ.', 'Join the fun in Goof Troop for the Super Nintendo.', 'A co-op masterpiece from Capcom. Use your wits to throw barrels, kick blocks, and outsmart enemies in this highly-regarded 16-bit puzzle-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goof-troop-france', 'SNES', 'Goof Troop (France)', '1993', 'Action', 'Capcom', '2', 'Cooperative action', 'Cooperative action-puzzle adventure featuring Goofy and Max.', 'Solve puzzles in the localized French version.', 'Jouez à Goof Troop en français sur la Super Nintendo.', 'The complete 16-bit co-op experience with localized French text. Perfect for fans of the Disney series who enjoy tactical puzzle-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goof-troop-germany', 'SNES', 'Goof Troop (Germany)', '1993', 'Action', 'Capcom', '2', 'Cooperative action', 'Cooperative action-puzzle adventure featuring Goofy and Max.', 'Solve puzzles in the localized German version.', 'Spielen Sie Goof Troop auf Deutsch für das SNES.', 'The complete 16-bit co-op experience with localized German text. Navigate the pirate island and solve complex environmental riddles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goof-troop-usa', 'SNES', 'Goof Troop (USA)', '1993', 'Action', 'Capcom', '2', 'Cooperative action', 'Cooperative action-puzzle adventure featuring Goofy and Max.', 'Solve environmental puzzles and defeat pirates to rescue Pete and PJ.', 'Join the fun in Goof Troop for the Super Nintendo.', 'Master the art of tossing items and pulling switches. One of the best 2-player 16-bit games ever made, combining Disney charm with tight design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goof-troop-st:-space-treasure-english', 'SNES', 'Goof Troop ST: Space Treasure (English)', '2021', 'Action', 'Fan-made', '2', 'Cooperative action', 'Fan-made total conversion mod of Goof Troop with a space theme.', 'Navigate a high-tech space station to find the cosmic treasure.', 'Play the Goof Troop: Space Treasure mod on the SNES.', 'A creative hack that replaces the pirate setting with a sci-fi atmosphere. Features new 16-bit graphics and challenging new puzzle layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goof-troop-st:-space-treasure-portuguese', 'SNES', 'Goof Troop ST: Space Treasure (Portuguese)', '2021', 'Action', 'Fan-made', '2', 'Cooperative action', 'Fan-made total conversion mod of Goof Troop in Portuguese.', 'Navegue pela estação espacial em português.', 'Jogue Goof Troop: Space Treasure em português no SNES.', 'The Portuguese localized version of the Space Treasure mod. Enjoy new 16-bit space puzzles with fully translated instructions and story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goofy-to-max---kaizoku-shima-no-daibouken-japan', 'SNES', 'Goofy to Max - Kaizoku Shima no Daibouken (Japan)', '1995', 'Action', 'CAPCOM', '1', 'Platformer', 'Cooperative action-puzzle adventure featuring Goofy and Max.', 'Solve environmental puzzles and defeat pirates to rescue Pete and PJ.', 'Experience the original Goofy to Max on the Super Famicom.', 'The Japanese release of the Capcom classic. Features the same brilliant 16-bit co-op mechanics and vibrant island-themed level design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('goombas-walk-a-v111-2', 'SNES', 'Goomba''s Walk, A (V1.11-2)', '2020', 'Platformer', 'Fan-made', '1', 'Side-scrolling', 'Experimental fan-made mod featuring a Goomba as the protagonist.', 'Navigate through a modified world from a Goomba''s perspective.', 'Explore the world in A Goomba''s Walk on the SNES.', 'A unique hack that flips the script on the Mario universe. Experience a short but creative 16-bit journey as one of the most iconic enemies in gaming history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gouketsuji-ichizoku-japan', 'SNES', 'Gouketsuji Ichizoku (Japan)', '1994', 'Fighting', 'Atlus', '2', 'Arcade fighting', 'One-on-one fighting game featuring a family of eccentric martial artists.', 'Win the tournament and prove the strength of the Gouketsuji clan.', 'Master the combat in Power Instinct (Gouketsuji Ichizoku) on SNES.', 'A quirky 16-bit fighter known for its unique characters, including the elderly twins Otane and Oume. Features fast-paced action and humorous special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gourmet-sentai---bara-yarou-japan', 'SNES', 'Gourmet Sentai - Bara Yarou (Japan)', '1995', 'Action', 'Future Pirates', '2', 'Beat ''em up', 'Bizarre side-scrolling beat ''em up with a cooking and nutrition theme.', 'Defeat enemies to collect ingredients and cook the perfect meal.', 'Experience the surreal Gourmet Sentai Bara Yarou on SNES.', 'A cult classic brawler. Battle strange enemies and use a unique 16-bit "cooking" mechanic between stages to regain health and boost stats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gourmet-sentai-barayarou-japan-en-by-aeon-genesis-v080-~gourmet-squadron-barayarou-incomplete', 'SNES', 'Gourmet Sentai Barayarou (Japan) [En by Aeon Genesis v0.80] (~Gourmet Squadron Barayarou) (Incomplete)', '1995', 'Action', 'Future Pirates', '2', 'Beat ''em up', 'Bizarre side-scrolling beat ''em up with a cooking and nutrition theme.', 'Experience the surreal story and cooking system with English text.', 'Play Gourmet Squadron Barayarou in English on the SNES.', 'The Aeon Genesis translation allows Western fans to understand the weird and wonderful 16-bit world of this food-based fighting masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gousou-jinrai-densetsu---musya-japan', 'SNES', 'Gousou Jinrai Densetsu - Musya (Japan)', '1994', 'Action', 'KID', '1', 'Side-scrolling', 'Side-scrolling action-platformer with a dark Japanese fantasy theme.', 'Defeat the mechanical and demonic invaders using your samurai skills.', 'Master the blade in Musya for the Super Nintendo.', 'Features an atmospheric 16-bit world based on Japanese folklore. Fight through eerie stages with a mix of traditional swordplay and magical abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-1---part-ii-usa', 'SNES', 'GP-1 - Part II (USA)', '1994', 'Racing', 'Atlus', '1', 'Formula racing', 'High-speed motorcycle racing simulation using Mode 7 technology.', 'Win the world championship by mastering international racing tracks.', 'Race to the finish in GP-1: Part II for the SNES.', 'An improved sequel featuring smoother 16-bit scaling effects and more bikes. Upgrade your machine and compete against a full grid of professional riders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-1---rapid-stream-japan', 'SNES', 'GP-1 - Rapid Stream (Japan)', '1994', 'Racing', 'Atlus', '1', 'Formula racing', 'High-speed motorcycle racing simulation using Mode 7 technology.', 'Win the world championship by mastering international racing tracks.', 'Experience the speed of GP-1: Rapid Stream on the SNES.', 'The Japanese title for the sequel. Offers refined 16-bit bike physics and challenging circuits across the globe for racing enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-1-europe', 'SNES', 'GP-1 (Europe)', '1994', 'Racing', 'Atlus', '1', 'Formula racing', 'High-speed motorcycle racing simulation using Mode 7 technology.', 'Win the world championship by mastering international racing tracks.', 'Hit the track in GP-1 for the Super Nintendo.', 'The European PAL release. Features realistic 16-bit bike handling and the "Mode 7" sense of speed that defined the early era of SNES racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-1-japan', 'SNES', 'GP-1 (Japan)', '1994', 'Racing', 'Atlus', '1', 'Formula racing', 'High-speed motorcycle racing simulation using Mode 7 technology.', 'Win the world championship by mastering international racing tracks.', 'Experience the original GP-1 on the Super Famicom.', 'The foundational 16-bit bike racer. Manage your team, choose your sponsors, and race for the top spot on the podium in diverse weather conditions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gp-1-usa', 'SNES', 'GP-1 (USA)', '1994', 'Racing', 'Atlus', '1', 'Formula racing', 'High-speed motorcycle racing simulation using Mode 7 technology.', 'Win the world championship by mastering international racing tracks.', 'Hit the track in GP-1 for the Super Nintendo.', 'Master the leaning mechanics and throttle control. A solid 16-bit racer with a focus on realism and authentic track layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gradius-iii-japan', 'SNES', 'Gradius III (Japan)', '1990', 'Shooter', 'Konami', '2', 'Horizontal shooter', 'Legendary side-scrolling shoot ''em up known for its difficulty.', 'Blast through the Bacterian Empire and stop the cosmic threat.', 'Experience the arcade hit Gradius III on the Super Famicom.', 'The original Japanese release. Features massive 16-bit bosses and a customizable weapon system that allows for deep tactical variety.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gradius-iii-usa', 'SNES', 'Gradius III (USA)', '1991', 'Shooter', 'Konami', '2', 'Horizontal shooter', 'Legendary side-scrolling shoot ''em up known for its difficulty.', 'Blast through the Bacterian Empire and stop the cosmic threat.', 'Conquer the stars in Gradius III for the Super Nintendo.', 'A benchmark of the 16-bit shooter genre. Master the power-up bar and navigate through intense bullet-hell stages and iconic environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gradius-iii-usa-sa-1-v17---base', 'SNES', 'Gradius III (USA) SA-1 (v1.7 - Base)', '1991', 'Shooter', 'Konami', '2', 'Enhanced shooter', 'Enhanced version of Gradius III using the SA-1 chip to remove lag.', 'Experience the most fluid version of the legendary shooter.', 'Play the lag-free Gradius III SA-1 mod on the SNES.', 'A technical marvel that utilizes the SA-1 chip to provide 100% smooth 16-bit gameplay, even with dozens of enemies on screen. The definitive way to play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gradius-iii-usa-sa-1-v17---origin', 'SNES', 'Gradius III (USA) SA-1 (v1.7 - Origin)', '1991', 'Shooter', 'Konami', '2', 'Enhanced shooter', 'Enhanced version of Gradius III using the SA-1 chip to remove lag.', 'Experience the original difficulty and balance without slowdown.', 'Play the lag-free Gradius III SA-1 mod on the SNES.', 'The "Origin" variant of the fix, preserving the original 16-bit game''s balancing while providing the technical stability of the SA-1 enhancement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('granhistoria---genshi-sekaiki-japan', 'SNES', 'Granhistoria - Genshi Sekaiki (Japan)', '1994', 'RPG', 'Banpresto', '1', 'Turn-based RPG', 'Turn-based RPG with a unique "chronological" storytelling system.', 'Record the history of a world by participating in its major events.', 'Discover the unique Granhistoria on the Super Famicom.', 'A rare 16-bit JRPG where you witness historical shifts. Your actions influence the future of the world map and the fate of its inhabitants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-gaiden-2-the---matsuri-da-wasshoi-japan', 'SNES', 'Great Battle Gaiden 2, The - Matsuri da Wasshoi (Japan)', '1994', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Action-platformer crossover featuring chibi versions of Japanese icons.', 'Defeat the evil forces during a massive Japanese festival.', 'Join the party in The Great Battle Gaiden 2 on SNES.', 'Part of the Compati Hero series. Play as SD versions of Gundam, Ultraman, and Kamen Rider in a fun and colorful 16-bit festival setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-ii-the---last-fighter-twin-english-v120', 'SNES', 'Great Battle II, The - Last Fighter Twin (English v1.20)', '1992', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Top-down/side-scrolling beat ''em up crossover with English text.', 'Lead the hero trio to defeat the Dark Brain in English.', 'Play The Great Battle II in English on the Super Nintendo.', 'The fan-translated version of this iconic 16-bit crossover. Control Gundam, Kamen Rider, and Ultraman in frantic co-op combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-ii-the---last-fighter-twin-japan', 'SNES', 'Great Battle II, The - Last Fighter Twin (Japan)', '1992', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling beat ''em up crossover featuring iconic heroes.', 'Defeat the Dark Brain and his army of mechanical monsters.', 'Join the heroes in The Great Battle II for the SNES.', 'A classic 16-bit brawler. Switch between legendary Japanese heroes on the fly to utilize their unique weapons and special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-iii-the-english', 'SNES', 'Great Battle III, The (English)', '1993', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling beat ''em up set in a fantasy medieval world.', 'Battle through knights and dragons with a full English translation.', 'Experience The Great Battle III in English on the SNES.', 'The fan translation brings this "Golden Axe" style 16-bit adventure to the West. Use magic and melee weapons to save the kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-iii-the-japan', 'SNES', 'Great Battle III, The (Japan)', '1993', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling beat ''em up set in a fantasy medieval world.', 'Battle through knights and dragons with the legendary hero trio.', 'Play the fantasy epic The Great Battle III on SNES.', 'A departure for the series, moving the 16-bit heroes into a medieval setting. Features deep melee combat and impressive sprite work for the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-iv-the-english', 'SNES', 'Great Battle IV, The (English)', '1994', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling run-and-gun shooter featuring mechs and heroes.', 'Infiltrate the enemy base and stop the intergalactic threat.', 'Play the action-packed The Great Battle IV in English.', 'The fan translation of the fourth entry. Features high-octane 16-bit shooting and platforming, with the ability to call in support from fellow heroes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-iv-the-japan', 'SNES', 'Great Battle IV, The (Japan)', '1994', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling run-and-gun shooter featuring mechs and heroes.', 'Infiltrate the enemy base and stop the intergalactic threat.', 'Experience the intense The Great Battle IV on SNES.', 'A peak 16-bit action title. Control iconic Japanese heroes in a "Mega Man" style shooter with massive bosses and cinematic sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-iv-the-japan-sample', 'SNES', 'Great Battle IV, The (Japan) (Sample)', '1994', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling run-and-gun shooter featuring mechs and heroes.', 'Explore an early development build of the fourth installment.', 'Check out The Great Battle IV Sample on the SNES.', 'A rare look at the game''s production. Witness early 16-bit level designs and mechanical concepts for this high-speed action crossover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-v-the-english-v120', 'SNES', 'Great Battle V, The (English v1.20)', '1995', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling action-platformer with a focus on gunplay and robots.', 'Defeat the evil robot army in this translated 16-bit adventure.', 'Play The Great Battle V in English on the Super Nintendo.', 'The final entry on the system. Features a unique "Wild West" and sci-fi theme with refined 16-bit shooting mechanics and diverse mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-battle-v-the-japan', 'SNES', 'Great Battle V, The (Japan)', '1995', 'Action', 'Banpresto', '2', 'Beat ''em up', 'Side-scrolling action-platformer with a focus on gunplay and robots.', 'Defeat the evil robot army across various themed worlds.', 'Experience the finale in The Great Battle V on the SNES.', 'Utilize a variety of ranged weapons and mecha abilities. A polished and visually impressive 16-bit conclusion to the legendary crossover series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-circus-mystery-starring-mickey-&-minnie-the-europe', 'SNES', 'Great Circus Mystery Starring Mickey & Minnie, The (Europe)', '1995', 'Platformer', 'Capcom', '2', 'Cooperative platformer', 'Side-scrolling action-platformer featuring Mickey and Minnie Mouse.', 'Rescue the circus and defeat the Baron''s forces.', 'Join Disney''s duo in The Great Circus Mystery on SNES.', 'The sequel to Magical Quest. Use various costumes with unique abilities to explore vibrant 16-bit levels. Features seamless 2-player co-op action and charming Capcom-quality animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-circus-mystery-starring-mickey-&-minnie-the-usa', 'SNES', 'Great Circus Mystery Starring Mickey & Minnie, The (USA)', '1995', 'Platformer', 'Capcom', '2', 'Cooperative platformer', 'Side-scrolling action-platformer featuring Mickey and Minnie Mouse.', 'Rescue the circus and defeat the Baron''s forces.', 'Join Disney''s duo in The Great Circus Mystery on SNES.', 'Master the Safari, Western, and Climbing outfits. A polished 16-bit Disney experience that blends clever puzzle-solving with classic Capcom platforming mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('great-waldo-search-the-usa', 'SNES', 'Great Waldo Search, The (USA)', '1992', 'Educational', 'Radiance Software', '1', 'Puzzle adventure', 'Digital hidden-object game based on the famous book series.', 'Find Waldo and specific objects within crowded, detailed scenes.', 'Search for the red-striped hero in The Great Waldo Search.', 'A faithful 16-bit adaptation of the books. Use the magnifying glass to scan massive, animated 16-bit illustrations and find Waldo before the time runs out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gt-racing-japan', 'SNES', 'GT Racing (Japan)', '1996', 'Racing', 'Imagineer', '2', 'Arcade racing', 'Isometric racing simulation with a focus on GT-class cars.', 'Win the national racing championship across diverse tracks.', 'Experience high-speed GT Racing on the Super Famicom.', 'Features realistic car handling and a variety of tuning options. A technical 16-bit racer that challenges your driving precision on winding road circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunforce---battle-fire-engulfed-terror-island-europe', 'SNES', 'Gunforce - Battle Fire Engulfed Terror Island (Europe)', '1992', 'Action', 'Irem', '2', 'Run and gun', 'Run-and-gun action shooter with heavy military themes.', 'Infiltrate Terror Island and destroy the enemy''s superweapon.', 'Blast your way through Gunforce on the Super Nintendo.', 'An arcade port from Irem. Use various vehicles like tanks and mechs to fight through 16-bit enemy bases in this fast-paced, high-octane shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunforce---battle-fire-engulfed-terror-island-japan', 'SNES', 'Gunforce - Battle Fire Engulfed Terror Island (Japan)', '1992', 'Action', 'Irem', '2', 'Run and gun', 'Run-and-gun action shooter with heavy military themes.', 'Infiltrate Terror Island and destroy the enemy''s superweapon.', 'Play the Japanese original Gunforce on the Super Famicom.', 'Experience the intense 16-bit action that laid the groundwork for the Metal Slug series. Collect powerful weapons and take down massive mechanical bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunforce---battle-fire-engulfed-terror-island-usa', 'SNES', 'Gunforce - Battle Fire Engulfed Terror Island (USA)', '1992', 'Action', 'Irem', '2', 'Run and gun', 'Run-and-gun action shooter with heavy military themes.', 'Infiltrate Terror Island and destroy the enemy''s superweapon.', 'Blast your way through Gunforce on the Super Nintendo.', 'Master the use of experimental weapon power-ups. A classic 16-bit "blast-everything" experience that rewards quick reflexes and aggressive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('habu-meijin-no-omoshiro-shougi-japan', 'SNES', 'Habu Meijin no Omoshiro Shougi (Japan)', '1993', 'Board game', 'SETA', '2', 'Shogi simulation', 'Traditional Shogi (Japanese chess) simulation with AI and tutorials.', 'Master the art of Shogi and defeat the legendary master Habu.', 'Learn Shogi with Habu Meijin on the Super Famicom.', 'Features a sophisticated AI and detailed 16-bit menus. Perfect for players looking to learn or master the traditional Japanese strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hagane---the-final-conflict-europe', 'SNES', 'Hagane - The Final Conflict (Europe)', '1994', 'Action', 'CAProduction', '1', 'Action platformer', 'Cyber-ninja action-platformer known for its high speed and difficulty.', 'Stop a rival ninja clan from destroying the world with ancient magic.', 'Experience the legendary Hagane: The Final Conflict on SNES.', 'A technical masterpiece of 16-bit action. Features complex movement mechanics, diverse sub-weapons, and some of the most fluid character animations on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hagane---the-final-conflict-usa', 'SNES', 'Hagane - The Final Conflict (USA)', '1994', 'Action', 'CAProduction', '1', 'Action platformer', 'Cyber-ninja action-platformer known for its high speed and difficulty.', 'Stop a rival ninja clan from destroying the world with ancient magic.', 'Master the blade in Hagane: The Final Conflict for SNES.', 'Rare and highly sought-after. Utilize acrobatic flips and a diverse arsenal to fight through mechanical and demonic 16-bit landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hagane-japan', 'SNES', 'Hagane (Japan)', '1994', 'Action', 'CAProduction', '1', 'Action platformer', 'Cyber-ninja action-platformer known for its high speed and difficulty.', 'Experience the original Japanese version of the ninja masterpiece.', 'Play Hagane on the Super Famicom for an intense challenge.', 'The unfiltered Japanese classic. Master the 16-bit arts of the cyber-ninja to survive punishing levels and gargantuan screen-filling bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hagane-japan-beta', 'SNES', 'Hagane (Japan) (Beta)', '1994', 'Action', 'CAProduction', '1', 'Action platformer', 'Cyber-ninja action-platformer known for its high speed and difficulty.', 'Explore early physics and level layouts in this ninja action beta.', 'Check out the Hagane Beta version on the Super Famicom.', 'A pre-release development build. Witness the tuning of the 16-bit cyber-ninja''s movement speed and the development of the game''s unique special attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hai-toride-japan', 'SNES', 'Hai Toride (Japan)', '1994', 'Puzzle', 'Nintendo', '2', 'Board-style puzzle', 'Puzzle-strategy game featuring tile-matching and grid navigation.', 'Clear the field of tiles by using logic and spatial awareness.', 'Master the puzzles in Hai Toride for the Super Famicom.', 'A polished 16-bit logic game. Navigate through increasingly difficult stages where every move must be calculated to clear the board and achieve a high score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haisei-mahjong---ryouga-japan', 'SNES', 'Haisei Mahjong - Ryouga (Japan)', '1993', 'Mahjong', 'Nichibutsu', '4', 'Traditional mahjong', 'Traditional Mahjong simulation with a focus on professional rules.', 'Defeat rival Mahjong experts and win the tournament.', 'Experience the technical Haisei Mahjong on Super Famicom.', 'Features a clean 16-bit interface and realistic AI. Offers a deep simulation of professional Mahjong play for fans of the traditional Japanese tile game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hakunetsu-pro-yakyuu---ganba-league-japan', 'SNES', 'Hakunetsu Pro Yakyuu - Ganba League (Japan)', '1992', 'Sports', 'Sega', '2', 'Baseball simulation', 'Arcade-style baseball simulation with a focus on fun and accessibility.', 'Win the baseball league by outperforming rival teams.', 'Play the energetic Ganba League on the Super Famicom.', 'Known in the West as "Extra Innings." Features a cute "chibi" art style and fast-paced 16-bit baseball action that emphasizes timing and arcade fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hakunetsu-pro-yakyuu---ganba-league-japan-rev-a', 'SNES', 'Hakunetsu Pro Yakyuu - Ganba League (Japan) (Rev A)', '1992', 'Sports', 'Sega', '2', 'Baseball simulation', 'Arcade-style baseball simulation with a focus on fun and accessibility.', 'Win the league in this refined revision of the baseball sim.', 'Play the polished Ganba League (Rev A) on SNES.', 'The updated 16-bit revision featuring minor bug fixes and improved AI batting logic for a more consistent and fair sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hakunetsu-pro-yakyuu-93---ganba-league-japan', 'SNES', 'Hakunetsu Pro Yakyuu ''93 - Ganba League (Japan)', '1993', 'Sports', 'Sega', '2', 'Baseball simulation', 'Arcade-style baseball simulation featuring updated 1993 rosters.', 'Lead your team to the pennant in the ''93 season.', 'Step up to the plate in Ganba League ''93 for the SNES.', 'Features improved 16-bit animations and more detailed stadium backgrounds. A fun and fast-paced baseball experience with a charming aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hakunetsu-pro-yakyuu-93---ganba-league-japan-beta', 'SNES', 'Hakunetsu Pro Yakyuu ''93 - Ganba League (Japan) (Beta)', '1993', 'Sports', 'Sega', '2', 'Baseball simulation', 'Arcade-style baseball simulation featuring updated 1993 rosters.', 'Test the early batting and pitching mechanics in this beta.', 'Check out the Ganba League ''93 Beta on the SNES.', 'An early development build showing the evolution of the 16-bit sports engine and character sprite animations before the final Japanese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hakunetsu-pro-yakyuu-94---ganba-league-3-japan', 'SNES', 'Hakunetsu Pro Yakyuu ''94 - Ganba League 3 (Japan)', '1994', 'Sports', 'Sega', '2', 'Baseball simulation', 'The third entry in the series featuring updated teams and graphics.', 'Master the diamond and win the championship in the ''94 season.', 'Experience Ganba League 3 on the Super Famicom.', 'The most refined entry in the trilogy. Features better 16-bit field physics and expanded team management options for a deeper baseball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hals-hole-in-one-golf-europe', 'SNES', 'HAL''s Hole in One Golf (Europe)', '1991', 'Sports', 'HAL Laboratory', '2', 'Golf simulation', 'Relaxing golf simulation featuring realistic physics and diverse courses.', 'Complete every hole with the fewest strokes possible.', 'Tee off in HAL''s Hole in One Golf on the Super Nintendo.', 'Utilizes "Mode 7" for a semi-3D view of the green. A peaceful 16-bit golf game that rewards careful wind management and precise shot power.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hals-hole-in-one-golf-usa', 'SNES', 'HAL''s Hole in One Golf (USA)', '1991', 'Sports', 'HAL Laboratory', '2', 'Golf simulation', 'Relaxing golf simulation featuring realistic physics and diverse courses.', 'Complete every hole with the fewest strokes possible.', 'Tee off in HAL''s Hole in One Golf on the Super Nintendo.', 'Master the 16-bit greens and bunkers. Features an intuitive control scheme that makes it accessible for casual players and golf enthusiasts alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hallowâ€™s-end-v104b', 'SNES', 'Hallowâ€™s End v1.04b', '2023', 'Horror', 'Fan-made', '1', 'Narrative horror', 'Fan-made total conversion mod with a dark fantasy/horror theme.', 'Navigate a haunted world and survive the Hallow''s End trials.', 'Experience the spooky Hallow''s End mod on the SNES.', 'A creative hack that transforms a classic game (often Zelda or Mario) into a brand new 16-bit horror adventure with custom assets and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamelin-no-violin-hiki-japan', 'SNES', 'Hamelin no Violin Hiki (Japan)', '1995', 'Action', 'Enix', '1', 'Action adventure', 'Puzzle-platformer where you use your companion as a tool.', 'Guide Hameln and Flute through hazards to save the world.', 'Discover Hamelin no Violin Hiki on the Super Famicom.', 'A unique 16-bit adventure. Pick up and throw your companion, Flute, or make her wear different costumes to solve environmental puzzles and defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hameln-no-violin-hiki-japan-en-by-j2e-v10-~violinist-of-hameln-the', 'SNES', 'Hameln no Violin Hiki (Japan) [En by J2e v1.0] (~Violinist of Hameln, The)', '1995', 'Action', 'Enix', '1', 'Action adventure', 'Puzzle-platformer where you use your companion as a tool.', 'Experience the unique musical adventure with English text.', 'Play The Violinist of Hameln in English on the SNES.', 'The J2e translation brings this charming and humorous 16-bit game to the West. Experience the original mechanics and quirky story with fully translated dialogue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hammerlock-wrestling-usa', 'SNES', 'Hammerlock Wrestling (USA)', '1994', 'Sports', 'Jaleco', '2', 'Arcade wrestling', 'Arcade-style professional wrestling with a unique isometric view.', 'Win the world title belt by pinning your rivals.', 'Enter the ring in Hammerlock Wrestling for the SNES.', 'Features large sprites and an emphasis on power moves. Master the 16-bit grappling system and use the ring ropes to perform devastating aerial attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hana-no-keiji---kumo-no-kanata-ni-japan', 'SNES', 'Hana no Keiji - Kumo no Kanata ni (Japan)', '1994', 'Action', 'TOSE', '1', 'Action adventure', 'Fighting game based on the popular historical manga.', 'Defeat legendary warriors and prove your strength as Keiji.', 'Battle for honor in Hana no Keiji on the Super Famicom.', 'A 16-bit one-on-one fighter with a distinct artistic style. Master Keiji''s unique weapons and special moves in a story inspired by the "Kabukimono" era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hanafuda-ou-japan', 'SNES', 'Hanafuda Ou (Japan)', '1992', 'Card game', 'Nintendo', '2', 'Traditional hanafuda', 'Traditional Hanafuda card game simulation with multiple modes.', 'Become the Hanafuda King by outplaying AI masters.', 'Play the traditional Hanafuda Ou on the Super Famicom.', 'Features beautiful 16-bit card designs and a relaxing soundtrack. Master the rules of Koi-Koi and enjoy a high-quality digital version of the classic card game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hanguk-pro-yagu-korea', 'SNES', 'Hanguk Pro Yagu (Korea)', '1994', 'Sports', 'Samsung', '2', 'Baseball simulation', 'Realistic baseball simulation featuring the Korean professional league.', 'Lead your favorite Korean team to the national championship.', 'Experience Hanguk Pro Yagu on the Super Nintendo.', 'A localized 16-bit sports title featuring authentic KBO team names and players. Offers solid baseball mechanics and a unique look at the sport in Korea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hanjuku-hero---ah-sekai-yo-hanjuku-nare!!-japan', 'SNES', 'Hanjuku Hero - Ah, Sekai yo Hanjuku Nare...!! (Japan)', '1992', 'RPG', 'Square', '1', 'Turn-based RPG', 'Real-time strategy RPG with a humorous and surreal theme.', 'Defeat rival armies using "Egg Monsters" and wacky tactics.', 'Experience the hilarious Hanjuku Hero on the Super Famicom.', 'A Square classic. Manage your kingdom and summon bizarre 16-bit creatures from eggs to fight in real-time battles filled with 90s Japanese comedy and charm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hansei-zaru-jirou-kun-no-daibouken-japan', 'SNES', 'Hansei Zaru Jirou-kun no Daibouken (Japan)', '1991', 'Action', 'Jaleco', '1', 'Comedy platformer', 'Side-scrolling platformer featuring a performing monkey.', 'Navigate through various stages to reach the circus performance.', 'Join the adventure in Hansei Zaru Jirou-kun on SNES.', 'Based on a real-life famous monkey in Japan. Features traditional 16-bit platforming where you must use agility and timing to overcome household and urban obstacles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haou-taikei-ryuu-knight---lord-of-paladin-japan', 'SNES', 'Haou Taikei Ryuu Knight - Lord of Paladin (Japan)', '1994', 'RPG', 'Sunrise', '1', 'Action RPG', 'Action-RPG based on the popular mecha anime series.', 'Control Ryuu Knight to defeat evil forces and upgrade your mecha.', 'Play the anime epic Ryuu Knight: Lord of Paladin on SNES.', 'Features a mix of top-down exploration and side-scrolling 16-bit combat. Level up your pilot and mecha while following an authentic story based on the TV show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haou-taikei-ryuu-knight---lord-of-paladin-japan-rev-a', 'SNES', 'Haou Taikei Ryuu Knight - Lord of Paladin (Japan) (Rev A)', '1994', 'RPG', 'Sunrise', '1', 'Action RPG', 'Action-RPG based on the popular mecha anime series.', 'Control Ryuu Knight to defeat evil forces in this refined version.', 'Play the polished Ryuu Knight: Lord of Paladin (Rev A) on SNES.', 'The updated 16-bit revision with minor bug fixes and improved sprite stability, offering the smoothest way to experience this mecha action-RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harapeko-bakka-japan', 'SNES', 'Harapeko Bakka (Japan)', '1995', 'Puzzle', 'Namco', '1', 'Arcade puzzle', 'Unique top-down action game featuring competitive eating mechanics.', 'Outmaneuver rivals and consume more food than anyone else.', 'Experience the quirky Harapeko Bakka on the Super Famicom.', 'Known as "Hungry Dinosaurs." A 16-bit competitive title where you must push, shove, and eat your way to victory in vibrant, hazard-filled arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardball-iii-usa', 'SNES', 'HardBall III (USA)', '1992', 'Sports', 'MindSpan', '2', 'Baseball simulation', 'Realistic baseball simulation with a focus on TV-style presentation.', 'Win the world series with professional stats and play-calling.', 'Step up to the plate in HardBall III for the Super Nintendo.', 'Features digitized play-by-play commentary and detailed player sprites. A serious 16-bit baseball sim that emphasizes realism and management depth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harleys-humongous-adventure-europe', 'SNES', 'Harley''s Humongous Adventure (Europe)', '1994', 'Platformer', 'Hi Tech Expressions', '1', 'Action platformer', 'Action-platformer where you play as a tiny hero in a giant world.', 'Navigate through a massive house and retrieve your shrinking machine.', 'Join Harley''s Humongous Adventure on the Super Nintendo.', 'Explore oversized 16-bit environments like kitchens and playrooms. Use chemical weapons and gadgets to fight household pests in this creative platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harleys-humongous-adventure-usa', 'SNES', 'Harley''s Humongous Adventure (USA)', '1994', 'Platformer', 'Hi Tech Expressions', '1', 'Action platformer', 'Action-platformer where you play as a tiny hero in a giant world.', 'Navigate through a massive house and retrieve your shrinking machine.', 'Join Harley''s Humongous Adventure on the Super Nintendo.', 'Master the use of the jetpack and grappling hook. A colorful 16-bit adventure that makes everyday objects feel like massive obstacles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harleys-humongous-adventure-usa-beta', 'SNES', 'Harley''s Humongous Adventure (USA) (Beta)', '1994', 'Platformer', 'Hi Tech Expressions', '1', 'Action platformer', 'Action-platformer where you play as a tiny hero in a giant world.', 'Test early physics and giant-sized level designs.', 'Check out Harley''s Humongous Adventure Beta on the SNES.', 'A pre-release version of the game. Discover early sprite work and how the 16-bit "miniature" scale was refined during the game''s development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harukanaru-augusta-japan', 'SNES', 'Harukanaru Augusta (Japan)', '1991', 'Sports', 'T&E Soft', '2', 'Golf simulation', 'Realistic golf simulation featuring the famous Augusta National course.', 'Master the fairways and win the prestigious Masters tournament.', 'Tee off in Harukanaru Augusta on the Super Famicom.', 'One of the first 16-bit golf games to feature digitized landscapes. Offers a slow-paced, technical simulation of professional golf with realistic wind and terrain.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harukanaru-augusta-japan-rev-b', 'SNES', 'Harukanaru Augusta (Japan) (Rev B)', '1991', 'Sports', 'T&E Soft', '2', 'Golf simulation', 'Realistic golf simulation featuring the famous Augusta National course.', 'Master the fairways in this refined 16-bit revision.', 'Play the polished Harukanaru Augusta (Rev B) on the SNES.', 'An updated Japanese version featuring improved ball physics and refined camera angles for a more accurate professional golfing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harukanaru-augusta-2---masters-japan', 'SNES', 'Harukanaru Augusta 2 - Masters (Japan)', '1992', 'Sports', 'T&E Soft', '2', 'Golf simulation', 'Advanced golf simulation sequel with updated Masters content.', 'Compete against professional golfers on legendary courses.', 'Experience Harukanaru Augusta 2: Masters on the SNES.', 'Features improved 16-bit digitized graphics and more complex green reading. A deep simulation for players who enjoy the technical side of golf.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harukanaru-augusta-3---masters-new-japan', 'SNES', 'Harukanaru Augusta 3 - Masters New (Japan)', '1993', 'Sports', 'T&E Soft', '2', 'Golf simulation', 'The most advanced entry in the 16-bit Augusta golf series.', 'Claim the Green Jacket by mastering the world''s toughest greens.', 'Play the definitive Harukanaru Augusta 3 on Super Famicom.', 'Pushes the SNES hardware to provide detailed digitized courses and professional-grade 16-bit golf mechanics, including advanced swing controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harukanaru-augusta-3---masters-new-japan-rev-a', 'SNES', 'Harukanaru Augusta 3 - Masters New (Japan) (Rev A)', '1993', 'Sports', 'T&E Soft', '2', 'Golf simulation', 'The most advanced entry in the 16-bit Augusta golf series.', 'Claim the Green Jacket in this refined Rev A version.', 'Play Harukanaru Augusta 3 (Rev A) on the Super Famicom.', 'The final 16-bit revision of the series, fixing minor data glitches and improving the AI of rival professional golfers for a fairer tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-europe', 'SNES', 'Harvest Moon (Europe)', '1994', 'Simulation', 'Amccus', '1', 'Farming simulation', 'Revolutionary farming simulation and life-management game.', 'Restore your grandfather''s farm while building relationships.', 'Start your farm life in Harvest Moon for the Super Nintendo.', 'The game that defined the genre. Manage your 16-bit crops, livestock, and schedule while trying to win the heart of a local villager in this cozy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-germany', 'SNES', 'Harvest Moon (Germany)', '1994', 'Simulation', 'Amccus', '1', 'Farming simulation', 'Revolutionary farming simulation and life-management game.', 'Restore your farm in the localized German version.', 'Spielen Sie Harvest Moon auf Deutsch für das SNES.', 'The complete 16-bit farming experience with fully localized German text. Manage your farm and social life in this beloved simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-spanish', 'SNES', 'Harvest Moon (Spanish)', '1994', 'Simulation', 'Amccus', '1', 'Farming simulation', 'Revolutionary farming simulation and life-management game.', 'Restore your farm in the localized Spanish version.', 'Juega a Harvest Moon en español para la Super Nintendo.', 'The 16-bit farming classic translated into Spanish. Clear the land, plant your crops, and build a legacy in your local language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon-usa', 'SNES', 'Harvest Moon (USA)', '1994', 'Simulation', 'Amccus', '1', 'Farming simulation', 'Revolutionary farming simulation and life-management game.', 'Restore your grandfather''s farm while building relationships.', 'Start your farm life in Harvest Moon for the Super Nintendo.', 'Clear the fields, raise cows, and get married. A deep and rewarding 16-bit experience that rewards patience and careful planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hashire-hebereke-japan', 'SNES', 'Hashire Hebereke (Japan)', '1994', 'Action', 'Sunsoft', '4', 'Party action', 'Isometric racing game featuring characters from the Hebereke series.', 'Win the race by using items and unique character abilities.', 'Race for glory in Hashire Hebereke for the Super Famicom.', 'A fast-paced 16-bit "foot racer." Choose your favorite quirky character and navigate hazard-filled tracks in this colorful and chaotic Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hat-trick-hero-japan', 'SNES', 'Hat Trick Hero (Japan)', '1992', 'Sports', 'Taito', '2', 'Soccer arcade', 'Arcade soccer simulation featuring large sprites and special moves.', 'Win the world cup and use "super shots" to defeat rivals.', 'Kick off the action in Hat Trick Hero on the Super Famicom.', 'Known as "Super Soccer Champ." A 16-bit football game that focuses on aggressive play and spectacular special moves rather than strict simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hat-trick-hero-2-japan', 'SNES', 'Hat Trick Hero 2 (Japan)', '1994', 'Sports', 'Taito', '2', 'Soccer arcade', 'Enhanced soccer sequel with more teams and refined controls.', 'Lead your nation to victory in the ultimate 16-bit tournament.', 'Experience the high-energy Hat Trick Hero 2 on SNES.', 'Features improved 16-bit animations and the ability to perform even more outrageous special shots. A fun, arcade-style take on the world''s favorite sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hatayama-hatch-no-pro-yakyuu-news!---jitsumei-ban-japan', 'SNES', 'Hatayama Hatch no Pro Yakyuu News! - Jitsumei Ban (Japan)', '1993', 'Sports', 'Namco', '2', 'Baseball simulation', 'Baseball management and simulation based on the "Pro Yakyuu News."', 'Manage your team and play through a realistic 16-bit season.', 'Step up to the plate in Hatayama Hatch no Pro Yakyuu News.', 'Features real player names and a TV-broadcast style presentation. Combines 16-bit on-field action with deep management and statistical tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hayazashi-nidan-morita-shougi-japan', 'SNES', 'Hayazashi Nidan Morita Shougi (Japan)', '1991', 'Board game', 'Sega', '2', 'Shogi board game', 'Traditional Shogi simulation featuring an advanced AI chip.', 'Defeat professional-grade AI in this technical Shogi sim.', 'Master Shogi in Hayazashi Nidan Morita Shougi on SNES.', 'Utilizes a special internal chip to provide a faster and more intelligent 16-bit opponent, making it a favorite for serious Shogi players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hayazashi-nidan-morita-shougi-2-japan', 'SNES', 'Hayazashi Nidan Morita Shougi 2 (Japan)', '1993', 'Board game', 'Sega', '2', 'Shogi board game', 'Advanced Shogi sequel with even more powerful processing.', 'Challenge the ultimate digital Shogi master on your SNES.', 'Experience the elite Hayazashi Nidan Morita Shougi 2.', 'Uses the ST010 chip for world-class 16-bit AI calculations. Offers a professional Shogi experience that was groundbreaking for home consoles at the time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('head-on-soccer-usa', 'SNES', 'Head-On Soccer (USA)', '1994', 'Sports', 'U.S. Gold', '2', 'Soccer simulation', 'Fast-paced soccer game with a focus on arcade fun and speed.', 'Score goals and win the tournament in this high-speed sim.', 'Play the energetic Head-On Soccer for the Super Nintendo.', 'Known as "Fever Pitch Soccer" in Europe. Features 16-bit players with individual stats and a variety of power-ups to tip the scales in your favor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heartthrob-memorial:-under-the-tree-of-legends', 'SNES', 'Heartthrob Memorial: Under the Tree of Legends', '1996', 'Simulation', 'Konami', '1', 'Dating simulation', 'The foundational dating simulation game (Fan Translation title).', 'Win the heart of your dream girl before graduation day.', 'Experience Heartthrob Memorial (Tokimeki Memorial) on SNES.', 'The game that popularized the dating sim genre. Balance your 16-bit school grades, fitness, and social life to find true love under the legendary tree.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hebereke-no-oishii-puzzle-wa-irimasenka-japan', 'SNES', 'Hebereke no Oishii Puzzle wa Irimasenka (Japan)', '1994', 'Puzzle', 'Sunsoft', '2', 'Competitive puzzle', 'Competitive puzzle game featuring the quirky Hebereke cast.', 'Clear your board by matching colored blocks and sabotaging rivals.', 'Solve the puzzles in Hebereke no Oishii Puzzle on SNES.', 'A charming 16-bit tile-matching game. Use character-specific special moves to overwhelm your opponent in this colorful Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hebereke-no-popoon-japan', 'SNES', 'Hebereke no Popoon (Japan)', '1992', 'Puzzle', 'Sunsoft', '2', 'Competitive puzzle', 'Fast-paced falling-block puzzle game with a humorous theme.', 'Defeat rivals in head-to-head 16-bit puzzle battles.', 'Join the fun in Hebereke no Popoon for the Super Famicom.', 'A frantic and cute 16-bit puzzler. Match heads to clear your screen and send "garbage" to your opponent in this high-energy arcade experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heberekes-popoitto-europe', 'SNES', 'Hebereke''s Popoitto (Europe)', '1995', 'Puzzle', 'Sunsoft', '2', 'Competitive puzzle', 'Falling-block puzzle game localized for the European market.', 'Match the character heads to clear the board and win.', 'Play the quirky Hebereke''s Popoitto on the SNES.', 'The PAL version of the puzzle classic. Features the same addictive 16-bit gameplay and surreal humor that made the series a cult favorite in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heberekes-popoon-europe', 'SNES', 'Hebereke''s Popoon (Europe)', '1995', 'Puzzle', 'Sunsoft', '2', 'Competitive puzzle', 'Falling-block puzzle game localized for the European market.', 'Match the character heads to clear the board and win.', 'Play the quirky Hebereke''s Popoon on the SNES.', 'A colorful 16-bit puzzle challenge for one or two players. Master the chain reactions to become the ultimate master of the Popoon world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heian-fuuunden-japan', 'SNES', 'Heian Fuuunden (Japan)', '1992', 'Action', 'Nichibutsu', '1', 'Action adventure', 'Tactical turn-based RPG set in a unique fantasy world.', 'Lead your army to restore peace to the land of Heian.', 'Experience the strategic Heian Fuuunden on the Super Famicom.', 'Features beautiful 16-bit art and a deep tactical combat system. Manage your units across diverse maps in a story inspired by Japanese history and mythology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heisei-gunjin-shougi-japan', 'SNES', 'Heisei Gunjin Shougi (Japan)', '1993', 'Board game', 'ASCII', '2', 'Military shogi', 'Strategy board game based on traditional military Shogi.', 'Outmaneuver your opponent and capture their flag or commander.', 'Play the tactical Heisei Gunjin Shougi on the Super Famicom.', 'A modern 16-bit take on the classic "Military Shogi." Use hidden unit types and strategic movement to outsmart the AI or a friend in this tense game of logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heisei-inu-monogatari-bow---popn-smash!!-japan', 'SNES', 'Heisei Inu Monogatari Bow - Pop''n Smash!! (Japan)', '1994', 'Action', 'Sunsoft', '2', 'Arcade action', 'Arcade-style air hockey/tennis game featuring the dog Bow.', 'Score points by smashing the puck past your opponent.', 'Join the fun in Bow: Pop''n Smash for the Super Famicom.', 'Based on the popular anime. Features fast-paced 16-bit arcade action with special power-ups and vibrant, humorous character animations in every match.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heisei-shin-onigashima---kouhen-japan', 'SNES', 'Heisei Shin Onigashima - Kouhen (Japan)', '1992', 'Adventure', 'Nintendo', '1', 'Text adventure', 'Cinematic visual novel and adventure game (The Conclusion).', 'Solve the mystery of the Oni island in this final chapter.', 'Complete the epic Heisei Shin Onigashima on the SNES.', 'The second half of Nintendo''s legendary adventure remake. Features beautiful 16-bit illustrations and a deep branching narrative based on Japanese folklore.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heisei-shin-onigashima---zenhen-japan', 'SNES', 'Heisei Shin Onigashima - Zenhen (Japan)', '1992', 'Adventure', 'Nintendo', '1', 'Text adventure', 'Cinematic visual novel and adventure game (The Beginning).', 'Embark on a mythical journey to uncover your true destiny.', 'Experience the first part of Heisei Shin Onigashima on SNES.', 'The opening chapter of this 16-bit masterpiece. Navigate through dialogue choices and environmental puzzles in a beautifully told fairy tale world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heiwa-pachinko-world-japan', 'SNES', 'Heiwa Pachinko World (Japan)', '1995', 'Gambling', 'ASCII', '1', 'Pachinko simulation', 'Authentic Pachinko simulation featuring real parlor machines.', 'Win the jackpot and manage your virtual parlor winnings.', 'Test your luck in Heiwa Pachinko World for the Super Famicom.', 'A realistic 16-bit recreation of Heiwa''s famous Pachinko machines. Features accurate ball physics and multiple themed tables to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heiwa-pachinko-world-2-japan', 'SNES', 'Heiwa Pachinko World 2 (Japan)', '1995', 'Gambling', 'ASCII', '1', 'Pachinko simulation', 'Authentic Pachinko simulation with updated machine types.', 'Master the latest digital Pachinko machines to win big.', 'Experience Heiwa Pachinko World 2 on the Super Famicom.', 'An improved sequel featuring more detailed 16-bit machine graphics and a wider variety of gameplay modes, including a story-driven career path.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heiwa-pachinko-world-3-japan', 'SNES', 'Heiwa Pachinko World 3 (Japan)', '1996', 'Gambling', 'ASCII', '1', 'Pachinko simulation', 'The final entry in the Heiwa Pachinko trilogy.', 'Collect the most silver balls across multiple professional machines.', 'Play the definitive Heiwa Pachinko World 3 on the SNES.', 'The most advanced 16-bit Pachinko simulation in the series. Features high-fidelity sound effects and the most accurate ball trajectories on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heiwa-parlor!-mini-8---pachinko-jikki-simulation-game-japan', 'SNES', 'Heiwa Parlor! Mini 8 - Pachinko Jikki Simulation Game (Japan)', '1996', 'Gambling', 'Heiwa', '1', 'Pachinko simulation', 'Compact Pachinko simulation featuring a collection of mini-games.', 'Master eight different classic Pachinko machines.', 'Enjoy variety in Heiwa Parlor! Mini 8 for the Super Famicom.', 'A specialized 16-bit simulation focusing on eight legendary machines. Offers a quick-play experience for fans who want variety and realistic parlor mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello!-pac-man-japan', 'SNES', 'Hello! Pac-Man (Japan)', '1994', 'Action', 'Namco', '2', 'Arcade maze action', 'Experimental side-scrolling adventure with indirect control.', 'Guide Pac-Man through his world by using a slingshot.', 'Play the unique Hello! Pac-Man on the Super Famicom.', 'Known in the West as Pac-Man 2: The New Adventures. A 16-bit "point-and-click" hybrid where you influence Pac-Man''s mood and actions to solve puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('herakles-no-eikou-iii---kamigami-no-chinmoku-japan', 'SNES', 'Herakles no Eikou III - Kamigami no Chinmoku (Japan)', '1992', 'RPG', 'Data East', '1', 'Turn-based RPG', 'Epic turn-based RPG set in an ancient world of Greek myth.', 'Search for your lost immortality and solve the silence of the gods.', 'Experience the legendary Glory of Heracles III on SNES.', 'A masterpiece of 16-bit storytelling. Follow a protagonist who cannot die in a world filled with gods, tragedy, and deep philosophical themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('herakles-no-eikou-iii---kamigami-no-chinmoku-japan-en-by-kojiro-v095beta1-~glory-of-heracles-iii-the---silence-of-the-gods', 'SNES', 'Herakles no Eikou III - Kamigami no Chinmoku (Japan) [En by Kojiro v0.95Beta1] (~Glory of Heracles III, The - Silence of the Gods)', '1992', 'RPG', 'Data East', '1', 'Turn-based RPG', 'Epic turn-based RPG with a full English fan translation.', 'Experience the immortal hero''s journey with English text.', 'Play Glory of Heracles III in English on the Super Nintendo.', 'The Kojiro translation allows Western fans to enjoy one of the best 16-bit RPG scripts, full of mystery and mythological intrigue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('herakles-no-eikou-iv---kamigami-kara-no-okurimono-japan', 'SNES', 'Herakles no Eikou IV - Kamigami Kara no Okurimono (Japan)', '1994', 'RPG', 'Data East', '1', 'Turn-based RPG', 'Advanced turn-based RPG featuring a "spirit" system and party swapping.', 'Prevent a global catastrophe by aiding the gods of Olympus.', 'Embark on the journey in Glory of Heracles IV on SNES.', 'The final 16-bit entry. Features incredible graphics and the unique ability to transfer the hero''s soul into different bodies to solve puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hero-senki---project-olympus-japan', 'SNES', 'Hero Senki - Project Olympus (Japan)', '1992', 'RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical RPG crossover featuring iconic Japanese heroes.', 'Lead Gundam, Ultraman, and Kamen Rider to save Project Olympus.', 'Join the heroes in Hero Senki for the Super Famicom.', 'A precursor to the Super Robot Wars series. Features turn-based 16-bit combat with beautifully animated special attacks from legendary hero franchises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hi-no-ouji-yamato-takeru-japan', 'SNES', 'Hi no Ouji Yamato Takeru (Japan)', '1993', 'Action', 'Hot-B', '1', 'Action RPG', 'Action-RPG based on the ancient Japanese legend of Yamato Takeru.', 'Defeat the Orochi clan and reclaim your rightful throne.', 'Explore the mythical Hi no Ouji Yamato Takeru on SNES.', 'A visually distinct 16-bit RPG. Navigate through ancient Japan, using magical artifacts and sword skills to overcome mythological beasts and dark sorcery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('higashio-osamu-kanshuu---super-pro-yakyuu-stadium-japan', 'SNES', 'Higashio Osamu Kanshuu - Super Pro Yakyuu Stadium (Japan)', '1993', 'Sports', 'Namco', '2', 'Baseball simulation', 'Baseball simulation with a focus on coaching and strategy.', 'Lead your pro team to victory through expert management.', 'Master the diamond in Super Pro Yakyuu Stadium on SNES.', 'Endorsed by pitching legend Osamu Higashio. Features detailed 16-bit player stats and a more strategic, simulation-heavy approach to the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiouden---mamono-tachi-tono-chikai-japan', 'SNES', 'Hiouden - Mamono-tachi Tono Chikai (Japan)', '1992', 'RPG', 'Taito', '1', 'Action RPG', 'Real-time tactical RPG with a focus on monster commanding.', 'Lead the Scarlet King''s army to reclaim his lost kingdom.', 'Command the spirits in Hiouden on the Super Famicom.', 'A unique 16-bit title from Wolf Team. Use a cursor-based interface to command your party in real-time battles against humans and demons alike.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiouden---mamono-tachi-tono-chikai-japan-en-by-aeon-genesis-v10-~hiouden---legend-of-the-scarlet-king---the-demonic-oath', 'SNES', 'Hiouden - Mamono-tachi Tono Chikai (Japan) [En by Aeon Genesis v1.0] (~Hiouden - Legend of the Scarlet King - The Demonic Oath)', '1992', 'RPG', 'Taito', '1', 'Action RPG', 'Real-time tactical RPG with a full English fan translation.', 'Experience the Legend of the Scarlet King with English text.', 'Play Hiouden in English on the Super Nintendo.', 'The Aeon Genesis translation opens this complex 16-bit strategy game to the West. Manage your troops and unleash powerful spells in a dark fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiryuu-no-ken-s---golden-fighter-japan', 'SNES', 'Hiryuu no Ken S - Golden Fighter (Japan)', '1992', 'Fighting', 'Culture Brain', '2', 'Arcade fighting', 'Martial arts fighting game with a unique RPG-style story mode.', 'Win the tournament and master the secret "Hiryuu" techniques.', 'Battle for glory in Hiryuu no Ken S (Flying Dragon) on SNES.', 'A hybrid of 16-bit fighting and RPG elements. Features a "clash" system where you must predict your opponent''s next move to counter effectively.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hiryuu-no-ken-s---hyper-version-japan', 'SNES', 'Hiryuu no Ken S - Hyper Version (Japan)', '1993', 'Fighting', 'Culture Brain', '2', 'Arcade fighting', 'Enhanced fighting game with faster speed and new characters.', 'Defeat the ultimate grandmasters in this "Hyper" tournament.', 'Experience the fast-paced Hiryuu no Ken S Hyper on SNES.', 'The definitive version of the fighter. Features improved 16-bit animations and a re-balanced roster for a more competitive arcade-style experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hissatsu-pachinko-collection-japan', 'SNES', 'Hissatsu Pachinko Collection (Japan)', '1994', 'Gambling', 'Sunsoft', '1', 'Pachinko compilation', 'Comprehensive Pachinko collection with a focus on variety.', 'Unlock and master a diverse set of professional machines.', 'Play Hissatsu Pachinko Collection on the Super Famicom.', 'A high-quality 16-bit simulation of Sunsoft''s famous Pachinko lineup. Features realistic parlor atmosphere and multiple difficulty levels for enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hissatsu-pachinko-collection-2-japan', 'SNES', 'Hissatsu Pachinko Collection 2 (Japan)', '1995', 'Gambling', 'Sunsoft', '1', 'Pachinko compilation', 'Pachinko sequel featuring modernized digital machines.', 'Win the jackpot across a new set of themed machines.', 'Experience Hissatsu Pachinko Collection 2 on the SNES.', 'Features more complex machine logic and improved 16-bit visual effects. A must-play for fans of authentic digital gambling simulations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hissatsu-pachinko-collection-3-japan', 'SNES', 'Hissatsu Pachinko Collection 3 (Japan)', '1995', 'Gambling', 'Sunsoft', '1', 'Pachinko compilation', 'The third installment of the professional Pachinko series.', 'Prove your skill at the parlor and collect a fortune in balls.', 'Test your luck in Hissatsu Pachinko Collection 3 on SNES.', 'Includes some of the most popular real-life machines from the mid-90s, perfectly recreated with 16-bit graphics and authentic audio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hissatsu-pachinko-collection-4-japan', 'SNES', 'Hissatsu Pachinko Collection 4 (Japan)', '1996', 'Gambling', 'Sunsoft', '1', 'Pachinko compilation', 'The final entry in the Hissatsu professional Pachinko series.', 'Reach the top of the Pachinko world in this ultimate collection.', 'Play the definitive Hissatsu Pachinko Collection 4 on SNES.', 'Features the largest roster of machines in the series, offering the most complete and polished 16-bit Pachinko experience on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-777-fighter---pachi-slot-ryuuguu-densetsu-japan', 'SNES', 'Hisshou 777 Fighter - Pachi-Slot Ryuuguu Densetsu (Japan)', '1993', 'Gambling', 'Ask Kodansha', '1', 'Pachislot simulation', 'Pachi-slot simulation based on the "Ryuuguu Densetsu" theme.', 'Master the reels and win the slot tournament.', 'Play Hisshou 777 Fighter on the Super Famicom.', 'A specialized 16-bit slot simulation. Features a specific theme and detailed payout charts, allowing players to practice their reel-stopping timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-777-fighter-ii---pachi-slot-maruhi-jouhou-japan', 'SNES', 'Hisshou 777 Fighter II - Pachi-Slot Maruhi Jouhou (Japan)', '1994', 'Gambling', 'Ask Kodansha', '1', 'Pachislot simulation', 'Pachi-slot simulation featuring secret tips and professional data.', 'Master the slots using real-world data and "hidden" info.', 'Play Hisshou 777 Fighter II on the Super Famicom.', 'A detailed 16-bit simulation of pachi-slot machines. Features a "secret information" mode to help players understand reel patterns and maximize their virtual winnings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-777-fighter-iii---kokuryuu-ou-no-fukkatsu-japan', 'SNES', 'Hisshou 777 Fighter III - Kokuryuu Ou no Fukkatsu (Japan)', '1995', 'Gambling', 'Ask Kodansha', '1', 'Pachislot simulation', 'Pachi-slot simulation with an added fantasy RPG story mode.', 'Defeat the Black Dragon King by winning at the slot machines.', 'Experience the unique Hisshou 777 Fighter III on SNES.', 'A creative 16-bit hybrid that blends traditional slot simulation with a fantasy narrative. Use your winnings to progress through the story and defeat ancient evils.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hisshou-pachi-slot-fun-japan', 'SNES', 'Hisshou Pachi-Slot Fun (Japan)', '1996', 'Gambling', 'ASCII', '1', 'Pachislot simulation', 'Professional pachi-slot simulation with multiple machine types.', 'Master the timing of the reels to hit the big jackpot.', 'Test your luck in Hisshou Pachi-Slot Fun on the SNES.', 'A straightforward and realistic 16-bit slot experience. Features authentic machine physics and a variety of themes to keep fans of the genre engaged.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hit-the-ice-usa', 'SNES', 'Hit the Ice (USA)', '1992', 'Sports', 'Taito', '4', 'Arcade ice hockey', 'Arcade-style hockey game with a focus on combat and "super" moves.', 'Win the championship by out-skating and out-punching your rivals.', 'Hit the ice in the high-energy Hit the Ice for the SNES.', 'Forget the rules; this is 16-bit "video hockey." Features 3-on-3 action with massive characters, over-the-top fights, and spectacular special goals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokuto-no-ken-5---tenma-ryuuseiden-ai-zetsu-shou-japan', 'SNES', 'Hokuto no Ken 5 - Tenma Ryuuseiden Ai Zetsu Shou (Japan)', '1992', 'Action', 'Toei Animation', '2', 'Beat ''em up', 'Traditional turn-based RPG based on the famous manga and anime.', 'Lead Kenshiro to defeat the forces of chaos and save his friends.', 'Experience the epic Hokuto no Ken 5 on the Super Famicom.', 'A deep 16-bit RPG that covers major story arcs from the series. Master the legendary "Hokuto Shinken" techniques in strategic turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokuto-no-ken-6---gekitou-denshou-ken-haou-e-no-michi-japan', 'SNES', 'Hokuto no Ken 6 - Gekitou Denshou Ken Haou e no Michi (Japan)', '1993', 'Action', 'Toei Animation', '2', 'Beat ''em up', 'One-on-one fighting game featuring the Hokuto no Ken cast.', 'Master the secret martial arts to become the ultimate successor.', 'Battle for glory in Hokuto no Ken 6 for the Super Famicom.', 'A 16-bit fighter that emphasizes the "Hokuto" pressure point system. Features large sprites and cinematic special moves inspired by the classic anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokuto-no-ken-7---seiken-retsuden-denshousha-e-no-michi-japan', 'SNES', 'Hokuto no Ken 7 - Seiken Retsuden Denshousha e no Michi (Japan)', '1994', 'Action', 'Toei Animation', '2', 'Beat ''em up', 'One-on-one fighting game with improved graphics and roster.', 'Claim the title of successor in the definitive 16-bit tournament.', 'Master the fist in Hokuto no Ken 7 on the Super Famicom.', 'The final entry in the series for the system. Features refined combat mechanics, faster gameplay, and a more comprehensive story mode for fans of Kenshiro.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holy-striker-japan', 'SNES', 'Holy Striker (Japan)', '1994', 'Sports', 'Namco', '2', 'Arcade soccer', 'Action-puzzle hybrid that plays like a combat-focused Arkanoid.', 'Defeat the demonic forces by bouncing your ball-warrior.', 'Play the unique Holy Striker on the Super Famicom.', 'The Japanese version of Fire Striker. Control your hero to deflect a projectile into enemies and bosses in this creative 16-bit arcade-style adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holy-umbrella---dondera-no-mubou!!-english-translated', 'SNES', 'Holy Umbrella - Dondera no Mubou!! (English Translated)', '1994', 'Action', 'Irem', '2', 'Arcade platformer', 'Side-scrolling action-platformer with RPG elements and English text.', 'Save the world of Dondera with your magical umbrella.', 'Play Holy Umbrella in English on the Super Nintendo.', 'The fan translation makes this quirky 16-bit gem accessible. Switch between characters to solve puzzles and master the unique umbrella-based movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('holy-umbrella---dondera-no-mubou!!-japan', 'SNES', 'Holy Umbrella - Dondera no Mubou!! (Japan)', '1994', 'Action', 'Irem', '2', 'Arcade platformer', 'Side-scrolling action-platformer with RPG elements.', 'Save the world of Dondera with your magical umbrella.', 'Discover the charming Holy Umbrella on the Super Famicom.', 'A visually stunning late-gen title. Features fluid 16-bit platforming, town exploration, and a humorous story that follows a modern boy transported to a fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-europe', 'SNES', 'Home Alone (Europe)', '1991', 'Action', 'Imagineering', '1', 'Action platformer', 'Action-adventure based on the hit Christmas movie.', 'Protect the McCallister house from Harry and Marv''s traps.', 'Defend your home in Home Alone for the Super Nintendo.', 'Play as Kevin and search for valuables to hide while setting up traps for the Wet Bandits. A 16-bit challenge that requires speed and planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-japan', 'SNES', 'Home Alone (Japan)', '1991', 'Action', 'Imagineering', '1', 'Action platformer', 'Action-adventure based on the hit Christmas movie.', 'Experience the Japanese version of the McCallister adventure.', 'Play Home Alone on the Super Famicom for an 16-bit thrill.', 'Known as "Home Alone" in Japan. Features the same trap-setting gameplay and colorful graphics inspired by the legendary 1990 film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-usa', 'SNES', 'Home Alone (USA)', '1991', 'Action', 'Imagineering', '1', 'Action platformer', 'Action-adventure based on the hit Christmas movie.', 'Protect the McCallister house from Harry and Marv''s traps.', 'Defend your home in Home Alone for the Super Nintendo.', 'Navigate the massive 16-bit house, collect items, and outsmart the burglars in this nostalgic licensed platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-2---lost-in-new-york-europe', 'SNES', 'Home Alone 2 - Lost in New York (Europe)', '1992', 'Action', 'Imagineering', '1', 'Action platformer', 'Side-scrolling action-platformer set in the Big Apple.', 'Escape the burglars and find your family in the streets of NYC.', 'Survive the city in Home Alone 2: Lost in New York on SNES.', 'Explore 16-bit versions of the Plaza Hotel and Central Park. Use toys as weapons to fend off enemies and survive the trials of the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-alone-2---lost-in-new-york-usa', 'SNES', 'Home Alone 2 - Lost in New York (USA)', '1992', 'Action', 'Imagineering', '1', 'Action platformer', 'Side-scrolling action-platformer set in the Big Apple.', 'Escape the burglars and find your family in the streets of NYC.', 'Survive the city in Home Alone 2: Lost in New York on SNES.', 'A more traditional platformer than the first game. Master Kevin''s movement to navigate through hazardous 16-bit urban environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('home-improvement-usa', 'SNES', 'Home Improvement (USA)', '1994', 'Action', 'Imagineering', '1', 'Action platformer', 'Action-platformer based on the sitcom starring Tim Allen.', 'Find your missing TV set while battling through dangerous sets.', 'Experience the bizarre Home Improvement on the SNES.', 'A unique 16-bit platformer. Use your power tools as weapons and grappling hooks across various film sets. Features "Real Digital Sound" and high-energy action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hong-kong-97-hong-kong', 'SNES', 'Hong Kong 97 (Hong Kong)', '1995', 'Action', 'Koei', '1', 'Experimental action', 'Infamous unlicensed shooter with a surreal and controversial theme.', 'Kill the "ugly reds" and save the future of Hong Kong.', 'Play the notorious Hong Kong 97 on the Super Famicom.', 'A cult classic for all the wrong reasons. Features a looping soundtrack, digitized graphics, and a level of 16-bit weirdness that has made it a legendary "bad" game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honkaku-mahjong---tetsuman-japan', 'SNES', 'Honkaku Mahjong - Tetsuman (Japan)', '1992', 'Board', 'Game Studio', '4', 'Mahjong simulation', 'Traditional Mahjong simulation with a focus on professional rules.', 'Defeat the Mahjong masters in this realistic simulation.', 'Play the authentic Honkaku Mahjong: Tetsuman on SNES.', 'A polished 16-bit Mahjong title featuring realistic AI and clean menu designs. Perfect for fans looking for a serious challenge in the classic tile game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honkaku-mahjong---tetsuman-ii-japan', 'SNES', 'Honkaku Mahjong - Tetsuman II (Japan)', '1993', 'Board', 'Game Studio', '4', 'Mahjong simulation', 'Traditional Mahjong sequel with improved AI and more modes.', 'Master the tiles and win the tournament in this refined sequel.', 'Experience Honkaku Mahjong: Tetsuman II on the SNES.', 'Features more character variety and updated 16-bit graphics. Offers a comprehensive simulation of professional Mahjong strategy and play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honkaku-shougi---fuuunji-ryuuou-japan', 'SNES', 'Honkaku Shougi - Fuuunji Ryuuou (Japan)', '1992', 'Board', 'Naxat Soft', '2', 'Shogi simulation', 'Authentic Shogi (Japanese Chess) simulation with a royal theme.', 'Defeat the Dragon King and prove your strategic mastery.', 'Master Shogi in Honkaku Shougi: Fuuunji Ryuuou on SNES.', 'A high-quality 16-bit Shogi experience. Features multiple difficulty levels and a helpful hint system for players learning the traditional strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honkakuha-igo-gosei-japan', 'SNES', 'Honkakuha Igo Gosei (Japan)', '1993', 'Board', 'Naxat Soft', '2', 'Go simulation', 'Deep strategy game based on the ancient board game of Go.', 'Win the Gosei title by mastering the territory-based game.', 'Play the strategic Honkakuha Igo Gosei on the SNES.', 'A professional-grade 16-bit simulation of Go. Features a powerful AI for the era, allowing for deep and challenging strategic matches on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honke-hanafuda-japan', 'SNES', 'Honke Hanafuda (Japan)', '1992', 'Board', 'Naxat Soft', '2', 'Hanafuda simulation', 'Traditional Hanafuda card game simulation with a focus on realism.', 'Master the classic cards and win the high-stakes tournament.', 'Play the authentic Honke Hanafuda on the Super Famicom.', 'Features beautiful 16-bit card art and a relaxing atmosphere. Enjoy various Hanafuda games like Koi-Koi with smooth controls and realistic rules.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honke-sankyo-fever---jikki-simulation-japan', 'SNES', 'Honke Sankyo Fever - Jikki Simulation (Japan)', '1993', 'Gambling', 'Sankyo', '1', 'Pachinko simulation', 'Authentic Pachinko simulation featuring real Sankyo Fever machines.', 'Master the silver balls to win the jackpot on licensed tables.', 'Play Honke Sankyo Fever Simulation on the Super Famicom.', 'A realistic 16-bit recreation of real-life Sankyo machines. Features accurate physics and multiple camera angles to simulate the parlor experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honke-sankyo-fever-2---jikki-simulation-japan', 'SNES', 'Honke Sankyo Fever 2 - Jikki Simulation (Japan)', '1994', 'Gambling', 'Sankyo', '1', 'Pachinko simulation', 'Authentic Pachinko sequel with updated Sankyo machines.', 'Win big on the latest digital Sankyo Fever tables.', 'Experience Honke Sankyo Fever 2 on the Super Famicom.', 'Features more detailed 16-bit machine graphics and a wider variety of gameplay modes, including a professional tournament simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honke-sankyo-fever-3---jikki-simulation-japan', 'SNES', 'Honke Sankyo Fever 3 - Jikki Simulation (Japan)', '1995', 'Gambling', 'Sankyo', '1', 'Pachinko simulation', 'The final entry in the Sankyo Fever Pachinko trilogy.', 'Reach the top of the Pachinko world on the best Sankyo tables.', 'Play the definitive Honke Sankyo Fever 3 on SNES.', 'The most advanced 16-bit Pachinko simulation in the series. Features high-fidelity audio and the most accurate ball trajectories on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('honoo-no-doukyuuji---dodge-danpei-japan', 'SNES', 'Honoo no Doukyuuji - Dodge Danpei (Japan)', '1992', 'Sports', 'Character Soft', '2', 'Sports action', 'Action sports game based on the dodgeball anime.', 'Lead Danpei and his team to the national dodgeball title.', 'Hit the court in Honoo no Doukyuuji: Dodge Danpei on SNES.', 'A high-energy 16-bit sports title. Features flashy "super shots" and fast-paced arcade gameplay inspired by the legendary manga and anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hook-europe', 'SNES', 'Hook (Europe)', '1992', 'Action', 'Ocean', '2', 'Action platformer', 'Action-platformer based on the film starring Robin Williams.', 'Rescue your children from Captain Hook in Neverland.', 'Fly to Neverland in Hook for the Super Nintendo.', 'Experience a beautifully animated 16-bit adventure. Master Peter Pan''s flight and sword skills across vibrant levels, from the pirate ship to the depths of the forest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hook-japan', 'SNES', 'Hook (Japan)', '1992', 'Action', 'Ocean', '2', 'Action platformer', 'Action-platformer based on the film starring Robin Williams.', 'Rescue your children from Captain Hook in Neverland.', 'Play the Japanese version of Hook on the Super Famicom.', 'The original Sony Imagesoft classic with high-fidelity 16-bit sprites and an enchanting soundtrack that captures the magic of the cinematic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hook-usa', 'SNES', 'Hook (USA)', '1992', 'Action', 'Ocean', '2', 'Action platformer', 'Action-platformer based on the film starring Robin Williams.', 'Rescue your children from Captain Hook in Neverland.', 'Fly to Neverland in Hook for the Super Nintendo.', 'Master the fluid platforming and use Rufio''s help to navigate 16-bit challenges. A polished movie tie-in that stands as a solid action title on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby---super-deluxe-japan', 'SNES', 'Hoshi no Kirby - Super Deluxe (Japan)', '1996', 'Action', 'HAL Laboratory', '4', 'Action platformer', 'Multi-game collection featuring various Kirby adventures.', 'Complete eight different 16-bit games in one massive package.', 'Experience Kirby Super Star (Super Deluxe) on SNES.', 'A peak 16-bit platformer. Features the debut of the "Helper" system for 2-player co-op, incredible copy abilities, and some of the best graphics on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby---super-deluxe-japan-rev-b', 'SNES', 'Hoshi no Kirby - Super Deluxe (Japan) (Rev B)', '1996', 'Action', 'HAL Laboratory', '4', 'Action platformer', 'Multi-game collection featuring various Kirby adventures.', 'Complete eight different 16-bit games in this refined revision.', 'Play the polished Hoshi no Kirby: Super Deluxe (Rev B).', 'The updated Japanese revision featuring minor balance tweaks and bug fixes, providing the most stable 16-bit Kirby experience for collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby-3-japan', 'SNES', 'Hoshi no Kirby 3 (Japan)', '1998', 'Action', 'HAL Laboratory', '2', 'Action platformer', 'Traditional side-scrolling platformer with a hand-drawn art style.', 'Defeat Dark Matter and restore peace to Dream Land.', 'Discover the artistic Kirby''s Dream Land 3 on SNES.', 'A late-gen masterpiece. Features a unique "colored pencil" 16-bit aesthetic and the ability to team up with diverse animal friends to solve puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('houkago-in-beppin-jogakuin-japan', 'SNES', 'Houkago in Beppin Jogakuin (Japan)', '1995', 'Adventure', 'Human Entertainment', '1', 'Visual novel', 'Visual novel/simulation set in a Japanese girls'' academy.', 'Navigate school life and build relationships through dialogue.', 'Experience Houkago in Beppin Jogakuin on Super Famicom.', 'A charming 16-bit simulation of Japanese school culture. Use a branching dialogue system to influence the story and interact with a variety of student characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hourai-gakuen-no-bouken!---tenkousei-scramble-japan', 'SNES', 'Hourai Gakuen no Bouken! - Tenkousei Scramble (Japan)', '1995', 'Adventure', 'Human Entertainment', '1', 'Adventure RPG', 'Large-scale turn-based JRPG set in a massive high school.', 'Lead a student club through bizarre supernatural adventures.', 'Explore the epic Hourai Gakuen no Bouken on SNES.', 'Features a massive cast and a humorous "school life" atmosphere. Command your 16-bit party in tactical battles within a sprawling and mysterious campus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('human-baseball-japan', 'SNES', 'Human Baseball (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Baseball simulation', 'Arcade-style baseball simulation with a focus on speed.', 'Win the national league through precise pitching and hitting.', 'Step up to the plate in Human Baseball for the SNES.', 'Features fast-paced 16-bit gameplay and smooth animations. A solid sports title from Human Entertainment that prioritizes fun and accessible controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('human-grand-prix-japan', 'SNES', 'Human Grand Prix (Japan)', '1992', 'Racing', 'Human Entertainment', '2', 'Formula racing', 'Realistic Formula 1 racing simulation using Mode 7.', 'Win the F1 World Championship across authentic circuits.', 'Race for glory in Human Grand Prix for the Super Famicom.', 'Known as F1 Pole Position in the West. Features realistic 16-bit physics, real driver names, and a technical approach to high-speed racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('human-grand-prix-ii-japan', 'SNES', 'Human Grand Prix II (Japan)', '1993', 'Racing', 'Human Entertainment', '2', 'Formula racing', 'Realistic Formula 1 racing simulation using Mode 7.', 'Master the updated tracks and car physics in this sequel.', 'Experience Human Grand Prix II on the Super Famicom.', 'Features improved 16-bit scaling effects and a deeper customization menu. A must-play for fans of technical and authentic 16-bit motorsports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('human-grand-prix-iii---f1-triple-battle-japan', 'SNES', 'Human Grand Prix III - F1 Triple Battle (Japan)', '1994', 'Racing', 'Human Entertainment', '2', 'Formula racing', 'Advanced Formula 1 simulation with a focus on tactical racing.', 'Win the Triple Battle tournament across international tracks.', 'Race the best in Human Grand Prix III for the SNES.', 'Introduces more detailed 16-bit car setups and weather effects. Manage your pit stops and tire wear to dominate the professional F1 circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('human-grand-prix-iv---f1-dream-battle-japan', 'SNES', 'Human Grand Prix IV - F1 Dream Battle (Japan)', '1995', 'Racing', 'Human Entertainment', '2', 'Formula racing', 'The ultimate 16-bit Formula 1 simulation from Human.', 'Achieve the F1 Dream by winning the world title.', 'Play the definitive Human Grand Prix IV on Super Famicom.', 'The series peak on SNES. Features high-quality 16-bit graphics, a massive roster of real drivers, and the most refined driving model in the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('humans-the-europe', 'SNES', 'Humans, The (Europe)', '1992', 'Puzzle', 'Cocktail Vision', '2', 'Puzzle strategy', 'Puzzle-strategy game where you guide a tribe through hazards.', 'Lead your primitive tribe to the goal in each level.', 'Save the tribe in The Humans for the Super Nintendo.', 'A creative 16-bit puzzler similar to Lemmings. Switch between different "Human" roles like hunters or tool-makers to navigate dangerous environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('humans-the-germany', 'SNES', 'Humans, The (Germany)', '1992', 'Puzzle', 'Cocktail Vision', '2', 'Puzzle strategy', 'Puzzle-strategy game where you guide a tribe through hazards.', 'Lead your primitive tribe to the goal in the German version.', 'Spielen Sie The Humans auf Deutsch für das SNES.', 'The complete 16-bit puzzle-adventure with localized German text. Use teamwork and strategy to ensure the survival of your primitive clan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hummer-super-mario-world', 'SNES', 'Hummer Super Mario World', '1991', 'Hack', 'Unknown', '1', 'ROM hack', 'Unlicensed fan-made modification of Super Mario World.', 'Explore a "Hummer" themed world with custom 16-bit assets.', 'Check out the Hummer Super Mario World mod on SNES.', 'A curious and rare 16-bit romhack. Features modified sprites and level designs, showcasing the early era of unlicensed SNES community creations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hungry-dinosaurs-europe', 'SNES', 'Hungry Dinosaurs (Europe)', '1994', 'Action', 'Flair Software', '2', 'Run and gun', 'Unique top-down action game featuring competitive eating mechanics.', 'Outmaneuver rivals and consume more food than anyone else.', 'Experience the quirky Hungry Dinosaurs on the Super Nintendo.', 'A localized version of "Harapeko Bakka." A 16-bit competitive title where speed and strategy are key to winning the eating tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hunt-for-red-october-the-europe', 'SNES', 'Hunt for Red October, The (Europe)', '1993', 'Action', 'Beam Software', '1', 'Action shooter', 'Side-scrolling submarine simulation and action game.', 'Navigate through enemy waters and complete covert missions.', 'Submerge in The Hunt for Red October on the Super Nintendo.', 'Based on the Tom Clancy novel and film. Features intense 16-bit naval combat where you must balance stealth and firepower to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hunt-for-red-october-the-japan', 'SNES', 'Hunt for Red October, The (Japan)', '1993', 'Action', 'Beam Software', '1', 'Action shooter', 'Side-scrolling submarine simulation and action game.', 'Navigate through enemy waters and complete covert missions.', 'Play the Japanese version of Red October on the SNES.', 'Experience the 16-bit tactical submarine action. Features detailed sub designs and a variety of mission objectives in a high-stakes Cold War setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hunt-for-red-october-the-usa', 'SNES', 'Hunt for Red October, The (USA)', '1993', 'Action', 'Beam Software', '1', 'Action shooter', 'Side-scrolling submarine simulation and action game.', 'Navigate through enemy waters and complete covert missions.', 'Submerge in The Hunt for Red October on the Super Nintendo.', 'Master the sonar and torpedo systems. A unique 16-bit title that blends slow-paced navigation with explosive combat sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hurricanes-europe', 'SNES', 'Hurricanes (Europe)', '1994', 'Action', 'U.S. Gold', '2', 'Arcade sports', 'Action-platformer based on the animated soccer series.', 'Recover the team''s missing equipment and defeat rivals.', 'Join the match in Hurricanes for the Super Nintendo.', 'A colorful 16-bit adventure where you use soccer balls as weapons. Navigate through diverse levels and solve puzzles to save the Hurricanes'' legacy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hurricanes-europe-beta', 'SNES', 'Hurricanes (Europe) (Beta)', '1994', 'Action', 'U.S. Gold', '2', 'Arcade sports', 'Action-platformer based on the animated soccer series.', 'Explore the early level designs of the soccer adventure.', 'Check out the Hurricanes Beta version on the SNES.', 'A pre-release development build. Discover initial 16-bit mechanical tweaks and sprite animations before the final European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hurricanes-usa', 'SNES', 'Hurricanes (USA)', '1994', 'Action', 'U.S. Gold', '2', 'Arcade sports', 'Action-platformer based on the animated soccer series.', 'Recover the team''s missing equipment and defeat rivals.', 'Join the match in Hurricanes for the Super Nintendo.', 'Master the ball-juggling mechanics to defeat 16-bit enemies. A fun and accessible licensed platformer for fans of the cartoon series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-iria-japan', 'SNES', 'Hyper Iria (Japan)', '1995', 'Action', 'Banpresto', '1', 'Anime action', 'Side-scrolling action-adventure based on the sci-fi anime.', 'Complete bounty hunting missions across dangerous planets.', 'Experience the stylish Hyper Iria on the Super Famicom.', 'A technical 16-bit gem. Use a variety of gadgets and weapons as Iria to fight through futuristic levels with fluid movement and great pixel art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-metroid-10', 'SNES', 'Hyper Metroid 1.0', '2017', 'Action', 'Unknown', '1', 'ROM hack', 'Total conversion fan-mod of Super Metroid with new physics.', 'Explore a reimagined Zebes with much faster mechanics.', 'Experience the legendary Hyper Metroid mod on the SNES.', 'A massive overhaul of the 16-bit classic. Features a completely new map, faster movement, and revamped power-ups for the ultimate Metroid challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-street-kart', 'SNES', 'Hyper Street Kart', '2019', 'Racing', 'Unknown', '2', 'ROM hack racing', 'Fast-paced racing mod featuring Street Fighter characters.', 'Win the Grand Prix using iconic fighters and their special abilities.', 'Race as Ryu and Chun-Li in Hyper Street Kart for SNES.', 'A creative "Super Mario Kart" hack. It replaces the cast with Street Fighter legends, featuring custom 16-bit sprites and modified tracks for a unique crossover racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-v-ball-europe', 'SNES', 'Hyper V-Ball (Europe)', '1994', 'Sports', 'Video System', '2', 'Volleyball arcade', 'High-speed volleyball simulation with both realistic and futuristic modes.', 'Master the court and win the world championship.', 'Hit the ball in Hyper V-Ball for the Super Nintendo.', 'Features the "Hyper" mode with robotic teams and special moves. A technically solid 16-bit sports title with smooth scaling and intense competitive gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyper-v-ball-usa', 'SNES', 'Hyper V-Ball (USA)', '1994', 'Sports', 'Video System', '2', 'Volleyball arcade', 'High-speed volleyball simulation with both realistic and futuristic modes.', 'Master the court and win the world championship.', 'Hit the ball in Hyper V-Ball for the Super Nintendo.', 'Choose between human or mechanical teams. This 16-bit volleyball sim offers deep strategy, precise timing, and a variety of power-serves to dominate the net.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyperzone-europe', 'SNES', 'HyperZone (Europe)', '1991', 'Shooter', 'Hal Laboratory', '1', 'Fixed shooter', 'Futuristic rail shooter using advanced Mode 7 scaling effects.', 'Navigate through hazardous zones and eliminate enemy bio-machines.', 'Blast through the future in HyperZone for the Super Nintendo.', 'Experience a pseudo-3D perspective as you glide through high-speed corridors. A visually impressive 16-bit shooter that rewards reflexes and energy management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyperzone-japan', 'SNES', 'HyperZone (Japan)', '1991', 'Shooter', 'Hal Laboratory', '1', 'Fixed shooter', 'Futuristic rail shooter using advanced Mode 7 scaling effects.', 'Navigate through hazardous zones and eliminate enemy bio-machines.', 'Play the original HyperZone on the Super Famicom.', 'Master the 16-bit "into-the-screen" combat. Upgrade your ship as you progress through vibrant, rotating environments in this early SNES classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyperzone-usa', 'SNES', 'HyperZone (USA)', '1991', 'Shooter', 'Hal Laboratory', '1', 'Fixed shooter', 'Futuristic rail shooter using advanced Mode 7 scaling effects.', 'Navigate through hazardous zones and eliminate enemy bio-machines.', 'Blast through the future in HyperZone for the Super Nintendo.', 'Avoid obstacles and maintain high speed while taking down bosses. A hypnotic 16-bit experience that showcases the console''s rotation and scaling capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('i-hate-you', 'SNES', 'I HATE YOU', '2018', 'Action', 'Unknown', '1', 'Homebrew experimental', 'Experimental or fan-made modification (Creepypasta/Horror).', 'Survive a distorted and surreal version of a classic world.', 'Experience the eerie I HATE YOU mod on the SNES.', 'A horror-themed hack (often of Super Mario World) designed to unsettle the player with glitch-style 16-bit visuals, distorted audio, and hidden messages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('idea-no-hi-japan', 'SNES', 'Idea no Hi (Japan)', '1995', 'Puzzle', 'Altron', '1', 'Puzzle experimental', 'Traditional turn-based RPG with a focus on dark, psychological themes.', 'Prevent a global cataclysm by exploring ancient ruins.', 'Discover the deep Idea no Hi on the Super Famicom.', 'Features character designs by manga artist Kenji Yasuhiko. A 16-bit JRPG known for its bizarre world-building, high encounter rate, and unique party members.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ignition-factor-the-usa', 'SNES', 'Ignition Factor, The (USA)', '1994', 'Action', 'Jaleco', '2', 'Run and gun', 'Action-simulation focusing on firefighting and rescue operations.', 'Extinguish fires and rescue civilians within a strict time limit.', 'Be a hero in The Ignition Factor for the Super Nintendo.', 'Known as "Fire Fighting" in Japan. Use specialized equipment and tactical planning to navigate burning skyscrapers in this high-stakes 16-bit rescue sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('igo-club-japan', 'SNES', 'Igo Club (Japan)', '1993', 'Board', 'Game Studio', '2', 'Board game', 'Strategic simulation of the ancient board game Go.', 'Defeat computer masters and improve your ranking.', 'Play the traditional Igo Club on the Super Famicom.', 'Features multiple skill levels and tutorials. A refined 16-bit digital version of Go, perfect for players looking for a quiet, intellectual challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ihatov-monogatari-japan', 'SNES', 'Ihatov Monogatari (Japan)', '1993', 'Adventure', 'Hect', '1', 'Story adventure', 'Atmospheric adventure game based on the works of Kenji Miyazawa.', 'Explore a dreamlike world and help its inhabitants.', 'Experience the poetic Ihatov Monogatari on Super Famicom.', 'A peaceful 16-bit journey. Instead of combat, focus on exploration and dialogue in a world inspired by classic Japanese literature and fairy tales.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ikari-no-yousai-japan', 'SNES', 'Ikari no Yousai (Japan)', '1994', 'Action', 'Jaleco', '2', 'Run and gun', 'Top-down action shooter featuring a mercenary in a hostile base.', 'Infiltrate the enemy fortress and stop the nuclear threat.', 'Blast through Ikari no Yousai (Operation Logic Bomb) on SNES.', 'Control an elite soldier with a variety of high-tech weapons. Features impressive 16-bit visual effects and challenging tactical shooting gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illusion-of-gaia-usa', 'SNES', 'Illusion of Gaia (USA)', '1994', 'Action', 'Quintet', '1', 'Action RPG', 'Epic Action-RPG featuring world-saving transformations.', 'Restore the seven wonders of the world and stop the comet.', 'Embark on the journey in Illusion of Gaia for the SNES.', 'A masterpiece of 16-bit storytelling. Transform Will into the dark knight Freedan or the solar being Shadow to solve puzzles and defeat cosmic evils.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illusion-of-gaia-usa-beta', 'SNES', 'Illusion of Gaia (USA) (Beta)', '1993', 'Action', 'Quintet', '1', 'Action RPG', 'Epic Action-RPG featuring world-saving transformations.', 'Test the early combat and narrative beats of this masterpiece.', 'Check out the Illusion of Gaia Beta on the SNES.', 'A pre-release version of the game. Discover early 16-bit translation drafts and mechanical adjustments for this legendary Quintet adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illusion-of-time-europe', 'SNES', 'Illusion of Time (Europe)', '1994', 'Action', 'Quintet', '1', 'Action RPG', 'Epic Action-RPG featuring world-saving transformations.', 'Restore the world''s landmarks and stop the ancient threat.', 'Experience Illusion of Time on the Super Nintendo.', 'The European title for Illusion of Gaia. Features deep 16-bit themes of life, death, and reincarnation across a world inspired by real-life mysteries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illusion-of-time-france', 'SNES', 'Illusion of Time (France)', '1994', 'Action', 'Quintet', '1', 'Action RPG', 'Epic Action-RPG featuring world-saving transformations.', 'Play the epic adventure in French.', 'Jouez à Illusion of Time en français sur le SNES.', 'The complete 16-bit Action-RPG with fully localized French text. Follow Will''s emotional journey through the ruins of Angkor Wat and the Great Wall.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illusion-of-time-germany', 'SNES', 'Illusion of Time (Germany)', '1994', 'Action', 'Quintet', '1', 'Action RPG', 'Epic Action-RPG featuring world-saving transformations.', 'Play the epic adventure in German.', 'Spielen Sie Illusion of Time auf Deutsch für das SNES.', 'The complete 16-bit Action-RPG with fully localized German text. Experience the tragic and heroic narrative that defined a generation of RPG fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illusion-of-time-germany-rev-a', 'SNES', 'Illusion of Time (Germany) (Rev A)', '1994', 'Action', 'Quintet', '1', 'Action RPG', 'Epic Action-RPG featuring world-saving transformations.', 'Play the epic adventure in the refined German revision.', 'Spielen Sie Illusion of Time (Rev A) auf Deutsch.', 'The updated 16-bit German revision, fixing minor text errors and improving script clarity for a smoother role-playing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illusion-of-time-spain', 'SNES', 'Illusion of Time (Spain)', '1994', 'Action', 'Quintet', '1', 'Action RPG', 'Epic Action-RPG featuring world-saving transformations.', 'Play the epic adventure in Spanish.', 'Juega a Illusion of Time en español para la Super Nintendo.', 'One of the first 16-bit RPGs to be fully translated into Spanish. Join Will and his friends in this unforgettable quest across the globe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('illvanian-no-shiro-japan', 'SNES', 'Illvanian no Shiro (Japan)', '1995', 'Adventure', 'Human Entertainment', '1', 'Adventure horror', 'Side-scrolling platformer with puzzle elements and a gothic theme.', 'Navigate through the monster-filled castle to reach the exit.', 'Explore the eerie Illvanian no Shiro on Super Famicom.', 'A quirky 16-bit title with a distinct visual style. Solve environmental puzzles and use timed jumps to survive this charming but challenging Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('imperium-usa', 'SNES', 'Imperium (USA)', '1991', 'Strategy', 'Electronic Arts', '1', 'Turn-based strategy', 'Vertical-scrolling shoot ''em up featuring a high-tech mech.', 'Destroy the alien invaders across multiple planetary stages.', 'Pilot the mech in Imperium for the Super Nintendo.', 'Known for its speed-control mechanic. Manage your ship''s velocity while dodging 16-bit bullet patterns and taking down massive mechanical bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inazuma-serve-da!-super-beach-volley-japan', 'SNES', 'Inazuma Serve da! Super Beach Volley (Japan)', '1994', 'Sports', 'Video System', '4', 'Beach volleyball', 'Fast-paced beach volleyball featuring "super-deformed" characters.', 'Win the summer tournament and become the beach king.', 'Hit the sand in Inazuma Serve da! on the Super Famicom.', 'A colorful and lighthearted 16-bit sports game. Features flashy special serves and 2-player co-op action in a fun, tropical setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incantation-europe', 'SNES', 'Incantation (Europe)', '1996', 'Action', 'Titus Software', '2', 'Action platformer', 'Action-platformer with a magical fantasy theme.', 'Restore the balance of the world by finding the ancient scrolls.', 'Experience the magical Incantation for the Super Nintendo.', 'Control a young wizard and use various spells to defeat monsters. A late-gen 16-bit platformer with vibrant graphics and a focus on exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incantation-usa', 'SNES', 'Incantation (USA)', '1996', 'Action', 'Titus Software', '2', 'Action platformer', 'Action-platformer with a magical fantasy theme.', 'Restore the balance of the world by finding the ancient scrolls.', 'Experience the magical Incantation for the Super Nintendo.', 'Navigate through enchanted forests and caves. Master your 16-bit magical projectiles to overcome bosses in this charming fantasy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-europe', 'SNES', 'Incredible Crash Dummies, The (Europe)', '1994', 'Action', 'Gray Matter', '1', 'Platform action', 'Action-platformer based on the famous safety test toys.', 'Rescue your partner and prove you are the ultimate crash dummy.', 'Join The Incredible Crash Dummies on the Super Nintendo.', 'Control Slick and Spin in a variety of 16-bit levels. Features unique mechanics where your character can lose limbs and still keep going in this quirky, humorous platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-japan', 'SNES', 'Incredible Crash Dummies, The (Japan)', '1994', 'Action', 'Gray Matter', '1', 'Platform action', 'Action-platformer based on the famous safety test toys.', 'Rescue your partner and prove you are the ultimate crash dummy.', 'Play the Japanese version of Crash Dummies on SNES.', 'The Super Famicom release of the toy-inspired adventure. Features vibrant 16-bit graphics and challenging stages that reward precision and a bit of "crashing" fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-usa', 'SNES', 'Incredible Crash Dummies, The (USA)', '1994', 'Action', 'Gray Matter', '1', 'Platform action', 'Action-platformer based on the famous safety test toys.', 'Rescue your partner and prove you are the ultimate crash dummy.', 'Join The Incredible Crash Dummies on the Super Nintendo.', 'Navigate through factories and test sites. A classic 16-bit licensed title that blends traditional platforming with the unique "breakable" nature of its protagonists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-crash-dummies-the-usa-beta', 'SNES', 'Incredible Crash Dummies, The (USA) (Beta)', '1994', 'Action', 'Gray Matter', '1', 'Platform action beta', 'Action-platformer based on the famous safety test toys.', 'Explore the early level designs and physics of this toy game.', 'Check out The Incredible Crash Dummies Beta on SNES.', 'A pre-release development build. Discover how the 16-bit limb-loss mechanics and stage layouts were tuned before the final North American launch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-hulk-the-europe', 'SNES', 'Incredible Hulk, The (Europe)', '1994', 'Action', 'Probe Software', '1', 'Superhero action', 'Action-platformer starring the iconic Marvel powerhouse.', 'Defeat the Leader and his army of villains across the globe.', 'Smash through enemies in The Incredible Hulk for the SNES.', 'Control the Hulk as he transforms between his powerful green form and the strategic Grey Hulk. A challenging 16-bit brawler with massive boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('incredible-hulk-the-usa', 'SNES', 'Incredible Hulk, The (USA)', '1994', 'Action', 'Probe Software', '1', 'Superhero action', 'Action-platformer starring the iconic Marvel powerhouse.', 'Defeat the Leader and his army of villains across the globe.', 'Smash through enemies in The Incredible Hulk for the SNES.', 'Utilize the Hulk''s immense strength to destroy environments and enemies. Experience 16-bit comic book action with detailed sprites and punishing difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-greatest-adventures-europe', 'SNES', 'Indiana Jones'' Greatest Adventures (Europe)', '1994', 'Action', 'LucasArts', '1', 'Action adventure', 'Cinematic action-platformer based on the original movie trilogy.', 'Relive the adventures from Raiders, Temple of Doom, and Last Crusade.', 'Experience Indiana Jones'' Greatest Adventures on the SNES.', 'A high-octane 16-bit epic using the "Super Star Wars" engine. Features whip-cracking action, Mode 7 vehicle levels, and digitized sounds from the films.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-greatest-adventures-japan', 'SNES', 'Indiana Jones'' Greatest Adventures (Japan)', '1994', 'Action', 'LucasArts', '1', 'Action adventure', 'Cinematic action-platformer based on the original movie trilogy.', 'Relive Indy''s most famous movie moments on your console.', 'Play Indiana Jones'' Greatest Adventures on Super Famicom.', 'The original Japanese release of the cinematic platformer. Features the same intense 16-bit challenge and faithful recreation of the Spielberg masterpieces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('indiana-jones-greatest-adventures-usa', 'SNES', 'Indiana Jones'' Greatest Adventures (USA)', '1994', 'Action', 'LucasArts', '1', 'Action adventure', 'Cinematic action-platformer based on the original movie trilogy.', 'Relive the adventures from Raiders, Temple of Doom, and Last Crusade.', 'Experience Indiana Jones'' Greatest Adventures on the SNES.', 'Master the whip and the revolver. One of the most polished 16-bit cinematic experiences, featuring incredible level variety and iconic John Williams music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inindo---way-of-the-ninja-usa', 'SNES', 'Inindo - Way of the Ninja (USA)', '1991', 'RPG', 'Koei', '1', 'Historical RPG', 'Strategy-RPG hybrid set in feudal Japan.', 'Unify Japan by mastering the arts of ninjutsu and diplomacy.', 'Master the shadows in Inindo: Way of the Ninja on SNES.', 'A deep Koei title. Travel across 16-bit Japan, recruit allies, and engage in turn-based battles while managing the political landscape of the warring states.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inspector-gadget-usa', 'SNES', 'Inspector Gadget (USA)', '1993', 'Action', 'Hudson Soft', '1', 'Action platformer', 'Action-platformer based on the classic bumbling detective cartoon.', 'Stop Dr. Claw and M.A.D. across international locations.', 'Go-Go-Gadget action in Inspector Gadget for the SNES.', 'Use Gadget''s various limbs and tools to solve 16-bit puzzles and fight enemies. Features the quirky humor and iconic characters from the animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-europe', 'SNES', 'International Superstar Soccer (Europe)', '1994', 'Sports', 'Konami', '2', 'Soccer simulation', 'Revolutionary soccer simulation that redefined the genre.', 'Win the international cup with realistic tactics and gameplay.', 'Play the legendary International Superstar Soccer on SNES.', 'The game that birthed the "PES" legacy. Features large 16-bit player sprites, diverse weather conditions, and the most fluid soccer mechanics of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-usa', 'SNES', 'International Superstar Soccer (USA)', '1994', 'Sports', 'Konami', '2', 'Soccer simulation', 'Revolutionary soccer simulation that redefined the genre.', 'Win the international cup with realistic tactics and gameplay.', 'Experience International Superstar Soccer for the SNES.', 'Master the "through-ball" and strategic substitutions. A landmark 16-bit sports title that brought professional-grade depth to console football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-deluxe-europe', 'SNES', 'International Superstar Soccer Deluxe (Europe)', '1995', 'Sports', 'Konami', '4', 'Soccer simulation deluxe', 'The definitive 16-bit soccer experience with updated features.', 'Claim the world title in the ultimate version of the game.', 'Play International Superstar Soccer Deluxe on the SNES.', 'Features improved graphics, new animations, and a legendary commentator. Often cited as the best 16-bit soccer game ever made for its speed and realism.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-deluxe-usa', 'SNES', 'International Superstar Soccer Deluxe (USA)', '1995', 'Sports', 'Konami', '4', 'Soccer simulation deluxe', 'The definitive 16-bit soccer experience with updated features.', 'Claim the world title in the ultimate version of the game.', 'Play International Superstar Soccer Deluxe on the SNES.', 'Master the strategy and skill-moves. This 16-bit masterpiece offers a deep "Scenario" mode and a highly competitive 2-player experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-tennis-tour-europe', 'SNES', 'International Tennis Tour (Europe)', '1993', 'Sports', 'Loriciel', '2', 'Tennis simulation', 'Realistic tennis simulation with a focus on professional tour play.', 'Climb the world rankings and win the Grand Slam tournaments.', 'Hit the court in International Tennis Tour for the SNES.', 'Features a variety of court surfaces and a deep career mode. A technical 16-bit sports title that requires precise timing and tactical shot placement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-tennis-tour-japan', 'SNES', 'International Tennis Tour (Japan)', '1993', 'Sports', 'Loriciel', '2', 'Tennis simulation', 'Realistic tennis simulation with a focus on professional tour play.', 'Climb the world rankings and win the Grand Slam tournaments.', 'Play the Japanese version of International Tennis Tour on SNES.', 'Known as "Telenet Tennis" in Japan. Offers a refined 16-bit tennis experience with detailed player animations and a challenging AI for sports enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-tennis-tour-usa', 'SNES', 'International Tennis Tour (USA)', '1993', 'Sports', 'Loriciel', '2', 'Tennis simulation', 'Realistic tennis simulation with a focus on professional tour play.', 'Climb the world rankings and win the Grand Slam tournaments.', 'Hit the court in International Tennis Tour for the SNES.', 'Master the serve-and-volley game. A solid 16-bit simulation that captures the intensity of professional tennis with smooth controls and realistic physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('invictus-v11', 'SNES', 'Invictus (V1.1)', '2019', 'Action', 'Unknown', '1', 'Homebrew arena fighter', 'Total conversion fan-mod of Super Metroid with a focus on combat.', 'Explore a dangerous new world with revamped mechanics and maps.', 'Experience the intense Invictus mod on the Super Nintendo.', 'A challenging 16-bit romhack featuring custom rooms, high-difficulty boss fights, and a completely new progression path for Metroid veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ippatsu-gyakuten-japan', 'SNES', 'Ippatsu Gyakuten (Japan)', '1994', 'Puzzle', 'Nichibutsu', '1', 'Puzzle gambling', 'Traditional gambling simulation featuring various Japanese games.', 'Win big at the parlor and build your virtual fortune.', 'Test your luck in Ippatsu Gyakuten for the Super Famicom.', 'A 16-bit simulation of Japanese betting culture. Features realistic mechanics for horse racing and other popular gambling pastimes with a polished interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('irem-major-title-the-europe', 'SNES', 'Irem Major Title, The (Europe)', '1994', 'Sports', 'Irem', '2', 'Golf simulation', 'Realistic golf simulation from the arcade masters at Irem.', 'Master the 18 holes and win the prestigious tournament.', 'Tee off in The Irem Major Title for the Super Nintendo.', 'Features a unique swing mechanic and detailed digitized course graphics. A technical 16-bit golf game that emphasizes environmental factors like wind and slope.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('irem-major-title-the-japan', 'SNES', 'Irem Major Title, The (Japan)', '1994', 'Sports', 'Irem', '2', 'Golf simulation', 'Realistic golf simulation from the arcade masters at Irem.', 'Master the 18 holes and win the prestigious tournament.', 'Experience the Japanese version of Irem Major Title on SNES.', 'The Super Famicom version of the arcade hit. Offers a high level of 16-bit realism and a challenging career mode for golf simulation purists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('irem-skins-game-the-usa', 'SNES', 'Irem Skins Game, The (USA)', '1994', 'Sports', 'Irem', '2', 'Golf simulation', 'Realistic golf simulation featuring famous professional courses.', 'Win the tournament and master the art of the perfect swing.', 'Play The Irem Skins Game on the Super Nintendo.', 'A polished 16-bit golf title that rewards patience and planning. Navigate through hazards and read the greens in this authentic sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-commando---koutetsu-no-senshi-japan', 'SNES', 'Iron Commando - Koutetsu no Senshi (Japan)', '1995', 'Action', 'Arcade Zone', '2', 'Run and gun', 'Gritty side-scrolling beat ''em up with high-intensity action.', 'Stop the terrorist organization and rescue the kidnapped scientist.', 'Fight through the streets in Iron Commando on the SNES.', 'A cult classic brawler. Features impressive 16-bit sprites, weapon use, and vehicle segments. Known for its high difficulty and cinematic action sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-commando-europe-proto', 'SNES', 'Iron Commando (Europe) (Proto)', '1995', 'Action', 'Arcade Zone', '2', 'Run and gun prototype', 'Gritty side-scrolling beat ''em up (Unreleased European prototype).', 'Experience the localized version of this rare brawler.', 'Check out the Iron Commando Prototype on the SNES.', 'A rare look at the cancelled PAL release. Features 16-bit street-fighting action with translated menus and the complete, intense gameplay of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('isozuri---ritou-hen-japan', 'SNES', 'Isozuri - Ritou Hen (Japan)', '1996', 'Action', 'Visit', '1', 'Fishing adventure', 'Specialized fishing simulation focusing on island and shore fishing.', 'Catch the rarest tropical fish across beautiful island locales.', 'Cast your line in Isozuri: Ritou Hen for the Super Famicom.', 'A realistic 16-bit fishing sim that focuses on specific techniques for rocky shores. Features detailed rod physics and a variety of lures for dedicated anglers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itadaki-street-2---neon-sign-wa-bara-iro-ni-japan', 'SNES', 'Itadaki Street 2 - Neon Sign wa Bara Iro ni (Japan)', '1994', 'Board', 'Chunsoft', '4', 'Board game', 'Competitive property-trading board game (precursor to Fortune Street).', 'Buy up the city and bankrupt your rivals to win.', 'Master the market in Itadaki Street 2 on the SNES.', 'An Enix masterpiece. A deep 16-bit board game with a focus on stock manipulation and property management. A favorite for multiplayer strategy fans in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itchy-&-scratchy-game-the-europe', 'SNES', 'Itchy & Scratchy Game, The (Europe)', '1995', 'Action', 'Beam Software', '1', 'Cartoon platformer', 'Cartoon action-platformer based on the show within The Simpsons.', 'Defeat your rival in a series of violent and humorous levels.', 'Join the chaos in The Itchy & Scratchy Game for the SNES.', 'Control Itchy as he uses a variety of lethal tools to torment Scratchy. A 16-bit title that perfectly captures the surreal and violent humor of the cartoon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itchy-&-scratchy-game-the-usa', 'SNES', 'Itchy & Scratchy Game, The (USA)', '1995', 'Action', 'Beam Software', '1', 'Cartoon platformer', 'Cartoon action-platformer based on the show within The Simpsons.', 'Defeat your rival in a series of violent and humorous levels.', 'Join the chaos in The Itchy & Scratchy Game for the SNES.', 'Navigate through various film sets and use over-the-top weapons. A fast-paced 16-bit platformer that rewards exploration and quick reflexes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itoi-shigesato-no-bass-tsuri-no-1-japan', 'SNES', 'Itoi Shigesato no Bass Tsuri No. 1 (Japan)', '1997', 'Sports', 'Ape Inc.', '1', 'Fishing simulation', 'Realistic fishing simulation with deep environmental mechanics.', 'Catch the biggest bass and win the tournament on Lake Akagi.', 'Experience Shigesato Itoi''s Bass Tsuri No. 1 on SNES.', 'Designed by the creator of EarthBound. Features a high-fidelity 16-bit simulation of bass fishing with changing weather, lure physics, and a relaxing, philosophical atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itou-hatasu-rokudan-no-shougi-doujou-japan', 'SNES', 'Itou Hatasu Rokudan no Shougi Doujou (Japan)', '1995', 'Board', 'Game Studio', '2', 'Shogi board game', 'Professional Shogi (Japanese Chess) simulation with AI coaching.', 'Defeat the master Itou Hatasu in a series of strategic matches.', 'Master Shogi in Itou Hatasu Rokudan no Shougi Doujou.', 'A technical 16-bit Shogi experience. Features professional-grade AI and a training mode to improve your openings and tactical endgame play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itou-hatasu-rokudan-no-shougi-doujou-japan-rev-a', 'SNES', 'Itou Hatasu Rokudan no Shougi Doujou (Japan) (Rev A)', '1995', 'Board', 'Game Studio', '2', 'Shogi board game', 'Professional Shogi simulation with AI coaching.', 'Defeat the master Itou Hatasu in this refined revision.', 'Play the polished Itou Hatasu Shougi (Rev A) on SNES.', 'An updated Japanese revision featuring minor AI logic improvements and bug fixes for a more stable and challenging 16-bit strategic experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('izzys-quest-for-the-olympic-rings-europe', 'SNES', 'Izzy''s Quest for the Olympic Rings (Europe)', '1996', 'Sports', 'Alexandria', '1', 'Sports platformer', 'Action-platformer featuring the 1996 Olympic mascot.', 'Recover the stolen Olympic rings across various themed worlds.', 'Join the adventure in Izzy''s Quest for the Olympic Rings.', 'Control the shapeshifting mascot Izzy. Use unique 16-bit power-ups to transform and navigate through vibrant levels filled with hazards and Olympic-themed secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('izzys-quest-for-the-olympic-rings-usa', 'SNES', 'Izzy''s Quest for the Olympic Rings (USA)', '1996', 'Sports', 'Alexandria', '1', 'Sports platformer', 'Action-platformer featuring the 1996 Olympic mascot.', 'Recover the stolen Olympic rings across various themed worlds.', 'Join the adventure in Izzy''s Quest for the Olympic Rings.', 'Master Izzy''s gliding and dashing abilities. A colorful 16-bit licensed platformer that captures the spirit of the Atlanta 1996 Olympic Games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('izzys-quest-for-the-olympic-rings-usa-beta', 'SNES', 'Izzy''s Quest for the Olympic Rings (USA) (Beta)', '1996', 'Sports', 'Alexandria', '1', 'Sports platformer beta', 'Action-platformer featuring the 1996 Olympic mascot.', 'Explore early level designs of the Olympic adventure.', 'Check out the Izzy''s Quest (Beta) on the SNES.', 'A pre-release development build. Witness the early 16-bit character animations and world-building for the official Olympic mascot''s console debut.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-96-dream-stadium-japan', 'SNES', 'J.League ''96 Dream Stadium (Japan)', '1996', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'Advanced soccer simulation featuring the 1996 J.League rosters.', 'Lead your favorite Japanese club to the league championship.', 'Kick off in J.League ''96 Dream Stadium for the SNES.', 'Features high-resolution 16-bit player sprites and realistic stadium atmospheres. Manage your team and execute complex tactical plays on the field.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-excite-stage-94-japan', 'SNES', 'J.League Excite Stage ''94 (Japan)', '1994', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'Fast-paced soccer game with a famous indoor "futsal" mode.', 'Win the J.League cup through high-speed arcade action.', 'Experience J.League Excite Stage ''94 on the SNES.', 'A cult classic known for its fluid 16-bit gameplay. Includes the popular indoor mode with walls that keep the ball in play for non-stop action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-excite-stage-94-japan-rev-a', 'SNES', 'J.League Excite Stage ''94 (Japan) (Rev A)', '1994', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'Fast-paced soccer game with a famous indoor "futsal" mode.', 'Win the J.League cup in this refined 16-bit revision.', 'Play the polished Excite Stage ''94 (Rev A) on SNES.', 'An updated version fixing minor sprite glitches and balancing the AI difficulty for a more consistent 16-bit soccer experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-excite-stage-95-japan', 'SNES', 'J.League Excite Stage ''95 (Japan)', '1995', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'Soccer simulation sequel with improved graphics and rosters.', 'Master the new 1995 season and claim the championship.', 'Hit the pitch in J.League Excite Stage ''95 on SNES.', 'Features smoother 16-bit animations and expanded team tactics. The indoor mode remains a highlight, offering fast and addictive arcade-style soccer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-excite-stage-96-japan', 'SNES', 'J.League Excite Stage ''96 (Japan)', '1996', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'The peak of the Excite Stage series with comprehensive features.', 'Conquer the Japanese football world in the 1996 season.', 'Play the definitive J.League Excite Stage ''96 on SNES.', 'Often considered the best 16-bit soccer game in Japan. Features a deep management mode, refined 16-bit physics, and the legendary indoor arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-excite-stage-96-japan-rev-a', 'SNES', 'J.League Excite Stage ''96 (Japan) (Rev A)', '1996', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'The peak of the Excite Stage series with comprehensive features.', 'Conquer the 1996 season in this refined Rev A version.', 'Play the polished J.League Excite Stage ''96 on SNES.', 'The final 16-bit revision of the series, featuring the most stable gameplay and updated player data for the ultimate Japanese soccer simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-soccer-prime-goal-japan', 'SNES', 'J.League Soccer Prime Goal (Japan)', '1993', 'Sports', 'Namco', '2', 'Soccer simulation', 'Arcade-style soccer simulation with a side-view perspective.', 'Lead your J.League team to victory with flashy special plays.', 'Experience J.League Soccer Prime Goal on the SNES.', 'Known for its cinematic 16-bit "Prime Goal" animations. A fast-paced football title that emphasizes fun, scoring, and high-energy matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-soccer-prime-goal-japan-rev-a', 'SNES', 'J.League Soccer Prime Goal (Japan) (Rev A)', '1993', 'Sports', 'Namco', '2', 'Soccer simulation', 'Arcade-style soccer simulation with a side-view perspective.', 'Win the league in this refined revision of the sports sim.', 'Play the polished J.League Soccer Prime Goal (Rev A).', 'An updated Japanese release that improves the 16-bit collision detection and ball physics for a more competitive arcade soccer match.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-soccer-prime-goal-2-japan', 'SNES', 'J.League Soccer Prime Goal 2 (Japan)', '1994', 'Sports', 'Namco', '2', 'Soccer simulation', 'Action-heavy soccer sequel with more teams and moves.', 'Dominate the field in the second entry of the Prime Goal series.', 'Kick off in J.League Soccer Prime Goal 2 on SNES.', 'Features updated 16-bit rosters and more detailed player sprites. Master the new special shots and defensive maneuvers to win the league.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-soccer-prime-goal-3-japan', 'SNES', 'J.League Soccer Prime Goal 3 (Japan)', '1995', 'Sports', 'Namco', '2', 'Soccer simulation', 'The third installment featuring improved strategy and visuals.', 'Master the pitch and win the championship in Prime Goal 3.', 'Experience the intense J.League Soccer Prime Goal 3.', 'Offers a more simulation-heavy approach while retaining 16-bit arcade fun. Features better stadium graphics and expanded tactical management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-super-soccer-95---jikkyou-stadium-japan', 'SNES', 'J.League Super Soccer ''95 - Jikkyou Stadium (Japan)', '1995', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'Soccer simulation featuring live commentary and 1995 data.', 'Win the league while enjoying authentic broadcast-style play.', 'Play J.League Super Soccer ''95 on the Super Famicom.', 'The first 16-bit soccer game to feature "Jikkyou" (live commentary). Offers a high level of immersion with real-time audio reactions to the on-field action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-super-soccer-japan', 'SNES', 'J.League Super Soccer (Japan)', '1994', 'Sports', 'KCE Tokyo', '2', 'Soccer simulation', 'The foundational entry in the Super Soccer series for J.League.', 'Start your journey to the top of the Japanese soccer world.', 'Experience J.League Super Soccer on the Super Famicom.', 'Features a unique 16-bit perspective and accessible controls. A solid starting point for fans of Japanese football simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jrr-tolkiens-the-lord-of-the-rings---volume-one-europe', 'SNES', 'J.R.R. Tolkien''s The Lord of the Rings - Volume One (Europe)', '1994', 'RPG', 'Interplay', '1', 'Action RPG', 'Action-RPG based on the legendary fantasy book series.', 'Lead the Fellowship to destroy the One Ring.', 'Explore Middle-earth in Lord of the Rings for the SNES.', 'A unique 16-bit RPG that supports up to 8 players via the Multitap. Explore iconic locations from the Shire to Bree in a top-down adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jrr-tolkiens-the-lord-of-the-rings---volume-one-germany', 'SNES', 'J.R.R. Tolkien''s The Lord of the Rings - Volume One (Germany)', '1994', 'RPG', 'Interplay', '1', 'Action RPG', 'Action-RPG based on the legendary fantasy book series.', 'Experience the epic fantasy journey in German.', 'Spielen Sie Der Herr der Ringe auf Deutsch für das SNES.', 'The complete 16-bit quest with localized German text. Command the Fellowship and solve environmental puzzles to survive the threat of Sauron.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jrr-tolkiens-the-lord-of-the-rings---volume-one-usa', 'SNES', 'J.R.R. Tolkien''s The Lord of the Rings - Volume One (USA)', '1994', 'RPG', 'Interplay', '1', 'Action RPG', 'Action-RPG based on the legendary fantasy book series.', 'Lead the Fellowship to destroy the One Ring.', 'Explore Middle-earth in Lord of the Rings for the SNES.', 'Master the use of iconic 16-bit items and character-specific skills. A faithful adaptation that focuses on the exploration and lore of Tolkien''s world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jack-nicklaus-golf-europe', 'SNES', 'Jack Nicklaus Golf (Europe)', '1992', 'Sports', 'Accolade', '1', 'Golf simulation', 'Realistic golf simulation endorsed by the legendary Jack Nicklaus.', 'Win the international tournament on professional-grade courses.', 'Tee off in Jack Nicklaus Golf for the Super Nintendo.', 'Features a sophisticated 16-bit course architect mode. Navigate through challenging greens and bunkers with realistic wind and club physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jack-nicklaus-golf-france', 'SNES', 'Jack Nicklaus Golf (France)', '1992', 'Sports', 'Accolade', '1', 'Golf simulation', 'Realistic golf simulation endorsed by the legendary Jack Nicklaus.', 'Play the professional golf simulation in French.', 'Jouez à Jack Nicklaus Golf en français sur le SNES.', 'The complete 16-bit golf experience with localized French menus. Compete against the best AI and master the art of the perfect swing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jack-nicklaus-golf-usa', 'SNES', 'Jack Nicklaus Golf (USA)', '1992', 'Sports', 'Accolade', '1', 'Golf simulation', 'Realistic golf simulation endorsed by the legendary Jack Nicklaus.', 'Win the international tournament on professional-grade courses.', 'Tee off in Jack Nicklaus Golf for the Super Nintendo.', 'Master the 16-bit greens and read the terrain. A solid and technical golf title that rewards patience and precise shot planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jaki-crush-japan', 'SNES', 'Jaki Crush (Japan)', '1994', 'Puzzle', 'NCS', '2', 'Action puzzle', 'Fast-paced pinball game with a dark, occult theme.', 'Hit the bumpers and score big in this demonic pinball world.', 'Experience the gothic Jaki Crush on the Super Famicom.', 'The third entry in the "Crush" series (after Alien and Devil). Features incredible 16-bit pixel art, multiple screen tiers, and bizarre supernatural bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-bond-jr-europe', 'SNES', 'James Bond Jr. (Europe)', '1991', 'Action', 'Eurocom', '1', 'Action platformer', 'Action-platformer featuring gadgets and side-scrolling combat.', 'Stop the evil SCUM organization across global missions.', 'Join the adventure in James Bond Jr. for the SNES.', 'Control the nephew of the famous spy in this 16-bit action title. Use a variety of gadgets and firearms to navigate through trap-filled levels and defeat iconic villains from the animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-bond-jr-usa', 'SNES', 'James Bond Jr. (USA)', '1991', 'Action', 'Eurocom', '1', 'Action platformer', 'Action-platformer featuring gadgets and side-scrolling combat.', 'Stop the evil SCUM organization across global missions.', 'Join the adventure in James Bond Jr. for the SNES.', 'Master the use of high-tech spy gear in a variety of 16-bit environments. A challenging licensed title that combines traditional platforming with fast-paced shooting mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-pond-3---operation-starfish-europe', 'SNES', 'James Pond 3 - Operation Starfish (Europe)', '1993', 'Action', 'Millennium', '1', 'Platform adventure', 'Huge side-scrolling platformer with a focus on exploration.', 'Stop Dr. Maybe''s moon mining operation and save the planet.', 'Experience the massive James Pond 3 on the SNES.', 'A creative 16-bit platformer featuring gravity-defying mechanics. Explore vast levels inspired by the moon, use diverse power-ups, and enjoy the quirky humor of the secret agent mudskipper.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('james-ponds-crazy-sports-europe', 'SNES', 'James Pond''s Crazy Sports (Europe)', '1993', 'Sports', 'Millennium', '2', 'Sports minigames', 'Wacky sports compilation featuring aquatic-themed events.', 'Win the gold medal in a series of bizarre Olympic-style games.', 'Compete in James Pond''s Crazy Sports for the SNES.', 'A lighthearted 16-bit sports title. Participate in events like "Running on Water" and "Feeding Frenzy" in a colorful, cartoonish world perfect for multiplayer fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jammes-japan', 'SNES', 'Jammes (Japan)', '1994', 'Puzzle', 'Nichibutsu', '2', 'Puzzle arcade', 'Unique puzzle game involving falling blocks and matching colors.', 'Clear the screen by strategic placement of colored pieces.', 'Solve the puzzles in Jammes for the Super Famicom.', 'A rare 16-bit Japanese puzzler with a distinct aesthetic. Challenge your spatial reasoning in single-player or competitive modes with smooth 16-bit animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jammit-usa', 'SNES', 'Jammit (USA)', '1993', 'Sports', 'Acclaim', '4', 'Basketball arcade', 'Urban street basketball simulation with a focus on 1-on-1 matches.', 'Outscore your opponent in high-stakes street ball games.', 'Hit the court in Jammit for the Super Nintendo.', 'Features digitized 16-bit graphics and a "trash talk" system. Master the timing of your dunks and shots in this gritty and realistic simulation of 90s street basketball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('janyuuki---gokuu-randa-japan', 'SNES', 'Janyuuki - Gokuu Randa (Japan)', '1994', 'Action', 'Masaya', '1', 'Action adventure', 'One-on-one fighting game based on the "Journey to the West" legend.', 'Defeat mythological rivals and complete the journey as Goku.', 'Experience the action in Janyuuki: Gokuu Randa on SNES.', 'A visually impressive 16-bit fighter. Unleash Sun Wukong''s magical staff attacks and special moves in high-speed combat against legendary Chinese folklore characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jb-the-super-bass-japan', 'SNES', 'JB The Super Bass (Japan)', '1994', 'Action', 'Jaleco', '1', 'Action platformer', 'Realistic fishing simulation focused on professional bass tournaments.', 'Land the biggest prize-winning bass to top the leaderboards.', 'Cast your line in JB The Super Bass for Super Famicom.', 'Features detailed 16-bit water physics and a variety of lures. Navigate your boat across different lakes and master the art of the perfect catch in this technical simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jelly-boy-europe', 'SNES', 'Jelly Boy (Europe)', '1995', 'Action', 'Probe Software', '1', 'Colorful platformer', 'Metamorphosing action-platformer featuring a protagonist made of jelly.', 'Rescue the kingdom by using your ability to change shape.', 'Play the unique Jelly Boy for the Super Nintendo.', 'Control a blob-like hero who can transform into a hammer, a balloon, and more. A colorful 16-bit adventure that rewards creative problem-solving and precise platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jelly-boy-2-japan-proto', 'SNES', 'Jelly Boy 2 (Japan) (Proto)', '1996', 'Action', 'Probe Software', '1', 'Platformer prototype', 'Enhanced platformer sequel with more transformations and levels.', 'Restore peace to the jelly world in this unreleased sequel.', 'Check out the Jelly Boy 2 Proto on the Super Famicom.', 'A rare, fully-functional prototype. Features improved 16-bit graphics and more complex transformation mechanics than the original, offering a peak at what could have been.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jelly-boy-2-japan-proto-en-by-kingmike-v10final', 'SNES', 'Jelly Boy 2 (Japan) (Proto) [En by KingMike v1.0Final]', '1996', 'Action', 'Probe Software', '1', 'Platformer prototype', 'Enhanced platformer sequel with a full English fan translation.', 'Experience the unreleased jelly adventure with English text.', 'Play Jelly Boy 2 in English on the Super Nintendo.', 'The KingMike translation makes this polished 16-bit prototype fully accessible. Explore brand new worlds and master unique transformations in a vibrant fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!---deluxe-edition-usa', 'SNES', 'Jeopardy! - Deluxe Edition (USA)', '1992', 'Trivia', 'GameTek', '3', 'Quiz show', 'Digital adaptation of the classic TV game show with expanded categories.', 'Win the most money by phrasing your answers in the form of a question.', 'Test your knowledge in Jeopardy! Deluxe Edition on SNES.', 'Features over 3,500 16-bit questions and realistic TV-style presentation. Play against friends or AI in this comprehensive trivia challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!---sports-edition-usa', 'SNES', 'Jeopardy! - Sports Edition (USA)', '1994', 'Trivia', 'GameTek', '3', 'Sports quiz', 'Specialized edition of the game show focusing on athletic trivia.', 'Prove your sports knowledge and claim the championship.', 'Play Jeopardy! Sports Edition for the Super Nintendo.', 'Features thousands of 16-bit questions spanning various sports history and trivia. A must-play for sports fans looking for a mental challenge on their console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-usa', 'SNES', 'Jeopardy! (USA)', '1992', 'Trivia', 'GameTek', '3', 'Quiz show', 'Digital version of the iconic quiz show featuring various difficulty levels.', 'Be the first to buzz in and answer correctly to win.', 'Join the competition in Jeopardy! for the SNES.', 'A faithful 16-bit recreation of the television experience. Manage your virtual earnings and face the "Daily Double" in this classic brain-teasing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jerry-boy-japan', 'SNES', 'Jerry Boy (Japan)', '1994', 'Action', 'NCS', '1', 'Platform adventure', 'Charming action-platformer starring a blue slime (Smart Ball).', 'Rescue the princess and reclaim your human form.', 'Discover the beautiful Jerry Boy for the Super Famicom.', 'Developed by Game Freak. Use Jerry''s 16-bit "sticky" physics to climb walls and ceiling. A polished, colorful, and highly imaginative platformer with great character design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jerry-boy-japan-en-by-chris-covell-v10', 'SNES', 'Jerry Boy (Japan) [En by Chris Covell v1.0]', '1994', 'Action', 'NCS', '1', 'Platform adventure', 'Charming action-platformer starring a blue slime with English text.', 'Follow the story of the cursed prince with a full translation.', 'Play Jerry Boy in English on the Super Nintendo.', 'The Chris Covell translation restores the story cut from the Western "Smart Ball" release. Experience the full 16-bit narrative of the slime prince in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jetsons-the---invasion-of-the-planet-pirates-usa', 'SNES', 'Jetsons, The - Invasion of the Planet Pirates (USA)', '1994', 'Action', 'Taito', '1', 'Cartoon platformer', 'Side-scrolling action-platformer based on the futuristic cartoon.', 'Protect the planet from space pirates using your magnetic boots.', 'Join The Jetsons: Invasion of the Planet Pirates on SNES.', 'Control George Jetson as he uses a high-tech "sucker" tool to grapple and fight. A creative 16-bit adventure with vibrant sci-fi backgrounds and smooth animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jigsaw-party-japan', 'SNES', 'Jigsaw Party (Japan)', '1993', 'Puzzle', 'Nichibutsu', '4', 'Party puzzle', 'Digital jigsaw puzzle game with various themes and difficulty levels.', 'Complete beautiful 16-bit images by fitting the pieces together.', 'Relax with Jigsaw Party for the Super Famicom.', 'Features a variety of colorful illustrations and a relaxing soundtrack. Includes competitive 16-bit modes where you race against a friend to finish the puzzle first.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-oshaberi-parodius-japan', 'SNES', 'Jikkyou Oshaberi Parodius (Japan)', '1995', 'Shooter', 'Konami', '2', 'Comedy shooter', 'Bizarre side-scrolling shoot ''em up with a talking commentator.', 'Blast through waves of surreal enemies in this parody adventure.', 'Experience Jikkyou Oshaberi Parodius on the Super Famicom.', 'A masterpiece of 16-bit comedy. Features a live commentator, incredible parody stages, and a huge cast of Konami characters in a chaotic and colorful shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-power-pro-wrestling-96---max-voltage-japan', 'SNES', 'Jikkyou Power Pro Wrestling ''96 - Max Voltage (Japan)', '1996', 'Sports', 'Konami', '2', 'Pro wrestling simulation', 'Professional wrestling simulation with a focus on TV-style presentation.', 'Win the world title and become a 16-bit wrestling legend.', 'Enter the ring in Jikkyou Power Pro Wrestling ''96 on SNES.', 'Introduces live commentary to the 16-bit ring. Features a deep "Edit Mode" and technical grappling mechanics that reward strategy and timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-power-pro-wrestling-96---max-voltage-japan-en-by-phil-v10-incomplete', 'SNES', 'Jikkyou Power Pro Wrestling ''96 - Max Voltage (Japan) [En by Phil v1.0] (Incomplete)', '1996', 'Sports', 'Konami', '2', 'Pro wrestling simulation', 'Professional wrestling simulation with a partial English translation.', 'Experience the 16-bit wrestling action with English menus.', 'Play Max Voltage in English on the Super Nintendo.', 'The Phil translation helps navigate the complex management and edit menus of this technical 16-bit wrestling sim, making the gameplay accessible to Western fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu---basic-ban-98-japan', 'SNES', 'Jikkyou Powerful Pro Yakyuu - Basic Ban ''98 (Japan)', '1998', 'Sports', 'Konami', '2', 'Baseball simulation', 'The final 16-bit entry in the series with updated 1998 rosters.', 'Lead your favorite team to the pennant in this definitive version.', 'Play the updated Powerful Pro Yakyuu ''98 on SNES.', 'Features refined "chibi" player graphics and the most advanced 16-bit AI in the series. Offers the most complete statistical baseball experience on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-94-japan', 'SNES', 'Jikkyou Powerful Pro Yakyuu ''94 (Japan)', '1994', 'Sports', 'Konami', '2', 'Baseball simulation', 'The game that started the "Powerful Pro" baseball phenomenon.', 'Master the technical pitching and batting system to win.', 'Experience Jikkyou Powerful Pro Yakyuu ''94 on SNES.', 'Introduces the iconic "head-only" 16-bit player style. Features a deep simulation of professional baseball with a focus on individual player stats and precise controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-96---kaimaku-ban-japan', 'SNES', 'Jikkyou Powerful Pro Yakyuu ''96 - Kaimaku Ban (Japan)', '1996', 'Sports', 'Konami', '2', 'Baseball simulation', 'Updated baseball simulation featuring the 1996 season''s opening data.', 'Climb the ranks and win the championship with your favorite team.', 'Play Powerful Pro Yakyuu ''96 on the Super Famicom.', 'Features improved 16-bit animations and the first appearances of the deep "Success Mode" career mechanics. A landmark title for Japanese sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-96---kaimaku-ban-japan-rev-a', 'SNES', 'Jikkyou Powerful Pro Yakyuu ''96 - Kaimaku Ban (Japan) (Rev A)', '1996', 'Sports', 'Konami', '2', 'Baseball simulation', 'Updated baseball simulation featuring the 1996 season''s opening data.', 'Win the pennant in this refined revision of the 1996 season.', 'Play the polished Powerful Pro Yakyuu ''96 (Rev A) on SNES.', 'The updated 16-bit Japanese revision featuring minor balance tweaks and bug fixes for a more stable and accurate professional baseball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2-japan', 'SNES', 'Jikkyou Powerful Pro Yakyuu 2 (Japan)', '1994', 'Sports', 'Konami', '2', 'Baseball simulation', 'Technical baseball simulation with "chibi" characters and live commentary.', 'Win the Japan Series with updated teams and stats.', 'Experience Jikkyou Powerful Pro Yakyuu 2 on SNES.', 'The sequel that refined the 16-bit baseball formula. Master the cursor-based batting and pitching system in this highly detailed and polished Japanese sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2-japan-rev-a', 'SNES', 'Jikkyou Powerful Pro Yakyuu 2 (Japan) (Rev A)', '1994', 'Sports', 'Konami', '2', 'Baseball simulation', 'Technical baseball simulation with "chibi" characters and live commentary.', 'Win the league in this refined revision.', 'Play the polished Powerful Pro Yakyuu 2 (Rev A) on SNES.', 'An updated Japanese revision that balances the pitching AI and fixes minor 16-bit sprite flickering for a smoother championship run.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-3---97-haru-japan', 'SNES', 'Jikkyou Powerful Pro Yakyuu 3 - ''97 Haru (Japan)', '1997', 'Sports', 'Konami', '2', 'Baseball simulation', 'The "Spring ''97" update of the popular baseball series.', 'Lead your team to victory with updated 1997 rosters.', 'Hit a home run in Powerful Pro Yakyuu 3 - ''97 Haru.', 'Features updated data for the 1997 season. Experience the most advanced 16-bit "Success Mode" and the trademark expressive character animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-3---97-haru-japan-rev-a', 'SNES', 'Jikkyou Powerful Pro Yakyuu 3 - ''97 Haru (Japan) (Rev A)', '1997', 'Sports', 'Konami', '2', 'Baseball simulation', 'The "Spring ''97" update of the popular baseball series.', 'Lead your team to victory in this refined revision.', 'Play Powerful Pro Yakyuu 3 - ''97 Haru (Rev A) on SNES.', 'The final 16-bit update for the Spring ''97 edition, featuring minor bug fixes and the most accurate player stats of the season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-3-japan', 'SNES', 'Jikkyou Powerful Pro Yakyuu 3 (Japan)', '1997', 'Sports', 'Konami', '2', 'Baseball simulation', 'The foundational third entry of the Powerful Pro series.', 'Master the diamond and win the pennant.', 'Play Jikkyou Powerful Pro Yakyuu 3 on the Super Famicom.', 'Introduces more complex player traits and specialized pitches. A landmark 16-bit title that deepened the simulation aspects of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer---perfect-eleven-japan', 'SNES', 'Jikkyou World Soccer - Perfect Eleven (Japan)', '1995', 'Sports', 'Konami', '2', 'Soccer simulation', 'Revolutionary soccer simulation with real-time commentary.', 'Win the world cup through precise 16-bit soccer gameplay.', 'Play Jikkyou World Soccer: Perfect Eleven on SNES.', 'The Japanese original of International Superstar Soccer. Features massive player sprites and a high-energy broadcast-style presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer---perfect-eleven-japan-rev-a', 'SNES', 'Jikkyou World Soccer - Perfect Eleven (Japan) (Rev A)', '1995', 'Sports', 'Konami', '2', 'Soccer simulation', 'Revolutionary soccer simulation with real-time commentary.', 'Win the world cup in this refined 16-bit revision.', 'Play the polished Perfect Eleven (Rev A) on SNES.', 'An updated version featuring minor AI adjustments and smoother 16-bit collision detection for a more competitive football experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer-2---fighting-eleven-japan', 'SNES', 'Jikkyou World Soccer 2 - Fighting Eleven (Japan)', '1996', 'Sports', 'Konami', '2', 'Soccer simulation', 'The peak of 16-bit soccer with expanded rosters and modes.', 'Dominate the world stage in this legendary sequel.', 'Experience Jikkyou World Soccer 2: Fighting Eleven.', 'Known as ISS Deluxe in the West. Features the most fluid 16-bit soccer mechanics ever made, including new player skills and weather effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer-2---fighting-eleven-japan-beta', 'SNES', 'Jikkyou World Soccer 2 - Fighting Eleven (Japan) (Beta)', '1996', 'Sports', 'Konami', '2', 'Soccer simulation beta', 'The peak of 16-bit soccer with expanded rosters and modes.', 'Explore early mechanics and team data in this beta version.', 'Check out the Fighting Eleven Beta on the SNES.', 'A pre-release development build. Witness the tuning of the 16-bit soccer engine and early commentator audio clips before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jim-lees-wildcats---covert-action-teams-usa', 'SNES', 'Jim Lee''s WildC.A.T.S - Covert Action Teams (USA)', '1995', 'Action', 'Beam Software', '2', 'Comic beat ''em up', 'Side-scrolling beat ''em up based on the Jim Lee comic book.', 'Stop the Daemonite invasion with the WildC.A.T.S team.', 'Battle through Jim Lee''s WildC.A.T.S on the SNES.', 'Control Spartan, Warblade, or Maul in this gritty 16-bit brawler. Features impressive comic-style art and intense melee combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jim-power---the-lost-dimension-in-3d-europe', 'SNES', 'Jim Power - The Lost Dimension in 3D (Europe)', '1993', 'Action', 'Loriciels', '1', 'Run-and-gun platformer', 'Ultra-challenging action platformer with unique 3D scrolling effects.', 'Navigate the Lost Dimension and defeat the evil Vaprak.', 'Survive Jim Power: The Lost Dimension in 3D on SNES.', 'Known for its multi-layered 16-bit parallax scrolling and punishing difficulty. Master your jumps and weapons across diverse, perspective-shifting stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jim-power---the-lost-dimension-in-3d-usa', 'SNES', 'Jim Power - The Lost Dimension in 3D (USA)', '1993', 'Action', 'Loriciels', '1', 'Run-and-gun platformer', 'Ultra-challenging action platformer with unique 3D scrolling effects.', 'Navigate the Lost Dimension and defeat the evil Vaprak.', 'Survive Jim Power: The Lost Dimension in 3D on SNES.', 'A technical marvel of the 16-bit era. Features a rocking soundtrack and visual effects that pushed the console''s limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-pro-tennis-tour-europe', 'SNES', 'Jimmy Connors Pro Tennis Tour (Europe)', '1992', 'Sports', 'Blue Sky Software', '2', 'Tennis simulation', 'Realistic tennis simulation endorsed by Jimmy Connors.', 'Climb the rankings and win the world tour.', 'Hit the court in Jimmy Connors Pro Tennis Tour on SNES.', 'Features a deep career mode and diverse court surfaces. A technical 16-bit sports title that rewards timing and tactical positioning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-pro-tennis-tour-france', 'SNES', 'Jimmy Connors Pro Tennis Tour (France)', '1992', 'Sports', 'Blue Sky Software', '2', 'Tennis simulation', 'Realistic tennis simulation endorsed by Jimmy Connors.', 'Play the professional tennis sim in French.', 'Jouez à Jimmy Connors Pro Tennis en français sur le SNES.', 'The complete 16-bit tennis experience with localized French menus. Master your serve and volley to become the world''s number one.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-pro-tennis-tour-germany', 'SNES', 'Jimmy Connors Pro Tennis Tour (Germany)', '1992', 'Sports', 'Blue Sky Software', '2', 'Tennis simulation', 'Realistic tennis simulation endorsed by Jimmy Connors.', 'Play the professional tennis sim in German.', 'Spielen Sie Jimmy Connors Pro Tennis auf Deutsch für das SNES.', 'The complete 16-bit tennis experience with localized German text. Navigate the world tour and claim the Grand Slam title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-pro-tennis-tour-japan', 'SNES', 'Jimmy Connors Pro Tennis Tour (Japan)', '1992', 'Sports', 'Blue Sky Software', '2', 'Tennis simulation', 'Realistic tennis simulation endorsed by Jimmy Connors.', 'Win the tournament in this high-quality Japanese release.', 'Experience Jimmy Connors Pro Tennis Tour on Super Famicom.', 'A faithful 16-bit simulation known for its smooth animations and challenging AI, offering a realistic take on professional tennis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-connors-pro-tennis-tour-usa', 'SNES', 'Jimmy Connors Pro Tennis Tour (USA)', '1992', 'Sports', 'Blue Sky Software', '2', 'Tennis simulation', 'Realistic tennis simulation endorsed by Jimmy Connors.', 'Climb the rankings and win the world tour.', 'Hit the court in Jimmy Connors Pro Tennis Tour on SNES.', 'Master the baseline game and special shots. A classic 16-bit sports title that balances simulation depth with accessible gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-houstons-bass-tournament-usa-usa', 'SNES', 'Jimmy Houston''s Bass Tournament U.S.A. (USA)', '1993', 'Sports', 'Data East', '1', 'Fishing simulation', 'Realistic bass fishing simulation in famous U.S. lakes.', 'Win the tournament by catching the heaviest prize bass.', 'Go fishing in Jimmy Houston''s Bass Tournament on SNES.', 'Endorsed by the pro angler. Features 16-bit lure selection, environmental physics, and a first-person perspective for hooking and reeling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen-bass-fishing-hisshouhou-in-usa-japan', 'SNES', 'Jissen Bass Fishing Hisshouhou in USA (Japan)', '1993', 'Sports', 'Naxat Soft', '1', 'Fishing simulation', 'Professional-grade bass fishing simulation with a focus on USA tours.', 'Master the American waters and claim the championship.', 'Experience Jissen Bass Fishing Hisshouhou on SNES.', 'A technical 16-bit fishing sim. Features realistic weather patterns and a wide variety of tackle options for the serious digital angler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen-kyoutei-japan', 'SNES', 'Jissen Kyoutei (Japan)', '1994', 'Sports', 'Naxat Soft', '1', 'Boat racing betting sim', 'Realistic simulation of the Japanese boat racing sport, Kyoutei.', 'Win the high-speed boat races through betting and skill.', 'Experience the intense Jissen Kyoutei on the Super Famicom.', 'A niche but deep 16-bit simulation. Manage your career, bet on races, and master the engine tuning to dominate the water circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen-pachinko-hisshouhou!-2-japan', 'SNES', 'Jissen Pachinko Hisshouhou! 2 (Japan)', '1994', 'Gambling', 'Naxat Soft', '1', 'Pachinko simulation', 'Pachinko simulation featuring professional machines and techniques.', 'Win the jackpot and learn professional parlor secrets.', 'Play Jissen Pachinko Hisshouhou! 2 on the Super Famicom.', 'Features realistic machine physics and a detailed simulation mode. A 16-bit essential for fans of authentic Japanese gambling games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen!-mahjong-shinan-japan', 'SNES', 'Jissen! Mahjong Shinan (Japan)', '1995', 'Gambling', 'Naxat Soft', '1', 'Mahjong training', 'Traditional Mahjong simulation with a focus on instruction.', 'Learn and master the art of Mahjong with expert guidance.', 'Improve your game in Jissen! Mahjong Shinan on SNES.', 'A polished 16-bit Mahjong title that includes tutorials and hint systems, making it perfect for both beginners and strategic masters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen!-pachi-slot-hisshouhou!-japan', 'SNES', 'Jissen! Pachi-Slot Hisshouhou! (Japan)', '1994', 'Gambling', 'Naxat Soft', '1', 'Slot machine simulation', 'Pachi-slot simulation featuring real-world parlor machines.', 'Master the reels and win the virtual jackpot.', 'Test your luck in Jissen! Pachi-Slot Hisshouhou! on SNES.', 'A realistic 16-bit pachi-slot experience. Features accurate reel patterns and statistical data to help players practice for real parlors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen!-pachi-slot-hisshouhou!-2-japan', 'SNES', 'Jissen! Pachi-Slot Hisshouhou! 2 (Japan)', '1995', 'Gambling', 'Naxat Soft', '1', 'Slot machine simulation', 'Sequel to the professional pachi-slot simulation series.', 'Win big at the virtual slots with new machine types.', 'Experience Jissen! Pachi-Slot Hisshouhou! 2 on the SNES.', 'Features improved 16-bit machine graphics and updated payout data, offering a more comprehensive simulation of the Japanese gambling experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen!-pachi-slot-hisshouhou!-classic-japan', 'SNES', 'Jissen! Pachi-Slot Hisshouhou! Classic (Japan)', '1996', 'Gambling', 'Naxat Soft', '1', 'Classic slot simulation', 'Classic pachi-slot collection featuring legendary parlor machines.', 'Master the vintage reels and win the championship.', 'Play Pachi-Slot Hisshouhou! Classic on the Super Famicom.', 'A nostalgic 16-bit trip through pachi-slot history. Features perfectly recreated classic machines for fans of the old-school parlor style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen!-pachi-slot-hisshouhou!-twin-japan', 'SNES', 'Jissen! Pachi-Slot Hisshouhou! Twin (Japan)', '1996', 'Gambling', 'Naxat Soft', '1', 'Slot machine simulation', 'Specialized pachi-slot simulation featuring "Twin" machines.', 'Master the double-reel mechanics to hit the big payouts.', 'Test your skills in Pachi-Slot Hisshouhou! Twin on SNES.', 'Features unique 16-bit machine logic and a high degree of realism in reel-stopping timing and parlor atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen!-pachi-slot-hisshouhou!-twin-vol-2-japan', 'SNES', 'Jissen! Pachi-Slot Hisshouhou! Twin Vol. 2 (Japan)', '1997', 'Gambling', 'Naxat Soft', '1', 'Slot machine simulation', 'Advanced pachi-slot sequel with even more twin-type machines.', 'Dominate the slots with updated machine data.', 'Experience Pachi-Slot Hisshouhou! Twin Vol. 2 on SNES.', 'The final volume of the Twin series. Offers the most refined 16-bit pachi-slot physics and a wide variety of themed machines to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jissen!-pachi-slot-hisshouhou!-yamasa-densetsu-japan', 'SNES', 'Jissen! Pachi-Slot Hisshouhou! Yamasa Densetsu (Japan)', '1997', 'Gambling', 'Naxat Soft', '1', 'Slot machine simulation', 'Pachi-slot simulation featuring the legendary Yamasa brand.', 'Master the iconic Yamasa machines and win the tournament.', 'Play the official Yamasa Densetsu on the Super Famicom.', 'A 16-bit tribute to one of Japan''s most famous slot manufacturers. Features highly accurate recreations of their most beloved parlor machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac---caveman-ninja-europe-enfrdeesitnl', 'SNES', 'Joe & Mac - Caveman Ninja (Europe) (En,Fr,De,Es,It,Nl)', '1991', 'Action', 'Data East', '2', 'Co-op platformer', 'Action-platformer featuring two heroic cavemen on a rescue mission.', 'Defeat dinosaurs and rival tribes to rescue the cavewomen.', 'Experience the prehistoric fun of Joe & Mac on the SNES.', 'A vibrant 16-bit arcade port. Play as Joe or Mac in 2-player co-op, using clubs and stone boomerangs to fight massive prehistoric bosses and rescue your village.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac---caveman-ninja-europe-enfrdeesitnl-beta', 'SNES', 'Joe & Mac - Caveman Ninja (Europe) (En,Fr,De,Es,It,Nl) (Beta)', '1991', 'Action', 'Data East', '2', 'Co-op platformer beta', 'Action-platformer featuring two heroic cavemen on a rescue mission.', 'Test early prehistoric levels and dinosaur boss encounters.', 'Check out the Joe & Mac (Beta) version on the SNES.', 'An early 16-bit development build. Explore initial level layouts and mechanical adjustments before the final multi-language European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac---tatakae-genshijin-japan', 'SNES', 'Joe & Mac - Tatakae Genshijin (Japan)', '1991', 'Action', 'Data East', '2', 'Co-op platformer', 'Action-platformer featuring two heroic cavemen on a rescue mission.', 'Rescue the kidnapped maidens in the original Japanese version.', 'Play Joe & Mac: Tatakae Genshijin on the Super Famicom.', 'The foundational 16-bit Japanese release. Known for its colorful graphics, humorous animations, and challenging arcade-style platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac-usa', 'SNES', 'Joe & Mac (USA)', '1991', 'Action', 'Data East', '2', 'Co-op platformer', 'Action-platformer featuring two heroic cavemen on a rescue mission.', 'Defeat dinosaurs and rival tribes to rescue the cavewomen.', 'Join the caveman chaos in Joe & Mac for the Super Nintendo.', 'Master the power-up system to throw fire, electricity, and stone. A high-energy 16-bit classic that defines the prehistoric action genre on the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac-2---lost-in-the-tropics-usa', 'SNES', 'Joe & Mac 2 - Lost in the Tropics (USA)', '1994', 'Action', 'Data East', '2', 'Platform adventure', 'Adventure-platformer with RPG elements and world-map exploration.', 'Recover the village crown and rebuild your prehistoric home.', 'Discover Joe & Mac 2: Lost in the Tropics on the SNES.', 'An expanded 16-bit sequel. Features a hub world, the ability to get married, and more diverse gameplay including secret areas and upgraded weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac-2---lost-in-the-tropics-usa-beta', 'SNES', 'Joe & Mac 2 - Lost in the Tropics (USA) (Beta)', '1994', 'Action', 'Data East', '2', 'Platform adventure beta', 'Adventure-platformer with RPG elements and world-map exploration.', 'Explore early tropical levels and new RPG mechanics.', 'Check out Joe & Mac 2: Lost in the Tropics Beta on SNES.', 'A pre-release version of the 16-bit sequel. Witness the early implementation of the world map and the evolution of the iconic caveman sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac-3---lost-in-the-tropics-europe-enfrde', 'SNES', 'Joe & Mac 3 - Lost in the Tropics (Europe) (En,Fr,De)', '1995', 'Action', 'Data East', '2', 'Platform adventure', 'Adventure-platformer with RPG elements, known as Joe & Mac 2 in USA.', 'Recover the stolen crown in the localized European version.', 'Play the epic Joe & Mac 3 on the Super Nintendo.', 'The European release of the sequel (marketed as the 3rd entry). Features multilingual support and the same polished 16-bit prehistoric exploration and combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joe-&-mac-3---lost-in-the-tropics-europe-enfrde-beta', 'SNES', 'Joe & Mac 3 - Lost in the Tropics (Europe) (En,Fr,De) (Beta)', '1995', 'Action', 'Data East', '2', 'Platform adventure beta', 'Adventure-platformer with RPG elements, known as Joe & Mac 2 in USA.', 'Test the localized European build and tropical stages.', 'Check out the Joe & Mac 3 (Beta) version on the SNES.', 'An early 16-bit European development build. Features preliminary translations and level balancing for the final multilingual release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-93-europe', 'SNES', 'John Madden Football ''93 (Europe)', '1992', 'Sports', 'Park Place Productions', '2', 'American football', 'Realistic American football simulation with updated 1993 rosters.', 'Lead your team to the Super Bowl with Madden''s expert strategy.', 'Kick off the action in John Madden Football ''93 on SNES.', 'The definitive early 16-bit football sim. Features improved animations, more plays, and the signature "Madden" style that revolutionized sports gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-93-usa', 'SNES', 'John Madden Football ''93 (USA)', '1992', 'Sports', 'Park Place Productions', '2', 'American football', 'Realistic American football simulation with updated 1993 rosters.', 'Win the championship in the premier 16-bit football sim.', 'Experience John Madden Football ''93 on the Super Nintendo.', 'Features realistic field conditions and detailed playbooks. A benchmark 16-bit sports title that rewards tactical planning and quick reflexes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-93-usa-rev-a', 'SNES', 'John Madden Football ''93 (USA) (Rev A)', '1992', 'Sports', 'Park Place Productions', '2', 'American football', 'Realistic American football simulation with updated 1993 rosters.', 'Win the league in this refined 16-bit revision.', 'Play the polished John Madden Football ''93 (Rev A) on SNES.', 'An updated Japanese revision that improves player AI and fixes minor 16-bit logic errors for a more consistent professional football experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-madden-football-usa', 'SNES', 'John Madden Football (USA)', '1990', 'Sports', 'Park Place Productions', '2', 'American football', 'The foundational entry of the legendary football simulation series.', 'Master the gridiron and win the first Madden championship.', 'Play the original John Madden Football on the Super Nintendo.', 'The game that started the 16-bit football revolution. Introduces deep tactical playcalling and the iconic perspective that defined the series for years.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jojo-no-kimyou-na-bouken-japan', 'SNES', 'JoJo no Kimyou na Bouken (Japan)', '1993', 'Fighting', 'Cobra Team', '2', 'Anime fighting', 'Turn-based RPG based on the iconic Stardust Crusaders arc.', 'Travel to Egypt to defeat DIO and save Jotaro''s mother.', 'Join the adventure in JoJo no Kimyou na Bouken on SNES.', 'A unique 16-bit JRPG featuring the "Stand" combat system. Explore beautifully drawn locations and battle iconic villains in a story faithful to the legendary manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('joushou-mahjong-tenpai-japan', 'SNES', 'Joushou Mahjong Tenpai (Japan)', '1994', 'Gambling', 'Naxat Soft', '1', 'Mahjong simulation', 'Traditional Mahjong simulation with a focus on professional play.', 'Defeat the Mahjong masters and claim the Tenpai title.', 'Master the tiles in Joushou Mahjong Tenpai on SNES.', 'Features a clean 16-bit interface and challenging AI. A serious simulation of professional Japanese Mahjong strategy for fans of the traditional board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jra-pat---wide-baken-taiyou-japan-tjdj', 'SNES', 'JRA PAT - Wide Baken Taiyou (Japan) (TJDJ)', '1996', 'Gambling', 'Naxat Soft', '1', 'Horse betting simulation', 'Digital horse racing betting tool for the JRA professional league.', 'Analyze race data and place virtual bets on international tracks.', 'Use the JRA PAT betting simulation on the Super Famicom.', 'A specialized 16-bit software used for race tracking and data analysis, reflecting the deep horse racing culture in Japan during the 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jra-pat---wide-baken-taiyou-japan-tjej', 'SNES', 'JRA PAT - Wide Baken Taiyou (Japan) (TJEJ)', '1996', 'Gambling', 'Naxat Soft', '1', 'Horse betting simulation', 'Digital horse racing betting tool with updated wide-bet data.', 'Master the odds in this specialized horse racing utility.', 'Explore JRA PAT: Wide Baken Taiyou on the Super Famicom.', 'Features detailed 16-bit statistics and betting patterns for professional horse racing enthusiasts looking to simulate real-world parlor tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jra-pat-japan-tjaj', 'SNES', 'JRA PAT (Japan) (TJAJ)', '1995', 'Gambling', 'Naxat Soft', '1', 'Horse betting simulation', 'Foundational horse racing data utility for the Japan Racing Assoc.', 'Track professional horse data and simulate race outcomes.', 'Experience the original JRA PAT on the Super Famicom.', 'The initial version of the data-heavy 16-bit racing sim. Offers a comprehensive look at the statistics and breeding records of the JRA era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jra-pat-japan-tjbj', 'SNES', 'JRA PAT (Japan) (TJBJ)', '1995', 'Gambling', 'Naxat Soft', '1', 'Horse betting simulation', 'Updated horse racing data utility with refined interface and data.', 'Improve your betting strategy with the latest JRA statistics.', 'Try JRA PAT (TJBJ) for the Super Famicom.', 'A revised 16-bit utility featuring minor data updates and improved navigation for a more efficient race-tracking experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd-europe', 'SNES', 'Judge Dredd (Europe)', '1995', 'Action', 'Probe Software', '1', 'Action platformer', 'Side-scrolling action shooter based on the cult classic film.', 'Clean up the streets of Mega-City One as the law.', 'I am the law in Judge Dredd for the Super Nintendo.', 'Blast through criminal gangs in a gritty 16-bit world. Use your Lawgiver pistol with multiple ammo types to defeat the Dark Judges and restore order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd-japan', 'SNES', 'Judge Dredd (Japan)', '1995', 'Action', 'Probe Software', '1', 'Action platformer', 'Side-scrolling action shooter based on the cult classic film.', 'Defeat the rogue judges in the original Japanese version.', 'Play Judge Dredd on the Super Famicom for intense action.', 'Features detailed 16-bit sprites and challenging platforming combat. Navigate through futuristic slums and high-tech towers to deliver justice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd-usa', 'SNES', 'Judge Dredd (USA)', '1995', 'Action', 'Probe Software', '1', 'Action platformer', 'Side-scrolling action shooter based on the cult classic film.', 'Clean up the streets of Mega-City One as the law.', 'I am the law in Judge Dredd for the Super Nintendo.', 'Master the use of heat-seeking, armor-piercing, and ricochet rounds. A high-octane 16-bit action title that captures the dark atmosphere of the comics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd-usa-sample', 'SNES', 'Judge Dredd (USA) (Sample)', '1995', 'Action', 'Probe Software', '1', 'Action platformer prototype', 'Side-scrolling action shooter based on the cult classic film.', 'Explore early Mega-City One level designs and weapons.', 'Check out the Judge Dredd (Sample) version on the SNES.', 'A rare 16-bit development sample. Experience the core mechanics and early visual style of the futuristic shooter before its final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumbo-ozaki-no-hole-in-one-japan', 'SNES', 'Jumbo Ozaki no Hole in One (Japan)', '1993', 'Sports', 'Nintendo', '1', 'Golf simulation', 'Realistic golf simulation endorsed by the legendary Jumbo Ozaki.', 'Master the 18 holes and claim the tournament trophy.', 'Tee off in Jumbo Ozaki no Hole in One on Super Famicom.', 'Features professional-grade 16-bit golf physics and course design. Navigate through hazards and wind in this technical simulation of pro-level golf.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumpin-derby-japan', 'SNES', 'Jumpin'' Derby (Japan)', '1993', 'Sports', 'Nintendo', '1', 'Horse racing betting', 'Horse racing simulation focused on breeding and training.', 'Breed the ultimate champion horse and win the Derby.', 'Train your champion in Jumpin'' Derby for the Super Famicom.', 'A deep 16-bit management sim. Balance your horse''s diet, training schedule, and race performance to dominate the professional racing world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-europe', 'SNES', 'Jungle Book, The (Europe)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Action platformer', 'Action-platformer based on the classic Disney animated film.', 'Navigate the jungle and defeat Shere Khan to reach the man-village.', 'Relive the magic in The Jungle Book for the Super Nintendo.', 'Features incredible 16-bit animation and vibrant backgrounds. Swing on vines, collect fruit, and encounter iconic characters like Baloo and Bagheera.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-japan', 'SNES', 'Jungle Book, The (Japan)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Action platformer', 'Action-platformer based on the classic Disney animated film.', 'Experience Mowgli''s adventure in the Japanese version.', 'Play The Jungle Book on the Super Famicom.', 'The original 16-bit Japanese release. Known for its high difficulty and polished Capcom-style platforming mechanics that remain a fan favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-usa', 'SNES', 'Jungle Book, The (USA)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Action platformer', 'Action-platformer based on the classic Disney animated film.', 'Navigate the jungle and defeat Shere Khan to reach the man-village.', 'Relive the magic in The Jungle Book for the Super Nintendo.', 'Master the projectile and swinging mechanics. A visually stunning 16-bit adventure that captures the charm and spirit of the Disney masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-book-the-usa-beta', 'SNES', 'Jungle Book, The (USA) (Beta)', '1994', 'Platformer', 'Virgin Interactive', '1', 'Action platformer beta', 'Action-platformer based on the classic Disney animated film.', 'Explore early jungle levels and character animations.', 'Check out The Jungle Book (Beta) version on the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of Mowgli''s movement and the incredible detail of the animated jungle world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-no-ouja-taa-chan---sekaimanyuu-daikakutou-no-maki-japan', 'SNES', 'Jungle no Ouja Taa-chan - Sekaimanyuu Daikakutou no Maki (Japan)', '1994', 'Fighting', 'Bandai', '2', 'Anime brawler', 'Action-platformer based on the humorous jungle manga and anime.', 'Defeat rival fighters in a worldwide tournament to save the jungle.', 'Join the wacky fun in Jungle no Ouja Taa-chan on SNES.', 'A vibrant 16-bit title featuring Tar-chan. Use wild combat moves and animal-assisted abilities in this colorful and humorous action-platformer inspired by the hit series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-strike-europe', 'SNES', 'Jungle Strike (Europe)', '1993', 'Action', 'Electronic Arts', '1', 'Isometric action', 'Isometric helicopter combat and rescue simulation.', 'Complete diverse jungle missions to stop a nuclear threat.', 'Pilot the chopper in Jungle Strike for the Super Nintendo.', 'The sequel to Desert Strike. Master the 16-bit controls of the Comanche helicopter, motorcycles, and hovercrafts across massive, destructible environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-strike-japan', 'SNES', 'Jungle Strike (Japan)', '1993', 'Action', 'Electronic Arts', '1', 'Isometric action', 'Isometric helicopter combat and rescue simulation.', 'Complete covert jungle operations in the Japanese version.', 'Play Jungle Strike on the Super Famicom for intense action.', 'Experience the high-stakes 16-bit flight simulation. Manage fuel, armor, and ammunition while navigating complex maps to rescue hostages and destroy key targets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-strike-usa', 'SNES', 'Jungle Strike (USA)', '1993', 'Action', 'Electronic Arts', '1', 'Isometric action', 'Isometric helicopter combat and rescue simulation.', 'Complete diverse jungle missions to stop a nuclear threat.', 'Pilot the chopper in Jungle Strike for the Super Nintendo.', 'Master the strategic 16-bit aerial combat. Balance firepower with careful navigation to dismantle a terrorist organization in various tropical and urban settings.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jungle-wars-2---kodai-mahou-ateimos-no-nazo-japan', 'SNES', 'Jungle Wars 2 - Kodai Mahou Ateimos no Nazo (Japan)', '1993', 'RPG', 'Atelier Double', '1', 'Tactical fantasy RPG', 'Turn-based RPG set in a prehistoric world with modern elements.', 'Solve the mystery of the ancient magic Ateimos.', 'Explore the unique world of Jungle Wars 2 on SNES.', 'A creative 16-bit JRPG. Lead a party of young warriors and animals through a colorful world that blends tribal settings with mysterious high-tech ruins.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-europe', 'SNES', 'Jurassic Park (Europe)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Restore power to the park and escape the dinosaur threat.', 'Survive the island in Jurassic Park for the Super Nintendo.', 'A cinematic 16-bit experience. Explore the island in top-down view and enter facilities for tense first-person segments while avoiding Velociraptors and the T-Rex.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-europe-beta', 'SNES', 'Jurassic Park (Europe) (Beta)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure beta', 'Hybrid top-down and first-person action-adventure game.', 'Test early dinosaur AI and facility interior designs.', 'Check out the Jurassic Park (Beta) version on the SNES.', 'A pre-release 16-bit development build. Witness the evolution of the 3D-style interior rendering and the balancing of the survival-horror elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-france', 'SNES', 'Jurassic Park (France)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Survive the dinosaur outbreak in the French version.', 'Jouez à Jurassic Park en français sur la Super Nintendo.', 'The complete 16-bit survival adventure with localized French text. Navigate Isla Nublar and outsmart the prehistoric predators.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-germany', 'SNES', 'Jurassic Park (Germany)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Survive the dinosaur outbreak in the German version.', 'Spielen Sie Jurassic Park auf Deutsch für das SNES.', 'The complete 16-bit survival adventure with localized German text. Manage your resources and navigate the dangerous park to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-italy', 'SNES', 'Jurassic Park (Italy)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Survive the dinosaur outbreak in the Italian version.', 'Gioca a Jurassic Park in italiano sulla Super Nintendo.', 'The complete 16-bit survival adventure with localized Italian text. Experience the tension of the prehistoric island in your own language.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-japan', 'SNES', 'Jurassic Park (Japan)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Survive the dinosaur outbreak in the Japanese version.', 'Experience Jurassic Park on the Super Famicom.', 'The original 16-bit Japanese release. Features the iconic soundtrack and the groundbreaking mix of exploration and pseudo-3D action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-spain', 'SNES', 'Jurassic Park (Spain)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Survive the dinosaur outbreak in the Spanish version.', 'Juega a Jurassic Park en español para la Super Nintendo.', 'The complete 16-bit survival adventure with localized Spanish text. One of the most atmospheric and ambitious titles on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-usa', 'SNES', 'Jurassic Park (USA)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Restore power to the park and escape the dinosaur threat.', 'Survive the island in Jurassic Park for the Super Nintendo.', 'Master the use of the motion sensor and diverse weaponry. A landmark 16-bit title known for its high difficulty and immersive atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-usa-rev-a', 'SNES', 'Jurassic Park (USA) (Rev A)', '1993', 'Action', 'Ocean Software', '1', 'Action adventure', 'Hybrid top-down and first-person action-adventure game.', 'Survive the island in this refined 16-bit revision.', 'Play the polished Jurassic Park (Rev A) on the SNES.', 'An updated North American revision fixing minor technical glitches and improving the stability of the 3D-style interior segments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-ii---the-chaos-continues-europe-enfrdeit', 'SNES', 'Jurassic Park II - The Chaos Continues (Europe) (En,Fr,De,It)', '1994', 'Action', 'Ocean Software', '1', 'Run and gun', 'Side-scrolling run-and-gun action shooter.', 'Stop InGen''s rivals from stealing dinosaur technology.', 'Return to the island in Jurassic Park II for the SNES.', 'A radical departure from the first game. Engage in high-octane 16-bit shooting action with multiple weapon types and intense boss fights against massive dinosaurs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-ii---the-chaos-continues-usa-enfrdeit', 'SNES', 'Jurassic Park II - The Chaos Continues (USA) (En,Fr,De,It)', '1994', 'Action', 'Ocean Software', '1', 'Run and gun', 'Side-scrolling run-and-gun action shooter.', 'Stop InGen''s rivals from stealing dinosaur technology.', 'Return to the island in Jurassic Park II for the SNES.', 'Features impressive 16-bit sprites and 2-player co-op action. Fight through urban and jungle environments in a gritty mission to restore order.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-ii---the-chaos-continues-usa-enfrdeit-beta', 'SNES', 'Jurassic Park II - The Chaos Continues (USA) (En,Fr,De,It) (Beta)', '1994', 'Action', 'Ocean Software', '1', 'Run and gun beta', 'Side-scrolling run-and-gun action shooter.', 'Explore early weapon balancing and dinosaur enemy placements.', 'Check out Jurassic Park II (Beta) on the Super Nintendo.', 'A pre-release 16-bit development build. Discover how the platforming and shooting mechanics were refined before the final North American launch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league-task-force-europe', 'SNES', 'Justice League Task Force (Europe)', '1995', 'Fighting', 'Rare', '2', 'Comic fighting', 'One-on-one fighting game featuring DC Comics superheroes.', 'Defeat Darkseid and his army of clones to save Earth.', 'Battle as your favorite hero in Justice League Task Force.', 'Control icons like Batman, Superman, and Wonder Woman in this 16-bit fighter. Features unique special moves and detailed character backgrounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league-task-force-japan', 'SNES', 'Justice League Task Force (Japan)', '1995', 'Fighting', 'Rare', '2', 'Comic fighting', 'One-on-one fighting game featuring DC Comics superheroes.', 'Save the world in the original Japanese version.', 'Experience Justice League Task Force on the Super Famicom.', 'The Japanese release of the DC crossover. Features 16-bit combat with a story mode that takes you through iconic comic book locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league-task-force-usa', 'SNES', 'Justice League Task Force (USA)', '1995', 'Fighting', 'Rare', '2', 'Comic fighting', 'One-on-one fighting game featuring DC Comics superheroes.', 'Defeat Darkseid and his army of clones to save Earth.', 'Battle as your favorite hero in Justice League Task Force.', 'Master the combat styles of the World''s Greatest Heroes. A challenging 16-bit fighter with a distinct comic book art style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league-task-force-usa-beta', 'SNES', 'Justice League Task Force (USA) (Beta)', '1995', 'Fighting', 'Rare', '2', 'Comic fighting beta', 'One-on-one fighting game featuring DC Comics superheroes.', 'Test early character balance and combat animations.', 'Check out the Justice League Task Force Beta on SNES.', 'A pre-release 16-bit development build. Witness the early frame-data for the heroes and the evolution of the special attack visual effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jutei-senki-japan', 'SNES', 'Jutei Senki (Japan)', '1993', 'RPG', 'NCS', '1', 'Tactical RPG', 'Tactical turn-based RPG with a sci-fi and bio-organic theme.', 'Lead the "Jutei" warriors to defend the planet from invaders.', 'Experience the strategic Jutei Senki on the Super Famicom.', 'Developed by Enix. Features a unique 16-bit aesthetic where units are organic machines. Master the complex tactical grid and unit strengths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jutei-senki-japan-en-by-aeon-genesis-v10', 'SNES', 'Jutei Senki (Japan) [En by Aeon Genesis v1.0]', '1993', 'RPG', 'NCS', '1', 'Tactical RPG translated', 'Tactical turn-based RPG with a full English fan translation.', 'Lead the organic army with a full English translation.', 'Play Jutei Senki in English on the Super Nintendo.', 'The Aeon Genesis translation makes this deep 16-bit strategy game accessible. Experience the unique sci-fi narrative and tactical depth in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jwp-joshi-pro-wrestling---pure-wrestle-queens-japan', 'SNES', 'JWP Joshi Pro Wrestling - Pure Wrestle Queens (Japan)', '1994', 'Sports', 'JWP', '2', 'Professional wrestling', 'All-female professional wrestling simulation with RPG elements.', 'Win the JWP championship and lead your wrestler to the top.', 'Enter the ring in Pure Wrestle Queens for the Super Famicom.', 'Features real-life wrestlers from the JWP promotion. A technical 16-bit wrestling game that balances ring action with management and character growth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kh-rummenigges-player-manager-germany', 'SNES', 'K.H. Rummenigge''s Player Manager (Germany)', '1994', 'Sports', 'Software 2000', '1', 'Soccer management', 'In-depth soccer management simulation for the German market.', 'Lead your team to the Bundesliga title through expert coaching.', 'Master the pitch in Player Manager for the Super Nintendo.', 'Endorsed by Karl-Heinz Rummenigge. Features deep 16-bit management menus, player transfers, and a tactical simulation of professional football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kh-rummenigges-player-manager-germany-sample', 'SNES', 'K.H. Rummenigge''s Player Manager (Germany) (Sample)', '1994', 'Sports', 'Software 2000', '1', 'Soccer management sample', 'In-depth soccer management simulation for the German market.', 'Explore the early management menus and database.', 'Check out the Player Manager Sample on the SNES.', 'A rare look at the game''s production. Witness the development of the 16-bit management engine and the player statistical tracking system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kablooey-usa', 'SNES', 'Kablooey (USA)', '1991', 'Puzzle', 'Kemco', '1', 'Arcade puzzle', 'Puzzle game where you must clear mines and traps.', 'Safely detonate explosives to clear each 16-bit level.', 'Solve the explosive puzzles in Kablooey for the SNES.', 'Known as "Bombuzal" in other regions. Features a variety of perspectives and increasingly complex logic puzzles that reward careful planning and timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabuki-chou-reach-mahjong-tonpuusen-japan', 'SNES', 'Kabuki Chou Reach Mahjong Tonpuusen (Japan)', '1994', 'Tabletop', 'SETA', '1', 'Mahjong', 'Traditional Mahjong simulation set in the famous Kabuki district.', 'Defeat the local masters and win the high-stakes tournament.', 'Play Kabuki Chou Reach Mahjong on the Super Famicom.', 'A polished 16-bit Mahjong title featuring realistic AI and a distinct urban atmosphere. Perfect for fans of the traditional Japanese tile game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kabuki-rocks-japan', 'SNES', 'Kabuki Rocks (Japan)', '1994', 'RPG', 'Atelier Double', '1', 'Fantasy RPG', 'Theatrical turn-based RPG with a Kabuki and Rock-and-Roll theme.', 'Stop the evil forces using the power of music and drama.', 'Experience the unique Kabuki Rocks on the Super Famicom.', 'One of the most creative 16-bit JRPGs. Features a rock-inspired soundtrack, theater-themed combat, and a vibrant art style that blends traditional Japan with modern flair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kachou-shima-kousaku-japan', 'SNES', 'Kachou Shima Kousaku (Japan)', '1995', 'Simulation', 'Kaneko', '1', 'Business simulation', 'Digital board game/simulation based on the famous salaryman manga.', 'Climb the corporate ladder and manage your business career.', 'Experience the life of Shima Kousaku on the Super Famicom.', 'A unique 16-bit "life sim." Navigate corporate politics, make business decisions, and follow the story of the most famous salaryman in Japanese fiction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kagakusha-harley-no-haran-banjou-japan', 'SNES', 'Kagakusha Harley no Haran Banjou (Japan)', '1993', 'Adventure', 'ASCII', '1', 'Point-and-click adventure', 'Action-platformer where you play as a tiny hero in a giant world.', 'Navigate a massive house and retrieve your shrinking machine.', 'Experience Harley no Haran Banjou on the Super Famicom.', 'The Japanese version of Harley''s Humongous Adventure. Use chemical weapons and gadgets to survive 16-bit kitchen and toy room stages from a miniature perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaite-tsukutte-asoberu-dezaemon-japan', 'SNES', 'Kaite Tsukutte Asoberu Dezaemon (Japan)', '1991', 'Utility', 'ASCII', '1', 'Game creation tool', 'Vertical shoot ''em up with a built-in game creation engine.', 'Create your own shooter or play the pre-made sample levels.', 'Build your own shooter in Dezaemon for the Super Famicom.', 'A groundbreaking 16-bit utility. Design your own ships, enemies, and music, or play the included high-quality shmup developed by Athena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakinoki-shougi-for-super-famicom-japan', 'SNES', 'Kakinoki Shougi for Super Famicom (Japan)', '1995', 'Tabletop', 'ASCII', '2', 'Shogi', 'Traditional Shogi (Japanese Chess) simulation with professional AI.', 'Defeat the Kakinoki AI and master the art of Shogi strategy.', 'Play the technical Kakinoki Shougi on the Super Famicom.', 'A serious 16-bit Shogi simulation. Features multiple analysis tools, difficulty levels, and a clean interface for serious practitioners of the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamaitachi-no-yoru-japan', 'SNES', 'Kamaitachi no Yoru (Japan)', '1994', 'Adventure', 'Chunsoft', '1', 'Sound novel', 'Sound novel/mystery adventure with silhouette-based characters.', 'Solve the murder mystery at a snowy mountain lodge.', 'Experience the legendary Kamaitachi no Yoru on SNES.', 'A masterpiece of 16-bit storytelling. Use logic and intuition to make choices that lead to over 40 different endings in this atmospheric thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-japan', 'SNES', 'Kamen Rider (Japan)', '1993', 'Action', 'Bandai', '1', 'Hero action', 'Side-scrolling beat ''em up based on the iconic tokusatsu hero.', 'Defeat the Shocker organization and their mutant cyborgs.', 'Fight for justice in Kamen Rider for the Super Famicom.', 'Features intense 16-bit brawling action. Control Rider 1 or Rider 2, master the "Rider Kick," and battle classic kaijin bosses from the TV series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-sd---shutsugeki!!-rider-machine-japan', 'SNES', 'Kamen Rider SD - Shutsugeki!! Rider Machine (Japan)', '1994', 'Action', 'Bandai', '1', 'Chibi action', 'Isometric combat racing game featuring SD (Super Deformed) Riders.', 'Race through dangerous tracks and defeat the Shocker minions.', 'Speed away in Kamen Rider SD for the Super Famicom.', 'A unique 16-bit racer. Use combat moves and special items to knock rivals off their bikes while navigating hazard-filled stages across Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('karura-ou-japan', 'SNES', 'Karura Ou (Japan)', '1994', 'RPG', 'Taito', '1', 'Fantasy RPG', 'Side-scrolling action-platformer with a dark mythological theme.', 'Stop the evil sorcerer and restore balance to the world.', 'Discover the intense Karura Ou on the Super Famicom.', 'Known as Skyblazer in the West. Features fluid 16-bit movement, wall-climbing mechanics, and spectacular magical attacks in a vibrant fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kashiwagi-shigetaka-no-top-water-bassing-japan', 'SNES', 'Kashiwagi Shigetaka no Top Water Bassing (Japan)', '1994', 'Sports', 'VAP', '1', 'Fishing simulation', 'Realistic fishing simulation focused on top-water techniques.', 'Catch the biggest prize bass using surface lures and strategy.', 'Master top-water fishing in Kashiwagi Shigetaka on SNES.', 'A specialized 16-bit fishing sim. Focuses on the precise movement of top-water lures to attract bass in beautifully rendered Japanese lake environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kats-run---zen-nihon-k-car-senshuken-japan', 'SNES', 'Kat''s Run - Zen-Nihon K-Car Senshuken (Japan)', '1993', 'Racing', 'Atlus', '1', 'Compact car racing', 'Isometric racing game featuring Japanese "Kei" micro-cars.', 'Win the K-Car championship through tight turns and speed.', 'Race tiny cars in Kat''s Run for the Super Famicom.', 'A quirky 16-bit racer. Choose from a variety of micro-cars with unique handling and race through urban and rural Japanese tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('katou-hifumi-kudan---shougi-club-japan', 'SNES', 'Katou Hifumi Kudan - Shougi Club (Japan)', '1995', 'Tabletop', 'Nichibutsu', '2', 'Shogi', 'Professional Shogi simulation featuring master Hifumi Katou.', 'Challenge the "Legend" Hifumi Katou and improve your rank.', 'Play the elite Katou Hifumi Shougi on the Super Famicom.', 'Offers high-level 16-bit AI and detailed tutorials based on Katou''s professional games. Perfect for players looking to study master-level Shogi.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawa-no-nushi-tsuri-2-japan', 'SNES', 'Kawa no Nushi Tsuri 2 (Japan)', '1994', 'Sports', 'Pack-In-Video', '1', 'Fishing simulation', 'RPG-style fishing simulation with open-world exploration.', 'Catch the "King of the River" and help your family.', 'Experience the charming Kawa no Nushi Tsuri 2 on SNES.', 'Known as Legend of the River King. Blends 16-bit RPG progression with a deep fishing engine. Level up your gear and explore diverse nature maps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawasaki-caribbean-challenge-usa', 'SNES', 'Kawasaki Caribbean Challenge (USA)', '1994', 'Racing', 'Absolute', '1', 'Motorcycle racing', 'Multi-sport racing game featuring jet skis and ATVs.', 'Win the Caribbean championship across water and land.', 'Race through paradise in Kawasaki Caribbean Challenge.', 'A fast-paced 16-bit racer that uses Mode 7 for scaling. Switch between different Kawasaki vehicles and master various terrains to claim victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawasaki-superbike-challenge-europe', 'SNES', 'Kawasaki Superbike Challenge (Europe)', '1995', 'Racing', 'Lankhor', '1', 'Motorcycle racing', 'High-speed motorcycle racing simulation using Mode 7.', 'Win the Superbike world title on authentic international tracks.', 'Feel the speed in Kawasaki Superbike Challenge for SNES.', 'Features a realistic cockpit view and impressive 16-bit scaling. Lean into corners and manage your speed to dominate the professional racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawasaki-superbike-challenge-usa', 'SNES', 'Kawasaki Superbike Challenge (USA)', '1995', 'Racing', 'Lankhor', '1', 'Motorcycle racing', 'High-speed motorcycle racing simulation using Mode 7.', 'Win the Superbike world title on authentic international tracks.', 'Feel the speed in Kawasaki Superbike Challenge for SNES.', 'Navigate through weather changes and challenging curves. A technical 16-bit racer that captures the intensity of professional bike racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keeper-japan', 'SNES', 'Keeper (Japan)', '1994', 'Action', 'KID', '1', 'Arcade action', 'Falling-block puzzle game with a unique movement mechanic.', 'Clear the board by pushing and matching colored blocks.', 'Solve the clever puzzles in Keeper for the Super Famicom.', 'A creative 16-bit puzzler. Instead of falling blocks, you move a cursor to slide tiles across the grid, creating chains to clear the stage before time runs out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiba-eight-special-japan', 'SNES', 'Keiba Eight Special (Japan)', '1993', 'Simulation', 'Namco', '1', 'Horse racing simulation', 'Horse racing data and betting simulation for the Eight Special series.', 'Predict race winners and manage your virtual betting bank.', 'Master the turf in Keiba Eight Special on Super Famicom.', 'A data-heavy 16-bit utility for horse racing fans. Features real horse stats, track conditions, and betting simulations to test your gambling strategies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiba-eight-special-japan-rev-a', 'SNES', 'Keiba Eight Special (Japan) (Rev A)', '1993', 'Simulation', 'Namco', '1', 'Horse racing simulation', 'Horse racing data and betting simulation (Refined Version).', 'Analyze race data and win big in this updated simulation.', 'Play the polished Keiba Eight Special (Rev A) on SNES.', 'The updated 16-bit Japanese revision featuring minor data corrections and improved menu navigation for horse racing enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keiba-eight-special-2-japan', 'SNES', 'Keiba Eight Special 2 (Japan)', '1994', 'Simulation', 'Namco', '1', 'Horse racing simulation', 'Advanced horse racing simulation with updated data and visuals.', 'Become a betting pro with the latest JRA racing statistics.', 'Experience Keiba Eight Special 2 on the Super Famicom.', 'Features a more comprehensive database of horses and jockeys. A deep 16-bit management and betting sim for the serious horse racing fan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ken-griffey-jr-presents-major-league-baseball-usa', 'SNES', 'Ken Griffey Jr. Presents Major League Baseball (USA)', '1994', 'Sports', 'Rare', '2', 'Baseball simulation', 'Arcade-style baseball simulation with real MLB teams and players.', 'Win the World Series with the help of Ken Griffey Jr.', 'Hit a home run in Ken Griffey Jr. Presents MLB on SNES.', 'Known for its fast gameplay and "real" feel despite the arcade style. Features a full 16-bit season mode and the iconic swing of The Kid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ken-griffey-jrs-winning-run-usa', 'SNES', 'Ken Griffey Jr.''s Winning Run (USA)', '1996', 'Sports', 'Rare', '2', 'Baseball arcade', 'High-performance baseball sim with advanced graphics and physics.', 'Claim the pennant in this technically impressive sequel.', 'Experience Ken Griffey Jr.''s Winning Run on the SNES.', 'Developed by Rare. Features "ACM" rendered 16-bit graphics and incredibly fluid player animations. One of the best-looking and playing sports titles on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kendo-rage-usa', 'SNES', 'Kendo Rage (USA)', '1993', 'Action', 'Jaleco', '1', 'Run and gun', 'Side-scrolling action-platformer with a humorous anime style.', 'Win the Kendo tournament and defeat the school''s monsters.', 'Battle with spirit in Kendo Rage for the Super Nintendo.', 'Control Maki as she uses her magical kendo stick to fight bizarre 16-bit enemies. A colorful and charming adventure with a distinct Japanese flair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kentou-ou-world-champion-japan', 'SNES', 'Kentou Ou World Champion (Japan)', '1993', 'Fighting', 'Bandai', '2', 'Boxing fighting', 'Boxing simulation with a focus on career management and timing.', 'Climb the ranks and win the World Champion belt.', 'Enter the ring in Kentou Ou World Champion on SNES.', 'Known as TKO Super Championship Boxing. Features large 16-bit sprites and a strategic approach to boxing where stamina management is key to victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kenyuu-densetsu-yaiba-japan', 'SNES', 'Kenyuu Densetsu Yaiba (Japan)', '1993', 'Action', 'Atelier Double', '1', 'Anime action', 'Action-RPG based on the popular manga by Gosho Aoyama.', 'Defeat the Onimaru clan and master the legendary swords.', 'Join the adventure in Kenyuu Densetsu Yaiba on SNES.', 'A vibrant 16-bit action title. Use Yaiba''s diverse elemental orbs to solve puzzles and defeat enemies in a story full of humor and martial arts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kero-kero-keroppi-no-bouken-nikki---nemureru-mori-no-keroriinu-japan', 'SNES', 'Kero Kero Keroppi no Bouken Nikki - Nemureru Mori no Keroriinu (Japan)', '1994', 'Adventure', 'Character Soft', '1', 'Children adventure', 'Educational adventure game featuring the Sanrio character Keroppi.', 'Explore the forest and help Keroppi''s friends in this diary.', 'Join Keroppi''s Adventure Nikki on the Super Famicom.', 'A charming 16-bit title designed for younger players. Solve simple puzzles and play mini-games in the colorful and friendly world of Sanrio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kessen!-dokapon-oukoku-iv---densetsu-no-yuusha-tachi-japan', 'SNES', 'Kessen! Dokapon Oukoku IV - Densetsu no Yuusha-tachi (Japan)', '1994', 'RPG', 'Asmik Ace', '4', 'Party RPG', 'Hybrid board game and turn-based RPG for up to four players.', 'Become the richest hero and save the Dokapon Kingdom.', 'Play the chaotic Dokapon Oukoku IV on Super Famicom.', 'A unique 16-bit "friendship-ending" game. Compete against others to complete quests, buy towns, and sabotage rivals in a vibrant RPG world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kevin-keegans-player-manager-europe', 'SNES', 'Kevin Keegan''s Player Manager (Europe)', '1992', 'Sports', 'Anco', '1', 'Soccer management', 'Soccer management simulation with a focus on the English league.', 'Lead your club to the top flight as a player-manager.', 'Master the dugout in Kevin Keegan''s Player Manager on SNES.', 'Features deep 16-bit management menus and a simulation engine for matches. Balance team finances, transfers, and tactics to win the league.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-off-europe', 'SNES', 'Kick Off (Europe)', '1992', 'Sports', 'Anco', '2', 'Soccer simulation', 'Fast-paced soccer game with a top-down perspective.', 'Outscore your opponent in high-speed, arcade-style matches.', 'Kick off the action in Kick Off for the Super Nintendo.', 'Known for its challenging "loose ball" physics. A 16-bit classic that requires high precision and skill to control the ball and score goals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-off-3---european-challenge-europe-beta', 'SNES', 'Kick Off 3 - European Challenge (Europe) (Beta)', '1994', 'Sports', 'Anco', '2', 'Soccer simulation beta', 'Fast-paced soccer game featuring European international teams.', 'Test the early mechanics of the third entry in the series.', 'Check out the Kick Off 3 Beta on the Super Nintendo.', 'A pre-release 16-bit development build. Discover initial ball physics and menu layouts for this fast-moving European soccer simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kick-off-3---european-challenge-europe-enfrdeesit', 'SNES', 'Kick Off 3 - European Challenge (Europe) (En,Fr,De,Es,It)', '1994', 'Sports', 'Anco', '2', 'Soccer simulation', 'Fast-paced soccer game featuring European international teams.', 'Win the European Challenge with updated tactics and speed.', 'Experience Kick Off 3 for the Super Nintendo.', 'A refined 16-bit soccer experience. Features improved controls over the original and a variety of international tournaments for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-klown-in-crazy-chase-europe', 'SNES', 'Kid Klown in Crazy Chase (Europe)', '1992', 'Action', 'Kemco', '1', 'Auto-scrolling action', 'Unique side-scrolling "run-and-tumble" puzzle-platformer.', 'Chase the princess while avoiding Blackie''s dangerous traps.', 'Join the chase in Kid Klown in Crazy Chase on the SNES.', 'A visually stunning 16-bit title. Run "into" the screen in a pseudo-3D perspective, dodging obstacles in a vibrant, cartoon-inspired world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-klown-in-crazy-chase-usa', 'SNES', 'Kid Klown in Crazy Chase (USA)', '1992', 'Action', 'Kemco', '1', 'Auto-scrolling action', 'Unique side-scrolling "run-and-tumble" puzzle-platformer.', 'Chase the princess while avoiding Blackie''s dangerous traps.', 'Join the chase in Kid Klown in Crazy Chase on the SNES.', 'A visually stunning 16-bit title. Run "into" the screen in a pseudo-3D perspective, dodging obstacles in a vibrant, cartoon-inspired world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-klown-no-crazy-chase-japan', 'SNES', 'Kid Klown no Crazy Chase (Japan)', '1992', 'Action', 'Kemco', '1', 'Auto-scrolling action', 'Unique side-scrolling "run-and-tumble" puzzle-platformer.', 'Chase the princess in the original Japanese version.', 'Play Kid Klown no Crazy Chase on the Super Famicom.', 'The original 16-bit release featuring the same high-energy isometric platforming and slapstick humor that made the series a cult favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-butouden-g-gundam-japan-en-by-aeon-genesis-v10-~mobile-fighter-g-gundam', 'SNES', 'Kidou Butouden G Gundam (Japan) [En by Aeon Genesis v1.0] (~Mobile Fighter G Gundam)', '1994', 'Fighting', 'Bandai', '2', 'Anime fighting', 'One-on-one fighting game based on the G Gundam anime.', 'Win the Gundam Fight tournament in full English.', 'Play G Gundam in English on the Super Nintendo.', 'The Aeon Genesis translation allows you to follow the hot-blooded story of Domon Kasshu. Features fast-paced 16-bit combat with massive mechs and special moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-butouden-g-gundam-japan', 'SNES', 'Kidou Butouden G-Gundam (Japan)', '1994', 'Fighting', 'Bandai', '2', 'Anime fighting', 'One-on-one fighting game based on the G Gundam anime.', 'Defeat rival Gundams and claim the title of champion.', 'Experience Mobile Fighter G Gundam on Super Famicom.', 'A rare Gundam fighter that plays like a traditional 2D brawler. Features large 16-bit sprites, intense special attacks, and a faithful roster from the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-gundam---cross-dimension-0079-japan', 'SNES', 'Kidou Senshi Gundam - Cross Dimension 0079 (Japan)', '1995', 'Action', 'Bandai', '1', 'Mecha action', 'Tactical turn-based RPG with original side-stories.', 'Lead the Federation to victory in this classic Gundam epic.', 'Explore Gundam Cross Dimension 0079 on Super Famicom.', 'Features a mix of strategic map movement and 16-bit turn-based combat. Includes an original side-story set during the One Year War with beautiful pixel art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-gundam---cross-dimension-0079-japan-en-by-aeon-genesis-v10-~mobile-suit-gundam---cross-dimension-0079', 'SNES', 'Kidou Senshi Gundam - Cross Dimension 0079 (Japan) [En by Aeon Genesis v1.0] (~Mobile Suit Gundam - Cross Dimension 0079)', '1995', 'Action', 'Bandai', '1', 'Mecha action translated', 'Tactical turn-based RPG with a full English fan translation.', 'Experience the Gundam One Year War with English text.', 'Play Gundam Cross Dimension 0079 in English on SNES.', 'The Aeon Genesis translation makes this deep 16-bit tactical RPG accessible, allowing fans to enjoy the complex narrative and mecha customization in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-gundam-f91---formula-senki-0122-japan', 'SNES', 'Kidou Senshi Gundam F91 - Formula Senki 0122 (Japan)', '1991', 'Action', 'Bandai', '1', 'Mecha action', 'Strategy-RPG featuring the F91 Gundam and Formula project.', 'Defeat the Crossbone Vanguard across planetary missions.', 'Experience Gundam F91: Formula Senki on Super Famicom.', 'A cinematic 16-bit strategy game. Command your mobile suits in turn-based battles that utilize large, detailed sprites and dramatic combat animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-v-gundam-japan-en-by-twilight-v10-~mobile-suit-v-gundam', 'SNES', 'Kidou Senshi V Gundam (Japan) [En by Twilight v1.0] (~Mobile Suit V Gundam)', '1993', 'Action', 'Bandai', '1', 'Mecha action translated', 'Side-scrolling action-platformer featuring V Gundam.', 'Complete the Victory Gundam story with English text.', 'Play Mobile Suit V Gundam in English on the SNES.', 'The Twilight translation helps navigate this high-speed 16-bit action title. Control the Victory Gundam through hazardous levels and epic boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-v-gundam-japan', 'SNES', 'Kidou Senshi V-Gundam (Japan)', '1993', 'Action', 'Bandai', '1', 'Mecha action', 'Side-scrolling action-platformer featuring V Gundam.', 'Defeat the Zanscare Empire in this high-speed action game.', 'Experience Mobile Suit V Gundam on the Super Famicom.', 'A fast-paced 16-bit action game. Master the use of the beam saber and rifle while navigating through beautifully drawn space and colony environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-z-gundam---away-to-the-newtype-japan', 'SNES', 'Kidou Senshi Z-Gundam - Away to the Newtype (Japan)', '1992', 'Action', 'Bandai', '1', 'Mecha action', 'Tactical strategy game with a focus on Newtype abilities.', 'Guide the AEUG to victory in the Gryps Conflict.', 'Master strategy in Z-Gundam: Away to the Newtype.', 'A deep 16-bit tactical sim. Features an original branching narrative where your strategic choices determine the fate of the Z-Gundam cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-soukou-dion-japan', 'SNES', 'Kidou Soukou Dion (Japan)', '1993', 'Action', 'NCS', '1', 'Mecha action', 'Vertical-scrolling shoot ''em up featuring a transformable mech.', 'Blast through enemy lines and stop the mechanical threat.', 'Pilot the mech in Kidou Soukou Dion on Super Famicom.', 'Known as "Hyperaze." A high-intensity 16-bit shooter where you can transform your craft to adapt to different combat situations and enemy patterns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidoukeisatsu-patlabor-japan', 'SNES', 'Kidoukeisatsu Patlabor (Japan)', '1992', 'Action', 'Bandai', '1', 'Mecha police action', 'Visual novel and adventure game based on the Patlabor series.', 'Solve crimes and pilot the Labor in this cinematic adventure.', 'Experience Kidoukeisatsu Patlabor on the Super Famicom.', 'Features a deep 16-bit narrative focusing on the Special Vehicle Section 2. Solve mysteries through dialogue and engage in strategic Labor combat sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kigurumi-daibouken---dream-maze-japan', 'SNES', 'Kigurumi Daibouken - Dream Maze (Japan)', '1991', 'Adventure', 'Sigma', '1', 'Puzzle adventure', 'Surreal first-person dungeon crawler with a maze theme.', 'Navigate the dream maze and solve its bizarre puzzles.', 'Explore the quirky Kigurumi Daibouken on Super Famicom.', 'A unique 16-bit RPG where characters wear mascot costumes. Features a colorful art style and turn-based combat in a world filled with dreams and humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiki-kaikai---nazo-no-kuro-manteau-japan', 'SNES', 'Kiki Kaikai - Nazo no Kuro Manteau (Japan)', '1992', 'Action', 'Taito', '2', 'Arcade action', 'Top-down run-and-gun shooter set in ancient Japan.', 'Defeat the Black Mantle and save the seven fortune gods.', 'Play Kiki Kaikai (Pocky & Rocky) on the Super Famicom.', 'A 16-bit masterpiece. Use talismans and magic to fight through waves of yokai in beautiful environments. Features incredible co-op gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiki-kaikai---tsukiyo-soushi-japan', 'SNES', 'Kiki Kaikai - Tsukiyo Soushi (Japan)', '1994', 'Action', 'Taito', '2', 'Arcade action', 'Top-down run-and-gun shooter with improved graphics and modes.', 'Embark on a new quest to save the lunar princess.', 'Experience Kiki Kaikai: Tsukiyo Soushi on Super Famicom.', 'The sequel known as Pocky & Rocky 2. Features refined 16-bit graphics, a variety of AI partners, and even more detailed Japanese folklore-inspired stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kikou-keisatsu-metal-jack-japan', 'SNES', 'Kikou Keisatsu Metal Jack (Japan)', '1992', 'Action', 'Bandai', '1', 'Anime action', 'Side-scrolling action-platformer based on the Metal Jack anime.', 'Defeat the criminal underworld using cybernetic armor.', 'Join the fight in Metal Jack for the Super Famicom.', 'Control the Jackal team in this 16-bit action title. Features armor transformations and intense combat against mechanical and biological threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kikuni-masahiko-no-jantoushi-doraou-japan', 'SNES', 'Kikuni Masahiko no Jantoushi Doraou (Japan)', '1992', 'Mahjong', 'ASCII', '1', 'Mahjong', 'Humorous Mahjong simulation featuring quirky characters.', 'Win the tournament in this comedy-focused Mahjong game.', 'Play Jantoushi Doraou on the Super Famicom.', 'Based on the manga by Masahiko Kikuni. Features 16-bit Mahjong strategy mixed with hilarious character reactions and a distinct underground gambling vibe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kikuni-masahiko-no-jantoushi-doraou-2---kigyou-senshi-japan', 'SNES', 'Kikuni Masahiko no Jantoushi Doraou 2 - Kigyou Senshi (Japan)', '1993', 'Mahjong', 'ASCII', '1', 'Mahjong', 'Professional Mahjong simulation sequel with a corporate theme.', 'Climb the corporate ladder by winning Mahjong matches.', 'Experience Jantoushi Doraou 2 on the Super Famicom.', 'Combines 16-bit Mahjong gameplay with a business management simulation. Defeat rival salarymen to expand your company and reach the top.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct---eyedol-edition-deluxe', 'SNES', 'Killer Instinct - Eyedol Edition Deluxe', '1995', 'Fighting', 'Rare', '2', 'Arcade fighting', 'Modified version of the fighting classic with boss characters.', 'Control the final boss Eyedol in this deluxe fan edition.', 'Play Killer Instinct: Eyedol Edition on the SNES.', 'A specialized 16-bit mod that allows players to use the final boss and features various balance tweaks for the ultimate competitive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-europe', 'SNES', 'Killer Instinct (Europe)', '1995', 'Fighting', 'Rare', '2', 'Arcade fighting', 'High-tech fighting game with pre-rendered 3D graphics.', 'Defeat the UltraTech tournament fighters and stop Cinder.', 'Master the combos in Killer Instinct for the SNES.', 'A technical marvel for the 16-bit era. Features the famous "Combo" system, "Ultra" finishes, and an incredible soundtrack that pushed the system to its limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-usa', 'SNES', 'Killer Instinct (USA)', '1995', 'Fighting', 'Rare', '2', 'Arcade fighting', 'High-tech fighting game with pre-rendered 3D graphics.', 'Defeat the UltraTech tournament fighters and stop Cinder.', 'Master the combos in Killer Instinct for the SNES.', 'Experience the definitive 16-bit brawler. Control a roster of diverse characters from Glacius to Jago in high-speed, high-fidelity combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-usa-beta', 'SNES', 'Killer Instinct (USA) (Beta)', '1995', 'Fighting', 'Rare', '2', 'Arcade fighting beta', 'High-tech fighting game with pre-rendered 3D graphics.', 'Test early character balance and the combo breaker engine.', 'Check out the Killer Instinct Beta on the SNES.', 'A pre-release 16-bit development build. Witness the fine-tuning of the complex combo mechanics and early sprite rendering techniques.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-usa-rev-a', 'SNES', 'Killer Instinct (USA) (Rev A)', '1995', 'Fighting', 'Rare', '2', 'Arcade fighting', 'High-tech fighting game with pre-rendered 3D graphics.', 'Win the tournament in this refined 16-bit revision.', 'Play the polished Killer Instinct (Rev A) on the SNES.', 'An updated North American revision that fixes minor gameplay glitches and improves the stability of the 16-bit combo system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-msu-1', 'SNES', 'Killer Instinct MSU-1', '1995', 'Fighting', 'Rare', '2', 'Enhanced audio hack', 'Enhanced version of the fighter with CD-quality audio.', 'Experience Killer Instinct with a high-fidelity soundtrack.', 'Play Killer Instinct MSU-1 on the Super Nintendo.', 'Utilizes the MSU-1 chip to bring the original arcade''s high-quality music and audio to the 16-bit console for the most immersive experience possible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kindai-mahjong-special-japan', 'SNES', 'Kindai Mahjong Special (Japan)', '1993', 'Mahjong', 'Namco', '1', 'Mahjong', 'Professional Mahjong simulation with updated rules and data.', 'Win the special tournament and prove your strategic skill.', 'Play Kindai Mahjong Special on the Super Famicom.', 'Features realistic AI and a focus on the modern rules of the game. A polished 16-bit title for serious fans of Japanese Mahjong.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-arthur-&-the-knights-of-justice-usa', 'SNES', 'King Arthur & The Knights of Justice (USA)', '1992', 'Action', 'LJN', '1', 'Cartoon action', 'Action-adventure based on the animated series and toys.', 'Lead the Knights of Justice to save King Arthur from Morgana.', 'Join King Arthur & The Knights of Justice on SNES.', 'A top-down 16-bit adventure developed by Enix. Manage your team of knights, solve environmental puzzles, and engage in real-time combat in Camelot.');